insert into public.sense_usages (id,sense_id,domain_id,example_en,example_tr,collocations,family,synonyms,antonyms,confusables,other_meanings_tr,tone_tags,status) values ('1bfaffe8-25b5-5236-86a1-f0d9e8c3049e','f70a2fc3-0c0e-5ae1-8249-6441801a2ca3','yds','A large proportion of students work part-time.','Öğrencilerin büyük bir kısmı yarı zamanlı çalışıyor.',array[]::text[],'["proportional (s.) orantılı"]'::jsonb,array[]::text[],array[]::text[],'[]'::jsonb,null,array['Akademik']::text[],'draft');
insert into public.sense_usages (id,sense_id,domain_id,example_en,example_tr,collocations,family,synonyms,antonyms,confusables,other_meanings_tr,tone_tags,status) values ('e40940f3-4a25-5b79-9fa8-5cb75f666f08','a8b6c3ee-a2ef-547d-9b40-0b103416e08f','yds','Exports fell slightly in May.','İhracat mayısta biraz düştü.',array[]::text[],'[]'::jsonb,array[]::text[],array['sharply','dramatically']::text[],'[]'::jsonb,null,array['Akademik']::text[],'draft');
insert into public.sense_usages (id,sense_id,domain_id,example_en,example_tr,collocations,family,synonyms,antonyms,confusables,other_meanings_tr,tone_tags,status) values ('ac39591c-bb84-5713-b496-48dc21b35d6c','d0f204e4-a8f0-5452-a39e-e273817b988a','yds','Overall, the economy grew by 3%.','Genel olarak ekonomi %3 büyüdü.',array[]::text[],'[]'::jsonb,array[]::text[],array[]::text[],'[]'::jsonb,null,array['Akademik']::text[],'draft');
insert into public.sense_usages (id,sense_id,domain_id,example_en,example_tr,collocations,family,synonyms,antonyms,confusables,other_meanings_tr,tone_tags,status) values ('219b9d85-84d9-51fa-8fd6-bf0ee8667f0f','931d8393-f6da-5b56-8db1-40d3a6f8057e','yds','Life expectancy has increased over the last decade.','Ortalama yaşam süresi son on yılda arttı.',array[]::text[],'[]'::jsonb,array[]::text[],array[]::text[],'[]'::jsonb,null,array['Akademik']::text[],'draft');
insert into public.sense_usages (id,sense_id,domain_id,example_en,example_tr,collocations,family,synonyms,antonyms,confusables,other_meanings_tr,tone_tags,status) values ('04345685-a454-5112-b8dd-38d3363c2a82','46493bdd-217e-50c9-87c1-bfa14d4e0fd0','yds','After years of growth, sales began to level off.','Yıllarca süren büyümenin ardından satışlar sabitlenmeye başladı.',array[]::text[],'[]'::jsonb,array['stabilize']::text[],array[]::text[],'[]'::jsonb,null,array['Akademik']::text[],'draft');
insert into public.sense_usages (id,sense_id,domain_id,example_en,example_tr,collocations,family,synonyms,antonyms,confusables,other_meanings_tr,tone_tags,status) values ('e5d57eff-54fc-5a29-b785-e3764e53f363','2d7f5524-0066-5835-8edf-ffef56a8da3a','yds','According to official figures, two million people moved abroad.','Resmî rakamlara göre iki milyon kişi yurt dışına taşındı.',array[]::text[],'[]'::jsonb,array[]::text[],array[]::text[],'[]'::jsonb,'“Şekil” veya “kişi, figür” anlamlarına da gelir.',array['Akademik']::text[],'draft');
insert into public.sense_usages (id,sense_id,domain_id,example_en,example_tr,collocations,family,synonyms,antonyms,confusables,other_meanings_tr,tone_tags,status) values ('0aef4aab-4b2c-5d5e-8d85-8c1227680c76','fcc28a46-e917-5bef-ad4e-54438a15e663','yds','The hypothesis was supported by the data.','Hipotez veriler tarafından desteklendi.',array[]::text[],'["hypothetical (s.) varsayımsal","hypothesize (f.) varsaymak"]'::jsonb,array[]::text[],array[]::text[],'[]'::jsonb,null,array['Akademik']::text[],'draft');
insert into public.sense_usages (id,sense_id,domain_id,example_en,example_tr,collocations,family,synonyms,antonyms,confusables,other_meanings_tr,tone_tags,status) values ('b208abd9-eae6-5576-ace4-76b311db8a20','f6ddbe39-c22c-5a98-a90d-bf6c6b029070','yds','The findings suggest that sleep affects memory.','Bulgular uykunun hafızayı etkilediğini düşündürüyor.',array['key findings','research findings']::text[],'[]'::jsonb,array[]::text[],array[]::text[],'[]'::jsonb,null,array['Akademik']::text[],'draft');
insert into public.sense_usages (id,sense_id,domain_id,example_en,example_tr,collocations,family,synonyms,antonyms,confusables,other_meanings_tr,tone_tags,status) values ('e26dbe0d-c2d4-5b6b-a7ba-4456ab8bd8dc','9e7b2570-945b-53f8-8f1f-1cdf95ce8c8c','yds','Each participant completed a short questionnaire.','Her katılımcı kısa bir anket doldurdu.',array[]::text[],'["participate (f.) katılmak","participation (i.) katılım"]'::jsonb,array[]::text[],array[]::text[],'[]'::jsonb,null,array['Akademik']::text[],'draft');
insert into public.sense_usages (id,sense_id,domain_id,example_en,example_tr,collocations,family,synonyms,antonyms,confusables,other_meanings_tr,tone_tags,status) values ('1563e6b5-43f7-54b2-8b9a-e037d54b9065','d79f2e4f-54ec-53b7-b005-726f754ffabd','yds','There is little evidence that the drug works.','İlacın işe yaradığına dair çok az kanıt var.',array['strong evidence','evidence for/that']::text[],'["evident (s.) açık, belli"]'::jsonb,array[]::text[],array[]::text[],'[]'::jsonb,null,array['Akademik']::text[],'draft');
insert into public.sense_usages (id,sense_id,domain_id,example_en,example_tr,collocations,family,synonyms,antonyms,confusables,other_meanings_tr,tone_tags,status) values ('8d6eeb8a-38bf-5da2-b436-be5871c36a4b','3f622930-6c70-5b48-ab85-5ead423ba766','yds','The study was conducted in three countries.','Çalışma üç ülkede yürütüldü.',array['conduct a study','conduct research']::text[],'[]'::jsonb,array[]::text[],array[]::text[],'[]'::jsonb,'İsim olarak “davranış” demektir.',array['Akademik']::text[],'draft');
insert into public.sense_usages (id,sense_id,domain_id,example_en,example_tr,collocations,family,synonyms,antonyms,confusables,other_meanings_tr,tone_tags,status) values ('b76dadfb-f4f1-50ea-906b-4fd1492c7297','82b656db-c292-59ea-9a73-50a8191e70fd','yds','The results indicate a strong link between diet and health.','Sonuçlar beslenme ile sağlık arasında güçlü bir bağlantıya işaret ediyor.',array[]::text[],'["indicator (i.) gösterge","indication (i.) belirti"]'::jsonb,array[]::text[],array[]::text[],'[]'::jsonb,null,array['Akademik']::text[],'draft');
insert into public.sense_usages (id,sense_id,domain_id,example_en,example_tr,collocations,family,synonyms,antonyms,confusables,other_meanings_tr,tone_tags,status) values ('85de3d17-fa21-55e4-80e6-9cf09cee4c63','978657b1-18f1-5439-9edc-7b1098c3418a','yds','According to a recent survey, most students study at night.','Yakın tarihli bir ankete göre öğrencilerin çoğu gece ders çalışıyor.',array['conduct a survey','survey results']::text[],'[]'::jsonb,array[]::text[],array[]::text[],'[]'::jsonb,null,array['Akademik']::text[],'draft');
insert into public.sense_usages (id,sense_id,domain_id,example_en,example_tr,collocations,family,synonyms,antonyms,confusables,other_meanings_tr,tone_tags,status) values ('e50e658d-3bc7-5a3d-8291-162985955b95','bcac8382-cd48-5139-ad80-2914492c33ca','yds','This approach has been used in many earlier studies.','Bu yaklaşım daha önceki pek çok çalışmada kullanıldı.',array[]::text[],'[]'::jsonb,array[]::text[],array[]::text[],'[]'::jsonb,'Fiil olarak “yaklaşmak” demektir.',array['Akademik']::text[],'draft');
insert into public.sense_usages (id,sense_id,domain_id,example_en,example_tr,collocations,family,synonyms,antonyms,confusables,other_meanings_tr,tone_tags,status) values ('8ec48d5c-bffe-56f7-b7d8-c0d0deef9b22','efd81d60-5b6d-57f9-95bb-404f514432be','yds','The researchers collected data from 2,000 households.','Araştırmacılar 2.000 haneden veri topladı.',array['collect data','data analysis']::text[],'[]'::jsonb,array[]::text[],array[]::text[],'[]'::jsonb,null,array['Akademik']::text[],'draft');
insert into public.sense_usages (id,sense_id,domain_id,example_en,example_tr,collocations,family,synonyms,antonyms,confusables,other_meanings_tr,tone_tags,status) values ('68c8b41a-0687-5a9e-9cff-3f7e881f6aed','e6499df2-aeb6-5329-a327-a6e8d0c45cf7','yds','One limitation of the study is its small sample.','Çalışmanın bir kısıtlılığı küçük örneklemidir.',array[]::text[],'["limit (f./i.) sınırlamak; sınır","limited (s.) sınırlı"]'::jsonb,array[]::text[],array[]::text[],'[]'::jsonb,null,array['Akademik']::text[],'draft');
insert into public.sense_usages (id,sense_id,domain_id,example_en,example_tr,collocations,family,synonyms,antonyms,confusables,other_meanings_tr,tone_tags,status) values ('f25d068d-def7-5b17-9b3d-ae01299668de','44cbad2a-c1ed-5b63-8eb1-9dbaf4b45b4a','yds','These measurements are not reliable enough.','Bu ölçümler yeterince güvenilir değil.',array[]::text[],'["reliability (i.) güvenilirlik","rely on (f.) güvenmek"]'::jsonb,array[]::text[],array[]::text[],'[]'::jsonb,null,array['Akademik']::text[],'draft');
insert into public.sense_usages (id,sense_id,domain_id,example_en,example_tr,collocations,family,synonyms,antonyms,confusables,other_meanings_tr,tone_tags,status) values ('b69c8a5c-50de-50c1-a298-8abe9470eaf6','e21ef95c-96c1-586a-b315-f688dbc94eed','yds','Unlike previous studies, this one used real patients.','Önceki çalışmaların aksine bu çalışmada gerçek hastalar kullanıldı.',array[]::text[],'[]'::jsonb,array['earlier','prior']::text[],array[]::text[],'[]'::jsonb,null,array['Akademik']::text[],'draft');
insert into public.sense_usages (id,sense_id,domain_id,example_en,example_tr,collocations,family,synonyms,antonyms,confusables,other_meanings_tr,tone_tags,status) values ('96f3419f-9b20-5b9a-8464-3cc3180f8724','fe4be65d-1549-52ca-8d5e-98212524a420','yds','Some scientists claim that the effect is temporary.','Bazı bilim insanları etkinin geçici olduğunu iddia ediyor.',array[]::text[],'["claim (i.) iddia"]'::jsonb,array[]::text[],array[]::text[],'[]'::jsonb,null,array['Akademik']::text[],'draft');
insert into public.sense_usages (id,sense_id,domain_id,example_en,example_tr,collocations,family,synonyms,antonyms,confusables,other_meanings_tr,tone_tags,status) values ('679c3c3e-ee4f-5ced-9726-149751b8ff4e','4decaa75-6671-5a3e-927d-7e611c4d4897','yds','We analyzed the results using statistical software.','Sonuçları istatistik yazılımı kullanarak analiz ettik.',array[]::text[],'["analysis (i.) analiz","analyst (i.) analist"]'::jsonb,array[]::text[],array[]::text[],'[]'::jsonb,null,array['Akademik']::text[],'draft');
insert into public.sense_usages (id,sense_id,domain_id,example_en,example_tr,collocations,family,synonyms,antonyms,confusables,other_meanings_tr,tone_tags,status) values ('f499bfbd-9eab-54c7-93a8-5f70defaa97d','dfe5e4fc-2cdd-55b4-b56f-433e86344a89','yds','There is a strong correlation between income and education.','Gelir ile eğitim arasında güçlü bir ilişki var.',array[]::text[],'[]'::jsonb,array[]::text[],array[]::text[],'[{"word":"causation","note_tr":"Nedensellik demektir; korelasyon nedensellik anlamına gelmez."}]'::jsonb,null,array['Akademik']::text[],'draft');
insert into public.sense_usages (id,sense_id,domain_id,example_en,example_tr,collocations,family,synonyms,antonyms,confusables,other_meanings_tr,tone_tags,status) values ('642befe9-8465-573b-80c3-8d94b1467044','ad3bcf03-80be-5f83-8e54-e1318097cb23','yds','The main objective of this study is to measure stress levels.','Bu çalışmanın temel amacı stres düzeylerini ölçmektir.',array[]::text[],'[]'::jsonb,array['aim','goal']::text[],array[]::text[],'[]'::jsonb,'Sıfat olarak “nesnel” demektir.',array['Akademik']::text[],'draft');
insert into public.sense_usages (id,sense_id,domain_id,example_en,example_tr,collocations,family,synonyms,antonyms,confusables,other_meanings_tr,tone_tags,status) values ('0e7a6d4a-1f69-5285-bad8-04f10da07fe7','4ce690a8-4170-5a91-889b-5975251a8cd3','yds','The sample was small; thus, the results cannot be generalized.','Örneklem küçüktü; bu nedenle sonuçlar genellenemez.',array[]::text[],'[]'::jsonb,array['therefore','hence']::text[],array[]::text[],'[]'::jsonb,null,array['Akademik']::text[],'draft');
insert into public.sense_usages (id,sense_id,domain_id,example_en,example_tr,collocations,family,synonyms,antonyms,confusables,other_meanings_tr,tone_tags,status) values ('5ea51d98-9cd5-5f93-af92-1f3da5c182ed','7732b903-863c-529b-b19b-3196754846c1','yds','About 60% of respondents said they felt stressed at work.','Yanıt verenlerin yaklaşık %60''ı işte stresli hissettiğini söyledi.',array[]::text[],'["respond (f.) yanıt vermek"]'::jsonb,array[]::text[],array[]::text[],'[]'::jsonb,null,array['Akademik']::text[],'draft');
insert into public.sense_usages (id,sense_id,domain_id,example_en,example_tr,collocations,family,synonyms,antonyms,confusables,other_meanings_tr,tone_tags,status) values ('b74a107b-f349-55f1-a9fc-8d7f2da46eea','e532d3e3-fe0f-57eb-9a29-e5c28e42d1b4','yds','The new study confirms earlier results.','Yeni çalışma önceki sonuçları doğruluyor.',array[]::text[],'["confirmation (i.) doğrulama"]'::jsonb,array[]::text[],array[]::text[],'[]'::jsonb,null,array['Akademik']::text[],'draft');
insert into public.sense_usages (id,sense_id,domain_id,example_en,example_tr,collocations,family,synonyms,antonyms,confusables,other_meanings_tr,tone_tags,status) values ('fd261873-c042-5ce6-b6e9-fa06ff6a47fb','62b658e6-7a76-5416-8fe9-60a010aecf87','yds','The study shows a clear trend toward online learning.','Çalışma çevrim içi öğrenmeye yönelik açık bir eğilim gösteriyor.',array['a growing trend','trend toward']::text[],'[]'::jsonb,array[]::text[],array[]::text[],'[]'::jsonb,null,array['Akademik']::text[],'draft');
insert into public.grammar_notes (id,slug,title_tr,short_tr,long_tr,examples,status) values ('3bf15cc6-24b0-5ade-bd72-578e2cc35706','first-conditional','First conditional (olası koşul)','Gelecekte olası bir durum ve sonucu için If + geniş zaman, will + yalın fiil kullanılır: If we add a fan, the temperature will drop.','If''li kısımda will kullanılmaz: If it will rain yanlıştır. Sonuç kısmında can, might, should da gelebilir: If the part arrives today, we can finish tomorrow. unless = if not: Unless we fix it, the line will stop.','[{"en":"If we use a thicker cable, it won''t overheat.","tr":"Daha kalın bir kablo kullanırsak aşırı ısınmaz."},{"en":"If the part arrives today, we can finish tomorrow.","tr":"Parça bugün gelirse yarın bitirebiliriz."},{"en":"Unless we inspect it, we won''t find the crack.","tr":"Muayene etmezsek çatlağı bulamayız."}]'::jsonb,'draft');
insert into public.grammar_notes (id,slug,title_tr,short_tr,long_tr,examples,status) values ('9279b596-fe91-567a-9d51-125884641a4b','suggestions-recommend','suggest ve recommend ile öneri','suggest/recommend + -ing ya da suggest/recommend + that + özne + yalın fiil kullanılır: We recommend using a filter. I suggest that we test it again.','suggest/recommend + kişi + to + fiil yanlıştır: I suggest you to test yanlış; doğrusu I suggest (that) you test it. Seçenek sunmak için One option is to … / Another option is to … kullanılır. Resmî raporlarda: It is recommended that …','[{"en":"We recommend replacing the filter every month.","tr":"Filtrenin her ay değiştirilmesini öneriyoruz."},{"en":"I suggest that we stop the line now.","tr":"Hattı şimdi durdurmamızı öneriyorum."},{"en":"Another option is to buy a new pump.","tr":"Bir diğer seçenek yeni bir pompa almak."}]'::jsonb,'draft');
insert into public.grammar_notes (id,slug,title_tr,short_tr,long_tr,examples,status) values ('456ec5da-d7b5-550b-9e0c-056b23139658','comparatives','Karşılaştırma (comparatives)','Kısa sıfatlar -er ve than alır: lighter than. Uzun sıfatlarda more kullanılır: more efficient than.','Düzensiz biçimler: good → better, bad → worse. Farkın büyüklüğü: much / far / slightly + -er: much lighter, slightly heavier. Eşitlik: as … as: as strong as steel. Kat: twice as heavy as. En üstünlük: the lightest, the most efficient. “more heavier” gibi çift karşılaştırma yanlıştır.','[{"en":"The new motor is more efficient than the old one.","tr":"Yeni motor eskisinden daha verimli."},{"en":"Aluminum is much lighter than steel.","tr":"Alüminyum çelikten çok daha hafif."},{"en":"This part is twice as heavy as that one.","tr":"Bu parça ötekinin iki katı ağır."}]'::jsonb,'draft');
insert into public.grammar_notes (id,slug,title_tr,short_tr,long_tr,examples,status) values ('d5774794-79d5-5598-b2ee-b28a68901a09','measurements-numbers','Ölçü ve sayıları söyleme','Boyut: 60 by 120 cm (altmışa yüz yirmi). Ondalık ayırıcı noktadır ve “point” diye okunur: 0.05 = zero point zero five.','Binlik ayırıcı virgüldür: 1,000. ± “plus or minus” diye okunur. Birim çoğulu: 2 kilograms; sıfat olarak tekil: a 2-kilogram part. Oranlar “per” ile: 30 liters per minute. Aralık: from −20 to 60 degrees Celsius. up to = -e kadar (üst sınır).','[{"en":"The plate measures 200 by 300 mm.","tr":"Plaka 200''e 300 mm boyutunda."},{"en":"The tolerance is plus or minus 0.05 mm.","tr":"Tolerans artı eksi 0,05 mm."},{"en":"The pump can deliver up to 40 liters per minute.","tr":"Pompa dakikada 40 litreye kadar basabilir."}]'::jsonb,'draft');
insert into public.grammar_notes (id,slug,title_tr,short_tr,long_tr,examples,status) values ('192debd3-9082-5b07-80a0-40d56570f67c','zero-conditional','Zero conditional (her zaman geçerli koşul)','Her zaman aynı sonucu veren durumlar için If + geniş zaman, geniş zaman kullanılır: If the pressure drops, the valve closes.','Teknik açıklamalarda ve kılavuzlarda çok yaygındır. If yerine When de kullanılabilir: When the light turns red, the system stops. Gelecekteki tek bir olası durum için first conditional kullanılır: If it rains tomorrow, we will test indoors.','[{"en":"If the temperature exceeds 100 °C, the system stops.","tr":"Sıcaklık 100 °C''yi aşarsa sistem durur."},{"en":"When you press this button, the pump starts.","tr":"Bu düğmeye bastığında pompa çalışır."},{"en":"If water gets inside, the sensor fails.","tr":"İçeri su girerse sensör arızalanır."}]'::jsonb,'draft');
insert into public.grammar_notes (id,slug,title_tr,short_tr,long_tr,examples,status) values ('0e47e1be-1f21-5acc-aab3-01552452cccd','past-passive','Geçmiş zamanda edilgen yapı','Test raporlarında işi kimin yaptığı önemli değilse was/were + fiilin 3. hâli kullanılır: The samples were tested at 20 °C.','Tekil özne: was tested; çoğul özne: were tested. Olumsuz: wasn''t measured. Soru: Was it calibrated? Yapan belirtilecekse: The test was carried out by the quality team. Raporlarda etken yapı (We tested …) da kabul edilir; edilgen daha resmî durur.','[{"en":"The samples were tested at 20 °C.","tr":"Numuneler 20 °C''de test edildi."},{"en":"The sensor was calibrated last month.","tr":"Sensör geçen ay kalibre edildi."},{"en":"Was the data recorded correctly?","tr":"Veriler doğru kaydedildi mi?"}]'::jsonb,'draft');
insert into public.grammar_notes (id,slug,title_tr,short_tr,long_tr,examples,status) values ('4a9d24f3-029d-5fcb-bf70-fa727ed9e5c5','going-to-plans','be going to ve will ile gelecek','Önceden karar verilmiş planlar için am/is/are going to + yalın fiil: I''m going to visit my parents. Konuşma anında verilen kararlar ve sözler için will: I''ll call you later.','Ayarlanmış buluşmalar için present continuous da kullanılır: I''m meeting Ayşe tomorrow. Olumsuz: I''m not going to … / I won''t … Konuşmada going to çoğu zaman “gonna” diye söylenir ama resmî yazıda kullanılmaz. will kısaltmaları: I''ll, you''ll, we''ll.','[{"en":"I''m going to clean the house on Saturday.","tr":"Cumartesi evi temizleyeceğim."},{"en":"I''ll send you the address.","tr":"Sana adresi göndereceğim."},{"en":"We''re meeting at six.","tr":"Altıda buluşuyoruz."}]'::jsonb,'draft');
insert into public.grammar_notes (id,slug,title_tr,short_tr,long_tr,examples,status) values ('7be2ff59-b822-5d17-b28c-77b5dd4bad29','frequency-adverbs','Sıklık zarfları','always, usually, often, sometimes, rarely, never ne sıklıkla yaptığını anlatır ve genelde ana fiilden önce gelir: I usually walk to work.','be fiilinden sonra gelir: I''m always tired on Mondays. Sıklık sorusu: How often do you …? Cevaplar: once a week, twice a month, every day (genelde cümle sonunda). never zaten olumsuzdur; “don''t never” denmez.','[{"en":"I usually have breakfast at eight.","tr":"Genellikle sekizde kahvaltı yaparım."},{"en":"She is never late.","tr":"O asla geç kalmaz."},{"en":"How often do you go to the gym?","tr":"Spor salonuna ne sıklıkla gidersin?"}]'::jsonb,'draft');
insert into public.grammar_notes (id,slug,title_tr,short_tr,long_tr,examples,status) values ('61191619-612d-5027-a1fe-6212fc28bc5e','present-simple','Present Simple (geniş zaman)','Alışkanlıklar, kalıcı durumlar ve genel gerçekler için kullanılır: I work at a bank. He, she, it ile fiil -s alır: She works.','Olumsuz: I don''t / She doesn''t + yalın fiil. Soru: Do you …? / Does she …? Sıklık zarfları (always, usually, often, sometimes, never) genelde fiilden önce gelir: I usually walk to work. like, know, need, want gibi durum fiilleri çoğunlukla -ing almaz.','[{"en":"I work at a small company.","tr":"Küçük bir şirkette çalışıyorum."},{"en":"She doesn''t drink coffee.","tr":"Kahve içmez."},{"en":"Do you live near here?","tr":"Buraya yakın mı oturuyorsun?"}]'::jsonb,'draft');
insert into public.grammar_notes (id,slug,title_tr,short_tr,long_tr,examples,status) values ('451cf418-a1b2-5782-8a95-8dc5c6a0b92d','to-be','to be: am / is / are','Kim olduğunu, nereli olduğunu ve nasıl hissettiğini anlatırken am/is/are kullanılır: I''m a nurse. She''s from İzmir.','I am (I''m); you, we, they are (''re); he, she, it is (''s). Olumsuz: I''m not, isn''t, aren''t. Soru: Are you a student? Is he at work? Meslekten önce a/an gelir: I''m an engineer. Sıfat + edat kalıpları çok kullanılır: good at, interested in, sure about, stuck on.','[{"en":"I''m a teacher.","tr":"Öğretmenim."},{"en":"Are you from Ankara?","tr":"Ankaralı mısın?"},{"en":"We aren''t sure about the plan.","tr":"Plandan emin değiliz."}]'::jsonb,'draft');
insert into public.grammar_notes (id,slug,title_tr,short_tr,long_tr,examples,status) values ('851477de-6cca-5819-9b94-be7428c7eb31','would-like','would like ve would you mind','Bir şey isterken I''d like + isim ya da I''d like to + fiil kibar bir yoldur: I''d like a refund. I''d like to speak to the manager.','I want daha doğrudandır; restoranda ve mağazada I''d like tercih edilir. Teklif: Would you like some tea? Çok nazik rica: Would you mind + -ing: Would you mind closing the window? Buna “No, not at all.” yanıtı “Hayır, hiç sorun değil” demektir; yani rica kabul edilmiştir.','[{"en":"I''d like the soup, please.","tr":"Çorba alayım, lütfen."},{"en":"Would you like a coffee?","tr":"Kahve ister misin?"},{"en":"Would you mind waiting a minute?","tr":"Bir dakika bekler misiniz?"}]'::jsonb,'draft');
insert into public.grammar_notes (id,slug,title_tr,short_tr,long_tr,examples,status) values ('d5daeed1-3188-5fc9-bf18-7fc0d1d582be','can-have-to','can, could ve have to','can/could yetenek, izin ve rica bildirir: Can I sit here? Could you help me? have to zorunluluk bildirir: I have to leave early.','can ve could sonrası yalın fiil gelir, “to” gelmez. could, can''den daha naziktir. have to, he/she/it ile has to olur. Olumsuzu farklıdır: don''t have to “gerek yok”, mustn''t “yasak” demektir. Sık kalıp: I can''t make it = gelemiyorum, yetişemiyorum.','[{"en":"Could I have the bill, please?","tr":"Hesabı alabilir miyim, lütfen?"},{"en":"I have to work late tonight.","tr":"Bu akşam geç saate kadar çalışmam gerekiyor."},{"en":"You don''t have to bring anything.","tr":"Bir şey getirmene gerek yok."}]'::jsonb,'draft');
insert into public.grammar_notes (id,slug,title_tr,short_tr,long_tr,examples,status) values ('a5f9d0fc-be42-50ae-afd1-5c3a477c4150','modal-suggestions-should','should ve could ile öneri','Öneri yaparken should (yapmalı) daha güçlü, could (yapabiliriz) daha yumuşaktır. Ardından fiil yalın gelir: We should add a test.','Maybe we could … / What about adding …? / Why don''t we …? kalıpları nazik öneridir. Modal fiiller ek almaz ve “to” ile kullanılmaz: should to add yanlıştır. Olumsuz: You shouldn''t merge it yet. Kod incelemesinde doğrudan emir (Change this.) yerine öneri kalıbı daha kibar durur.','[{"en":"We should add a test for this case.","tr":"Bu durum için bir test eklemeliyiz."},{"en":"Maybe we could cache the result.","tr":"Belki sonucu önbelleğe alabiliriz."},{"en":"You shouldn''t merge it before the tests pass.","tr":"Testler geçmeden birleştirmemelisin."}]'::jsonb,'draft');
insert into public.grammar_notes (id,slug,title_tr,short_tr,long_tr,examples,status) values ('65dafd22-780c-55e5-96c7-520eb58691f9','passive-voice-basics','Edilgen yapı (passive voice)','İşi kimin yaptığı önemli değilse be + fiilin 3. hâli kullanılır: The bug was fixed. This should be moved.','Zamanlara göre: is fixed (geniş), was fixed (geçmiş), has been fixed (sonuç), will be fixed (gelecek), should be fixed (gereklilik). Yapan belirtilecekse “by” kullanılır: The PR was approved by Ece. Teknik metinlerde ve raporlarda çok yaygındır.','[{"en":"The bug was fixed in version 2.4.","tr":"Hata 2.4 sürümünde düzeltildi."},{"en":"This logic should be moved to a helper.","tr":"Bu mantık bir yardımcıya taşınmalı."},{"en":"The PR was approved by two reviewers.","tr":"PR iki inceleyen tarafından onaylandı."}]'::jsonb,'draft');
insert into public.grammar_notes (id,slug,title_tr,short_tr,long_tr,examples,status) values ('6abb00b5-f7d0-5462-97e1-00928664f27f','past-simple-reporting','Past Simple ile olanı anlatma','Biten olayları anlatırken fiilin geçmiş hâli kullanılır: It crashed. I fixed it. Düzensiz fiillere dikkat: see → saw, find → found.','Olumsuz ve soru “did” ile kurulur ve fiil yalın kalır: It didn''t crash. Did it crash? Hata kayıtlarında olayların sırası verilir: First I logged in, then the page froze. Zaman belirtilmişse (yesterday, at 10 am) past simple gerekir; zaman yoksa ve sonuç şimdi önemliyse present perfect tercih edilir: I''ve fixed it.','[{"en":"The app crashed after the update.","tr":"Uygulama güncellemeden sonra çöktü."},{"en":"I didn''t see any errors in the log.","tr":"Kayıtta hiçbir hata görmedim."},{"en":"Did you restart the server?","tr":"Sunucuyu yeniden başlattın mı?"}]'::jsonb,'draft');
insert into public.grammar_notes (id,slug,title_tr,short_tr,long_tr,examples,status) values ('6a11b3cb-d93f-533d-b6d2-56af6ab35df5','present-perfect-results','Present Perfect ile sonuç bildirme','Geçmişte yapılan ama sonucu şimdi önemli olan işler için have/has + fiilin 3. hâli kullanılır: I''ve finished the tests.','Belirli bir geçmiş zaman söylenmez: I''ve fixed the bug (I''ve fixed it yesterday denmez; zaman varsa past simple: I fixed it yesterday). Soru: Have you tried restarting it? Olumsuz: We haven''t deployed yet. “already” ve “yet” sık birlikte kullanılır: I''ve already merged it. / Has QA tested it yet?','[{"en":"I''ve finished the API integration.","tr":"API entegrasyonunu bitirdim."},{"en":"Have you tried clearing the cache?","tr":"Önbelleği temizlemeyi denedin mi?"},{"en":"We haven''t released the hotfix yet.","tr":"Acil düzeltmeyi henüz yayımlamadık."}]'::jsonb,'draft');
insert into public.grammar_notes (id,slug,title_tr,short_tr,long_tr,examples,status) values ('07f46ae3-6018-5f8f-8bda-377e874ddc92','present-continuous','Present Continuous (şimdiki zaman)','Şu an ya da bu günlerde süren işler için am/is/are + fiil-ing kullanılır. Toplantıda en sık kalıp: I''m working on …','Olumlu: I''m (I am) working on the login page. Olumsuz: I''m not working on it today. Soru: Are you working on the API? Durum bildiren bazı fiiller (know, need, want) genellikle -ing almaz: I need help (I''m needing help değil). “Bu hafta, bu sprint” gibi geçici süreçler için de kullanılır: This week we''re fixing bugs.','[{"en":"I''m working on the login page.","tr":"Giriş sayfası üzerinde çalışıyorum."},{"en":"Are you working on the API today?","tr":"Bugün API üzerinde mi çalışıyorsun?"},{"en":"We aren''t adding new features this week.","tr":"Bu hafta yeni özellik eklemiyoruz."}]'::jsonb,'draft');
insert into public.grammar_notes (id,slug,title_tr,short_tr,long_tr,examples,status) values ('d5e18b4b-8396-58e1-90d3-60ff590c1767','polite-requests-could','Could you …? ile nazik istek','Bir iş arkadaşından nazikçe bir şey isterken Could you + yalın fiil kullanılır. Can you daha samimidir.','Could you review my code? (nazik) · Can you review my code? (samimi) · Would you mind reviewing my code? (daha yumuşak; mind sonrası fiil -ing alır). Could we …? biçimi ortak bir öneri veya plan değişikliği için kullanılır: Could we move the demo? Cevap verirken: Sure. / Of course. / Sorry, I can''t today.','[{"en":"Could you take a look at my pull request?","tr":"Pull request''ime bir göz atabilir misin?"},{"en":"Would you mind sharing the logs?","tr":"Kayıtları paylaşır mısın?"},{"en":"Could we move the meeting to 3 pm?","tr":"Toplantıyı saat 15''e alabilir miyiz?"}]'::jsonb,'draft');
insert into public.grammar_notes (id,slug,title_tr,short_tr,long_tr,examples,status) values ('1b0b85f6-765e-57cd-838b-8e483d2c0e86','linkers-cause-effect','Neden-sonuç bağlaçları','Neden: because + cümle; because of / due to + isim. Sonuç: so, therefore, thus, consequently, as a result. Amaç: so that + cümle.','Bağlacın ardından ne geldiğine bak: cümle mi, isim mi? because the weather was bad / because of the bad weather. therefore ve consequently genelde noktalı virgül veya noktadan sonra gelir ve ardından virgül alır. otherwise “aksi takdirde” anlamında koşullu bir sonuç bildirir.','[{"en":"Because of the strike, all trains were cancelled.","tr":"Grev yüzünden bütün trenler iptal edildi."},{"en":"The sample was small; therefore, the results are limited.","tr":"Örneklem küçüktü; bu nedenle sonuçlar sınırlı."},{"en":"He left early so that he could catch the bus.","tr":"Otobüse yetişebilmek için erken çıktı."}]'::jsonb,'draft');
insert into public.grammar_notes (id,slug,title_tr,short_tr,long_tr,examples,status) values ('18bb25a1-8990-5403-bef1-60ed86047678','linkers-contrast','Karşıtlık bağlaçları','Cümle ile: although, even though, whereas, while. İsim ile: despite, in spite of. Cümle başında bağlantı zarfı olarak: however, nevertheless, in contrast.','although + cümle: Although it rained, … / despite + isim veya -ing: Despite the rain, … / Despite being tired, … “despite of” yanlıştır. whereas iki durumu karşılaştırır: A is cheap, whereas B is expensive. however ve nevertheless noktalı virgül veya noktadan sonra gelir. Paragraf sorularında karşıtlık bağlacından sonra çoğu zaman yazarın asıl görüşü gelir.','[{"en":"Although it was late, they continued working.","tr":"Geç olmasına rağmen çalışmaya devam ettiler."},{"en":"Despite the high price, the product sold well.","tr":"Yüksek fiyatına rağmen ürün iyi sattı."},{"en":"Some people learn by reading, whereas others learn by doing.","tr":"Bazı insanlar okuyarak öğrenirken diğerleri yaparak öğrenir."}]'::jsonb,'draft');
insert into public.grammar_notes (id,slug,title_tr,short_tr,long_tr,examples,status) values ('720f608f-5573-5769-bc14-e12bd1dbaa95','change-verbs','Değişimi anlatma: increase, rise, fall, decline','Fiil: Prices rose/fell by 5%. İsim: There was a 5% rise/fall in prices. by = değişim miktarı, to = ulaşılan değer, from … to = başlangıç ve son değer.','rise (rose, risen) nesne almaz; raise nesne ister: The company raised prices. Zarf + fiil: increased sharply, fell slightly. Sıfat + isim: a sharp increase, a slight fall. Grafik metinlerinde sık geçenler: peak (zirve), remain stable (sabit kalmak), fluctuate (dalgalanmak), level off (sabitlenmek), account for (… oluşturmak).','[{"en":"Sales rose by 10% to 2 million.","tr":"Satışlar %10 artarak 2 milyona çıktı."},{"en":"There was a slight fall in exports.","tr":"İhracatta hafif bir düşüş oldu."},{"en":"The company raised its prices.","tr":"Şirket fiyatlarını artırdı."}]'::jsonb,'draft');
insert into public.grammar_notes (id,slug,title_tr,short_tr,long_tr,examples,status) values ('c2448d19-7c6a-5373-b84f-f0ecdb345163','present-perfect-trends','Eğilimlerde present perfect','Geçmişte başlayıp etkisi süren değişimler için has/have + fiilin 3. hâli kullanılır: The number of users has doubled since 2020.','since + başlangıç noktası (since 2020), for + süre (for ten years), over the last decade. Sürecin devam ettiğini vurgulamak için present perfect continuous: Prices have been rising for months. Belirli ve bitmiş bir zaman söyleniyorsa past simple gerekir: Prices rose in 2021.','[{"en":"Internet use has increased over the last decade.","tr":"İnternet kullanımı son on yılda arttı."},{"en":"The number of students has grown since 2015.","tr":"Öğrenci sayısı 2015''ten beri arttı."},{"en":"Prices have been rising for six months.","tr":"Fiyatlar altı aydır yükseliyor."}]'::jsonb,'draft');
insert into public.grammar_notes (id,slug,title_tr,short_tr,long_tr,examples,status) values ('bfcf9a85-caf2-5d11-b852-1fdd48d940df','reporting-verbs','Raporlama fiilleri (suggest, show, claim …)','Akademik metinlerde bulgular suggest, show, indicate, reveal, claim gibi fiillerle aktarılır. Fiilin gücü önemlidir: show kesin, suggest temkinlidir.','Yapı: özne + fiil + that + cümle: The data indicate that … Temkinli dil (hedging): may, might, likely, appear to: The drug may reduce pain. Okuma sorularında yazarın kesin mi temkinli mi konuştuğuna dikkat et. claim (iddia eder) çoğu zaman yazarın bu görüşe mesafeli olduğunu ima eder.','[{"en":"The data indicate that the effect is small.","tr":"Veriler etkinin küçük olduğunu gösteriyor."},{"en":"Some experts claim that the method is unsafe.","tr":"Bazı uzmanlar yöntemin güvenli olmadığını iddia ediyor."},{"en":"It is likely that prices will rise.","tr":"Fiyatların artması muhtemel."}]'::jsonb,'draft');
insert into public.grammar_notes (id,slug,title_tr,short_tr,long_tr,examples,status) values ('5745b079-cf8a-5e9d-9c2f-f10b9ed53ed7','relative-clauses','İlgi cümlecikleri (who, which, that)','Bir ismi açıklayan cümlecikte insanlar için who, nesneler için which, ikisi için de that kullanılır: participants who slept less, a study which lasted ten years.','whose iyelik bildirir: students whose parents work abroad. where yer bildirir: the city where the study was done. Virgüllü (ek bilgi veren) ilgi cümleciğinde that kullanılmaz: The study, which lasted ten years, … Cümle tamamlama sorularında ismin insan mı nesne mi olduğuna ve virgüle bak.','[{"en":"Students who sleep well perform better.","tr":"İyi uyuyan öğrenciler daha iyi performans gösterir."},{"en":"The method, which was developed in 2010, is still popular.","tr":"2010''da geliştirilen yöntem hâlâ yaygın."},{"en":"This is the lab where the tests were done.","tr":"Testlerin yapıldığı laboratuvar burası."}]'::jsonb,'draft');
insert into public.patterns (id,template_en,slot_key,example_en,example_tr,chunks,grammar_note_id,context_tags,tone_tags,template_tr,status) values ('ba589ee5-bb12-52a3-af48-fc201a72cbdb','If we …, … will …','will drop','If we add a fan, the temperature will drop.','Bir fan eklersek sıcaklık düşer.','[{"en":"If we add a fan","tr":"bir fan eklersek"},{"en":"the temperature","tr":"sıcaklık"},{"en":"will drop","tr":"düşecek"}]'::jsonb,'3bf15cc6-24b0-5ade-bd72-578e2cc35706',array['Toplantı','Öneri']::text[],array['Nötr']::text[],'Şunu yaparsak sıcaklık düşer: ….','draft');
insert into public.patterns (id,template_en,slot_key,example_en,example_tr,chunks,grammar_note_id,context_tags,tone_tags,template_tr,status) values ('2acf9154-f037-5f77-9854-1e614af5a9d7','The problem is that …','is that','The problem is that the cable is too thin.','Sorun, kablonun fazla ince olması.','[{"en":"The problem","tr":"sorun"},{"en":"is that","tr":"şu ki"},{"en":"the cable is too thin","tr":"açıklama"}]'::jsonb,'61191619-612d-5027-a1fe-6212fc28bc5e',array['Toplantı','Rapor']::text[],array['Nötr']::text[],'Sorun şu: ….','draft');
insert into public.patterns (id,template_en,slot_key,example_en,example_tr,chunks,grammar_note_id,context_tags,tone_tags,template_tr,status) values ('a0cdcdf9-0be9-565e-825f-10dbab219d2d','One option is to …','One option is','One option is to replace the bearing.','Seçeneklerden biri rulmanı değiştirmek.','[{"en":"One option is","tr":"seçeneklerden biri"},{"en":"to replace the bearing","tr":"öneri (to + fiil)"}]'::jsonb,'9279b596-fe91-567a-9d51-125884641a4b',array['Toplantı','E-posta']::text[],array['Nötr']::text[],'Seçeneklerden biri şu: ….','draft');
insert into public.patterns (id,template_en,slot_key,example_en,example_tr,chunks,grammar_note_id,context_tags,tone_tags,template_tr,status) values ('c092b83c-9db6-5cde-8b9a-9edf6fe177a5','I suggest that we …','that we','I suggest that we test it again.','Tekrar test etmemizi öneriyorum.','[{"en":"I suggest","tr":"öneriyorum"},{"en":"that we","tr":"-memizi"},{"en":"test it again","tr":"öneri (yalın fiil)"}]'::jsonb,'9279b596-fe91-567a-9d51-125884641a4b',array['Toplantı','E-posta']::text[],array['Resmî']::text[],'Şunu yapmamızı öneriyorum: ….','draft');
insert into public.patterns (id,template_en,slot_key,example_en,example_tr,chunks,grammar_note_id,context_tags,tone_tags,template_tr,status) values ('d54f574e-d3d9-5f2a-9196-663c2d4421ab','… is caused by …','caused by','The noise is caused by a loose screw.','Ses gevşek bir vidadan kaynaklanıyor.','[{"en":"The noise","tr":"ses"},{"en":"is caused by","tr":"… kaynaklanıyor"},{"en":"a loose screw","tr":"neden"}]'::jsonb,'65dafd22-780c-55e5-96c7-520eb58691f9',array['Rapor','Toplantı']::text[],array['Nötr']::text[],'Ses şundan kaynaklanıyor: ….','draft');
insert into public.patterns (id,template_en,slot_key,example_en,example_tr,chunks,grammar_note_id,context_tags,tone_tags,template_tr,status) values ('f99a5141-dcf3-5c65-8819-2a8a365b1706','To avoid …, we should …','avoid','To avoid overheating, we should add a fan.','Aşırı ısınmayı önlemek için bir fan eklemeliyiz.','[{"en":"To avoid overheating","tr":"aşırı ısınmayı önlemek için"},{"en":"we should add a fan","tr":"bir fan eklemeliyiz"}]'::jsonb,'a5f9d0fc-be42-50ae-afd1-5c3a477c4150',array['Toplantı','Öneri']::text[],array['Nötr']::text[],'Şunu önlemek için bir fan eklemeliyiz: ….','draft');
insert into public.patterns (id,template_en,slot_key,example_en,example_tr,chunks,grammar_note_id,context_tags,tone_tags,template_tr,status) values ('d6e21946-3f3d-5091-b458-1b94f937b094','The advantage of … is that …','advantage','The advantage of this design is that it''s cheaper.','Bu tasarımın avantajı daha ucuz olması.','[{"en":"The advantage of this design","tr":"bu tasarımın avantajı"},{"en":"is that","tr":"şu ki"},{"en":"it''s cheaper","tr":"gerekçe"}]'::jsonb,'456ec5da-d7b5-550b-9e0c-056b23139658',array['Toplantı','Rapor']::text[],array['Nötr']::text[],'Bu tasarımın avantajı şu: ….','draft');
insert into public.patterns (id,template_en,slot_key,example_en,example_tr,chunks,grammar_note_id,context_tags,tone_tags,template_tr,status) values ('d751f72a-6d83-55d7-9b8a-07cfb18aeb26','How long will it take to …?','take','How long will it take to fix the line?','Hattı tamir etmek ne kadar sürer?','[{"en":"How long","tr":"ne kadar"},{"en":"will it take","tr":"sürer"},{"en":"to fix the line","tr":"iş"}]'::jsonb,'4a9d24f3-029d-5fcb-bf70-fa727ed9e5c5',array['Toplantı','Planlama']::text[],array['Nötr']::text[],'Şunu yapmak ne kadar sürer: …?','draft');
insert into public.patterns (id,template_en,slot_key,example_en,example_tr,chunks,grammar_note_id,context_tags,tone_tags,template_tr,status) values ('3dbb14ba-164b-51d7-9c3e-c55a4db89b86','We could either … or …','either','We could either repair the pump or buy a new one.','Ya pompayı tamir edebiliriz ya da yenisini alabiliriz.','[{"en":"We could either","tr":"ya … -ebiliriz"},{"en":"repair the pump","tr":"1. seçenek"},{"en":"or buy a new one","tr":"ya da yenisini almak"}]'::jsonb,'a5f9d0fc-be42-50ae-afd1-5c3a477c4150',array['Toplantı']::text[],array['Nötr']::text[],'Ya şunu yapabiliriz ya da yenisini alabiliriz: ….','draft');
insert into public.patterns (id,template_en,slot_key,example_en,example_tr,chunks,grammar_note_id,context_tags,tone_tags,template_tr,status) values ('7e03af13-cf58-5e99-b7ad-5697d1c2f6ba','For safety reasons, …','reasons','For safety reasons, wear gloves in the lab.','Güvenlik nedeniyle laboratuvarda eldiven tak.','[{"en":"For safety reasons","tr":"güvenlik nedeniyle"},{"en":"wear gloves","tr":"talimat (emir kipi)"}]'::jsonb,'61191619-612d-5027-a1fe-6212fc28bc5e',array['Güvenlik','Kılavuz']::text[],array['Resmî']::text[],'Güvenlik nedeniyle şunu yap: ….','draft');
insert into public.patterns (id,template_en,slot_key,example_en,example_tr,chunks,grammar_note_id,context_tags,tone_tags,template_tr,status) values ('f3c8fd03-f101-5295-8a23-63e4d8f0ffbe','… is …-er than …','quieter than','The new pump is quieter than the old one.','Yeni pompa eskisinden daha sessiz.','[{"en":"The new pump","tr":"yeni pompa"},{"en":"is quieter than","tr":"-den daha sessiz"},{"en":"the old one","tr":"eskisi"}]'::jsonb,'456ec5da-d7b5-550b-9e0c-056b23139658',array['Teknik toplantı','Rapor']::text[],array['Nötr']::text[],'Yeni pompa eskisinden daha ….','draft');
insert into public.patterns (id,template_en,slot_key,example_en,example_tr,chunks,grammar_note_id,context_tags,tone_tags,template_tr,status) values ('af4ca369-6ef5-5506-931d-9fa0f8791e30','It measures … by …','measures','The panel measures 60 by 120 cm.','Panel 60''a 120 cm boyutunda.','[{"en":"The panel","tr":"panel"},{"en":"measures","tr":"… ölçüsünde"},{"en":"60 by 120 cm","tr":"en × boy"}]'::jsonb,'d5774794-79d5-5598-b2ee-b28a68901a09',array['Teknik özellik']::text[],array['Nötr']::text[],'Panelin ölçüsü: ….','draft');
insert into public.patterns (id,template_en,slot_key,example_en,example_tr,chunks,grammar_note_id,context_tags,tone_tags,template_tr,status) values ('eeb5321f-1d1e-5c4a-a8d9-7aca24148afb','It''s made of …','made of','The housing is made of stainless steel.','Gövde paslanmaz çelikten yapılmış.','[{"en":"The housing","tr":"gövde"},{"en":"is made of","tr":"-den yapılmış"},{"en":"stainless steel","tr":"malzeme"}]'::jsonb,'65dafd22-780c-55e5-96c7-520eb58691f9',array['Teknik özellik']::text[],array['Nötr']::text[],'Gövde şundan yapılmış: ….','draft');
insert into public.patterns (id,template_en,slot_key,example_en,example_tr,chunks,grammar_note_id,context_tags,tone_tags,template_tr,status) values ('dc6f8a11-53b1-5c29-bb70-1b1fac6e3e47','It operates at …','operates at','The system operates at 24 volts.','Sistem 24 voltta çalışır.','[{"en":"The system","tr":"sistem"},{"en":"operates at","tr":"… değerinde çalışır"},{"en":"24 volts","tr":"değer"}]'::jsonb,'61191619-612d-5027-a1fe-6212fc28bc5e',array['Teknik özellik']::text[],array['Nötr']::text[],'Sistem şu değerde çalışır: ….','draft');
insert into public.patterns (id,template_en,slot_key,example_en,example_tr,chunks,grammar_note_id,context_tags,tone_tags,template_tr,status) values ('c2fd071c-7e52-5a0c-86a9-6c4f034e4ffd','It can … up to …','up to','The crane can lift up to two tons.','Vinç iki tona kadar kaldırabilir.','[{"en":"The crane can lift","tr":"vinç kaldırabilir"},{"en":"up to","tr":"-e kadar"},{"en":"two tons","tr":"üst sınır"}]'::jsonb,'d5774794-79d5-5598-b2ee-b28a68901a09',array['Teknik özellik']::text[],array['Nötr']::text[],'Vinç şuna kadar kaldırabilir: ….','draft');
insert into public.patterns (id,template_en,slot_key,example_en,example_tr,chunks,grammar_note_id,context_tags,tone_tags,template_tr,status) values ('cf3a5bce-0c75-5da7-8bcd-9358b3849b1c','The difference between … is …','difference','The difference between the two readings is 0.3 mm.','İki ölçüm arasındaki fark 0,3 mm.','[{"en":"The difference","tr":"fark"},{"en":"between the two readings","tr":"iki ölçüm arasındaki"},{"en":"is 0.3 mm","tr":"değer"}]'::jsonb,'d5774794-79d5-5598-b2ee-b28a68901a09',array['Rapor','Teknik toplantı']::text[],array['Nötr']::text[],'İki ölçüm arasındaki fark: ….','draft');
insert into public.patterns (id,template_en,slot_key,example_en,example_tr,chunks,grammar_note_id,context_tags,tone_tags,template_tr,status) values ('3119a233-8316-5152-8079-c296e372bb70','The result is within …','within','The result is within the allowed range.','Sonuç izin verilen aralığın içinde.','[{"en":"The result","tr":"sonuç"},{"en":"is within","tr":"içinde"},{"en":"the allowed range","tr":"sınır"}]'::jsonb,'61191619-612d-5027-a1fe-6212fc28bc5e',array['Kalite','Rapor']::text[],array['Nötr']::text[],'Sonuç şunun içinde: ….','draft');
insert into public.patterns (id,template_en,slot_key,example_en,example_tr,chunks,grammar_note_id,context_tags,tone_tags,template_tr,status) values ('c2067317-925b-54e2-bdf0-5ab3309a6cca','… should not exceed …','exceed','The temperature should not exceed 80 °C.','Sıcaklık 80 °C''yi aşmamalı.','[{"en":"The temperature","tr":"sıcaklık"},{"en":"should not exceed","tr":"aşmamalı"},{"en":"80 °C","tr":"sınır"}]'::jsonb,'a5f9d0fc-be42-50ae-afd1-5c3a477c4150',array['Güvenlik','Kılavuz']::text[],array['Uyarı']::text[],'Sıcaklık şunu aşmamalı: ….','draft');
insert into public.patterns (id,template_en,slot_key,example_en,example_tr,chunks,grammar_note_id,context_tags,tone_tags,template_tr,status) values ('76e80029-f9fa-5e12-b355-7139fcd77f66','Compared to …, …','Compared to','Compared to steel, aluminum is much lighter.','Çelikle karşılaştırıldığında alüminyum çok daha hafif.','[{"en":"Compared to steel","tr":"çelikle karşılaştırıldığında"},{"en":"aluminum is much lighter","tr":"alüminyum çok daha hafif"}]'::jsonb,'456ec5da-d7b5-550b-9e0c-056b23139658',array['Teknik toplantı','Rapor']::text[],array['Nötr']::text[],'Alüminyum şununla karşılaştırıldığında çok daha hafif: ….','draft');
insert into public.patterns (id,template_en,slot_key,example_en,example_tr,chunks,grammar_note_id,context_tags,tone_tags,template_tr,status) values ('a9009ae2-219b-55c0-bfc2-e8fe1c4bf3c0','According to …, …','According to','According to the datasheet, the maximum load is 5 kN.','Veri sayfasına göre azami yük 5 kN.','[{"en":"According to the datasheet","tr":"veri sayfasına göre"},{"en":"the maximum load is 5 kN","tr":"bilgi"}]'::jsonb,'61191619-612d-5027-a1fe-6212fc28bc5e',array['Rapor','Teknik toplantı']::text[],array['Resmî']::text[],'Şuna göre azami yük 5 kN: ….','draft');
insert into public.patterns (id,template_en,slot_key,example_en,example_tr,chunks,grammar_note_id,context_tags,tone_tags,template_tr,status) values ('6fe54c92-5675-53cd-9eea-9f99d5740dee','If …, the … (her zaman geçerli sonuç)','closes','If the pressure drops, the valve closes automatically.','Basınç düşerse vana otomatik olarak kapanır.','[{"en":"If the pressure drops","tr":"basınç düşerse"},{"en":"the valve closes","tr":"vana kapanır"},{"en":"automatically","tr":"otomatik olarak"}]'::jsonb,'192debd3-9082-5b07-80a0-40d56570f67c',array['Kılavuz','Teknik açıklama']::text[],array['Nötr']::text[],'… vana otomatik olarak kapanır.','draft');
insert into public.patterns (id,template_en,slot_key,example_en,example_tr,chunks,grammar_note_id,context_tags,tone_tags,template_tr,status) values ('a6489ca4-5daf-56fc-890b-2c4190a52611','The … was tested at …','was tested','The battery was tested at −20 °C.','Pil −20 °C''de test edildi.','[{"en":"The battery","tr":"pil"},{"en":"was tested","tr":"test edildi"},{"en":"at −20 °C","tr":"koşul"}]'::jsonb,'0e47e1be-1f21-5acc-aab3-01552452cccd',array['Test raporu']::text[],array['Resmî']::text[],'Pil şu koşulda test edildi: ….','draft');
insert into public.patterns (id,template_en,slot_key,example_en,example_tr,chunks,grammar_note_id,context_tags,tone_tags,template_tr,status) values ('bd13d00e-0516-54bd-be51-79fdf9dff016','The results show that …','show that','The results show that the coating works well.','Sonuçlar kaplamanın iyi çalıştığını gösteriyor.','[{"en":"The results","tr":"sonuçlar"},{"en":"show that","tr":"-dığını gösteriyor"},{"en":"the coating works well","tr":"bulgu"}]'::jsonb,'61191619-612d-5027-a1fe-6212fc28bc5e',array['Test raporu','Sunum']::text[],array['Resmî']::text[],'Sonuçlar şunu gösteriyor: ….','draft');
insert into public.patterns (id,template_en,slot_key,example_en,example_tr,chunks,grammar_note_id,context_tags,tone_tags,template_tr,status) values ('a70ff061-3170-519f-8339-010505b20e66','It failed after …','after','The bearing failed after 3,000 hours.','Rulman 3.000 saat sonra arızalandı.','[{"en":"The bearing failed","tr":"rulman arızalandı"},{"en":"after 3,000 hours","tr":"3.000 saat sonra"}]'::jsonb,'6abb00b5-f7d0-5462-97e1-00928664f27f',array['Test raporu']::text[],array['Nötr']::text[],'Rulman şundan sonra arızalandı: ….','draft');
insert into public.patterns (id,template_en,slot_key,example_en,example_tr,chunks,grammar_note_id,context_tags,tone_tags,template_tr,status) values ('3d193241-ffbe-5aee-a947-4a386aba93e5','There was no sign of …','sign of','There was no sign of corrosion after the test.','Testten sonra korozyon belirtisi yoktu.','[{"en":"There was no","tr":"yoktu"},{"en":"sign of corrosion","tr":"korozyon belirtisi"},{"en":"after the test","tr":"testten sonra"}]'::jsonb,'6abb00b5-f7d0-5462-97e1-00928664f27f',array['Test raporu']::text[],array['Resmî']::text[],'Testten sonra şunun belirtisi yoktu: ….','draft');
insert into public.patterns (id,template_en,slot_key,example_en,example_tr,chunks,grammar_note_id,context_tags,tone_tags,template_tr,status) values ('3f6001d8-cf2f-5b9b-a059-5d18b1b70394','We need to repeat … because …','repeat','We need to repeat the test because the sensor was loose.','Sensör gevşek olduğu için testi tekrarlamamız gerekiyor.','[{"en":"We need to repeat","tr":"tekrarlamamız gerekiyor"},{"en":"the test","tr":"iş"},{"en":"because the sensor was loose","tr":"neden"}]'::jsonb,'d5daeed1-3188-5fc9-bf18-7fc0d1d582be',array['Toplantı','Laboratuvar']::text[],array['Nötr']::text[],'Sensör gevşek olduğu için şunu tekrarlamamız gerekiyor: ….','draft');
insert into public.patterns (id,template_en,slot_key,example_en,example_tr,chunks,grammar_note_id,context_tags,tone_tags,template_tr,status) values ('7b26e8d1-0de8-5cb5-909b-1ee189f35646','… increased by …','by','The temperature increased by 15 degrees.','Sıcaklık 15 derece arttı.','[{"en":"The temperature","tr":"sıcaklık"},{"en":"increased by","tr":"… kadar arttı"},{"en":"15 degrees","tr":"artış miktarı"}]'::jsonb,'720f608f-5573-5769-bc14-e12bd1dbaa95',array['Test raporu']::text[],array['Nötr']::text[],'Sıcaklık şu kadar arttı: ….','draft');
insert into public.patterns (id,template_en,slot_key,example_en,example_tr,chunks,grammar_note_id,context_tags,tone_tags,template_tr,status) values ('7eb5be40-357b-52b7-81e9-368206d66e6c','Under … conditions, …','Under','Under normal conditions, the motor runs at 1,500 rpm.','Normal koşullar altında motor 1.500 devirde çalışır.','[{"en":"Under normal conditions","tr":"normal koşullar altında"},{"en":"the motor runs at 1,500 rpm","tr":"motor 1.500 devirde çalışır"}]'::jsonb,'192debd3-9082-5b07-80a0-40d56570f67c',array['Teknik açıklama']::text[],array['Resmî']::text[],'… motor 1.500 devirde çalışır.','draft');
insert into public.patterns (id,template_en,slot_key,example_en,example_tr,chunks,grammar_note_id,context_tags,tone_tags,template_tr,status) values ('4b500344-8168-558a-b831-3df26de9c52b','We observed …','observed','We observed a small vibration at high speed.','Yüksek hızda küçük bir titreşim gözlemledik.','[{"en":"We observed","tr":"gözlemledik"},{"en":"a small vibration","tr":"gözlem"},{"en":"at high speed","tr":"koşul"}]'::jsonb,'6abb00b5-f7d0-5462-97e1-00928664f27f',array['Test raporu']::text[],array['Resmî']::text[],'Şunu gözlemledik: ….','draft');
insert into public.patterns (id,template_en,slot_key,example_en,example_tr,chunks,grammar_note_id,context_tags,tone_tags,template_tr,status) values ('1bb37809-e0e2-5532-a067-2c431433d57c','We recommend …-ing','using','We recommend using a thicker seal.','Daha kalın bir conta kullanılmasını öneriyoruz.','[{"en":"We recommend","tr":"öneriyoruz"},{"en":"using a thicker seal","tr":"öneri (-ing)"}]'::jsonb,'9279b596-fe91-567a-9d51-125884641a4b',array['Test raporu','Toplantı']::text[],array['Resmî']::text[],'Şunu öneriyoruz: ….','draft');
insert into public.patterns (id,template_en,slot_key,example_en,example_tr,chunks,grammar_note_id,context_tags,tone_tags,template_tr,status) values ('6e79395f-e354-54a4-b267-77b6e064096d','I''m going to … this weekend.','going to','I''m going to visit my parents this weekend.','Bu hafta sonu ailemi ziyaret edeceğim.','[{"en":"I''m going to","tr":"-eceğim (plan)"},{"en":"visit my parents","tr":"eylem"},{"en":"this weekend","tr":"bu hafta sonu"}]'::jsonb,'4a9d24f3-029d-5fcb-bf70-fa727ed9e5c5',array['Sohbet','Plan yapma']::text[],array['Günlük']::text[],'Bu hafta sonu şunu yapacağım: ….','draft');
insert into public.patterns (id,template_en,slot_key,example_en,example_tr,chunks,grammar_note_id,context_tags,tone_tags,template_tr,status) values ('b8212bf2-d967-5ff8-a24c-3280572ae7fa','How about …?','about','How about going to the cinema tonight?','Bu akşam sinemaya gitmeye ne dersin?','[{"en":"How about","tr":"ne dersin"},{"en":"going to the cinema","tr":"öneri (-ing veya isim)"}]'::jsonb,'a5f9d0fc-be42-50ae-afd1-5c3a477c4150',array['Plan yapma','Davet']::text[],array['Samimi']::text[],'Şuna ne dersin: …?','draft');
insert into public.patterns (id,template_en,slot_key,example_en,example_tr,chunks,grammar_note_id,context_tags,tone_tags,template_tr,status) values ('fa024ecc-9dd9-51c8-93aa-b7c01dafe404','Are you free on …?','on','Are you free on Friday evening?','Cuma akşamı müsait misin?','[{"en":"Are you free","tr":"müsait misin"},{"en":"on Friday evening","tr":"zaman"}]'::jsonb,'451cf418-a1b2-5782-8a95-8dc5c6a0b92d',array['Plan yapma','Davet']::text[],array['Günlük']::text[],'… müsait misin?','draft');
insert into public.patterns (id,template_en,slot_key,example_en,example_tr,chunks,grammar_note_id,context_tags,tone_tags,template_tr,status) values ('70574ff3-ec1a-5ba6-99f6-a00b1d67bb86','I always … before …','before','I always check my email before work.','İşten önce her zaman e-postalarımı kontrol ederim.','[{"en":"I always","tr":"her zaman"},{"en":"check my email","tr":"eylem"},{"en":"before work","tr":"işten önce"}]'::jsonb,'7be2ff59-b822-5d17-b28c-77b5dd4bad29',array['Sohbet','Rutin']::text[],array['Günlük']::text[],'İşten önce her zaman şunu yaparım: ….','draft');
insert into public.patterns (id,template_en,slot_key,example_en,example_tr,chunks,grammar_note_id,context_tags,tone_tags,template_tr,status) values ('53eb02b5-87d0-57be-abe9-819c977dcb23','I have to … today.','have to','I have to finish this report today.','Bu raporu bugün bitirmem gerekiyor.','[{"en":"I have to","tr":"-mem gerekiyor"},{"en":"finish this report","tr":"yapılacak iş"},{"en":"today","tr":"bugün"}]'::jsonb,'d5daeed1-3188-5fc9-bf18-7fc0d1d582be',array['Sohbet','Mazeret']::text[],array['Günlük']::text[],'Bugün şunu yapmam gerekiyor: ….','draft');
insert into public.patterns (id,template_en,slot_key,example_en,example_tr,chunks,grammar_note_id,context_tags,tone_tags,template_tr,status) values ('fb59a901-f0bb-539f-bdee-bca6a85c15b6','I''m meeting … tomorrow.','meeting','I''m meeting Ayşe for lunch tomorrow.','Yarın öğle yemeğinde Ayşe''yle buluşacağım.','[{"en":"I''m meeting","tr":"buluşacağım (ayarlanmış plan)"},{"en":"Ayşe for lunch","tr":"kim ve ne için"},{"en":"tomorrow","tr":"yarın"}]'::jsonb,'07f46ae3-6018-5f8f-8bda-377e874ddc92',array['Plan yapma']::text[],array['Günlük']::text[],'Yarın … buluşacağım.','draft');
insert into public.patterns (id,template_en,slot_key,example_en,example_tr,chunks,grammar_note_id,context_tags,tone_tags,template_tr,status) values ('39513978-0c89-5532-9b5d-21828c93c602','Let''s meet at …','meet','Let''s meet at the café near the station.','İstasyonun yakınındaki kafede buluşalım.','[{"en":"Let''s","tr":"-elim"},{"en":"meet","tr":"buluş-"},{"en":"at the café","tr":"yer"}]'::jsonb,'61191619-612d-5027-a1fe-6212fc28bc5e',array['Plan yapma']::text[],array['Samimi']::text[],'Şurada buluşalım: ….','draft');
insert into public.patterns (id,template_en,slot_key,example_en,example_tr,chunks,grammar_note_id,context_tags,tone_tags,template_tr,status) values ('41c61d73-b622-57a2-888c-2c31b760d66d','It takes … to get to …','takes','It takes about 40 minutes to get to work.','İşe gitmek yaklaşık 40 dakika sürüyor.','[{"en":"It takes","tr":"sürüyor"},{"en":"about 40 minutes","tr":"süre"},{"en":"to get to work","tr":"işe gitmek"}]'::jsonb,'61191619-612d-5027-a1fe-6212fc28bc5e',array['Sohbet','Rutin']::text[],array['Günlük']::text[],'İşe gitmek şu kadar sürüyor: ….','draft');
insert into public.patterns (id,template_en,slot_key,example_en,example_tr,chunks,grammar_note_id,context_tags,tone_tags,template_tr,status) values ('a2023554-3c00-56e4-90d6-f4f4861dc5d0','Sorry, I can''t make it …','make it','Sorry, I can''t make it tonight.','Kusura bakma, bu akşam gelemiyorum.','[{"en":"Sorry","tr":"kusura bakma"},{"en":"I can''t make it","tr":"gelemiyorum, yetişemiyorum"},{"en":"tonight","tr":"zaman"}]'::jsonb,'d5daeed1-3188-5fc9-bf18-7fc0d1d582be',array['Davet','Mazeret']::text[],array['Nazik']::text[],'Kusura bakma, şu zaman gelemiyorum: ….','draft');
insert into public.patterns (id,template_en,slot_key,example_en,example_tr,chunks,grammar_note_id,context_tags,tone_tags,template_tr,status) values ('da21158b-5c90-53fd-a2b7-ec6baedef19b','What time does … start?','does','What time does the movie start?','Film saat kaçta başlıyor?','[{"en":"What time","tr":"saat kaçta"},{"en":"does the movie start","tr":"film başlıyor"}]'::jsonb,'61191619-612d-5027-a1fe-6212fc28bc5e',array['Plan yapma']::text[],array['Günlük']::text[],'… saat kaçta başlıyor?','draft');
insert into public.patterns (id,template_en,slot_key,example_en,example_tr,chunks,grammar_note_id,context_tags,tone_tags,template_tr,status) values ('acaa600b-c294-5ab3-9d83-9bdb4c9723c2','I''m a/an …','a','I''m a software developer.','Yazılım geliştiriciyim.','[{"en":"I''m","tr":"ben …-im"},{"en":"a","tr":"bir"},{"en":"software developer","tr":"meslek"}]'::jsonb,'451cf418-a1b2-5782-8a95-8dc5c6a0b92d',array['Tanışma','İş görüşmesi']::text[],array['Günlük']::text[],'Mesleğim: ….','draft');
insert into public.patterns (id,template_en,slot_key,example_en,example_tr,chunks,grammar_note_id,context_tags,tone_tags,template_tr,status) values ('b48d5d1a-1cf7-542f-b615-d0775a16cdf4','I work at …','at','I work at a bank in Kadıköy.','Kadıköy''de bir bankada çalışıyorum.','[{"en":"I work","tr":"çalışıyorum"},{"en":"at","tr":"-de"},{"en":"a bank in Kadıköy","tr":"iş yeri"}]'::jsonb,'61191619-612d-5027-a1fe-6212fc28bc5e',array['Tanışma','İş görüşmesi']::text[],array['Günlük']::text[],'Şurada çalışıyorum: ….','draft');
insert into public.patterns (id,template_en,slot_key,example_en,example_tr,chunks,grammar_note_id,context_tags,tone_tags,template_tr,status) values ('0fa081c3-6341-5e06-9514-4754fe2c5f68','I''ve lived in … for … years.','for','I''ve lived in İstanbul for five years.','Beş yıldır İstanbul''da yaşıyorum.','[{"en":"I''ve lived","tr":"yaşıyorum (geçmişten beri)"},{"en":"in İstanbul","tr":"yer"},{"en":"for five years","tr":"beş yıldır"}]'::jsonb,'6a11b3cb-d93f-533d-b6d2-56af6ab35df5',array['Tanışma']::text[],array['Günlük']::text[],'Beş yıldır şurada yaşıyorum: ….','draft');
insert into public.patterns (id,template_en,slot_key,example_en,example_tr,chunks,grammar_note_id,context_tags,tone_tags,template_tr,status) values ('c7b52092-30a2-5715-bc72-924b495469ca','I like …-ing in my free time.','reading','I like reading in my free time.','Boş zamanımda okumayı severim.','[{"en":"I like","tr":"severim"},{"en":"reading","tr":"-mayı (fiil + -ing)"},{"en":"in my free time","tr":"boş zamanımda"}]'::jsonb,'61191619-612d-5027-a1fe-6212fc28bc5e',array['Tanışma','Sohbet']::text[],array['Günlük']::text[],'Boş zamanımda şunu severim: ….','draft');
insert into public.patterns (id,template_en,slot_key,example_en,example_tr,chunks,grammar_note_id,context_tags,tone_tags,template_tr,status) values ('8fae41bd-2fc9-59bb-a986-732080a64e13','I''m good at …','at','I''m good at solving problems.','Problem çözmekte iyiyim.','[{"en":"I''m good","tr":"iyiyim"},{"en":"at","tr":"… konusunda"},{"en":"solving problems","tr":"beceri"}]'::jsonb,'451cf418-a1b2-5782-8a95-8dc5c6a0b92d',array['Tanışma','İş görüşmesi']::text[],array['Günlük']::text[],'Şunda iyiyim: ….','draft');
insert into public.patterns (id,template_en,slot_key,example_en,example_tr,chunks,grammar_note_id,context_tags,tone_tags,template_tr,status) values ('8b237c02-b4e2-5010-8127-09f3f95a7465','I don''t … very often.','don''t','I don''t watch TV very often.','Pek sık televizyon izlemem.','[{"en":"I don''t","tr":"-mam"},{"en":"watch TV","tr":"eylem"},{"en":"very often","tr":"çok sık"}]'::jsonb,'61191619-612d-5027-a1fe-6212fc28bc5e',array['Sohbet']::text[],array['Günlük']::text[],'Şunu pek sık yapmam: ….','draft');
insert into public.patterns (id,template_en,slot_key,example_en,example_tr,chunks,grammar_note_id,context_tags,tone_tags,template_tr,status) values ('3345c65f-14ee-5f14-96ed-d6049b88ebc2','How long have you …?','have you','How long have you lived here?','Ne zamandır burada yaşıyorsun?','[{"en":"How long","tr":"ne zamandır"},{"en":"have you","tr":"(sen) -"},{"en":"lived here","tr":"süren durum"}]'::jsonb,'6a11b3cb-d93f-533d-b6d2-56af6ab35df5',array['Tanışma','Sohbet']::text[],array['Günlük']::text[],'Ne zamandır şunu yapıyorsun: …?','draft');
insert into public.patterns (id,template_en,slot_key,example_en,example_tr,chunks,grammar_note_id,context_tags,tone_tags,template_tr,status) values ('cd4e9a10-ee9b-590c-9122-849667c2754d','What kind of … do you like?','kind of','What kind of music do you like?','Ne tür müzik seversin?','[{"en":"What kind of","tr":"ne tür"},{"en":"music","tr":"konu"},{"en":"do you like","tr":"seversin"}]'::jsonb,'61191619-612d-5027-a1fe-6212fc28bc5e',array['Sohbet']::text[],array['Günlük']::text[],'Ne tür … seversin?','draft');
insert into public.patterns (id,template_en,slot_key,example_en,example_tr,chunks,grammar_note_id,context_tags,tone_tags,template_tr,status) values ('cf27d220-fac9-5685-b12a-0b65d3b1631f','I live with …','live with','I live with my sister.','Kız kardeşimle yaşıyorum.','[{"en":"I live","tr":"yaşıyorum"},{"en":"with","tr":"ile"},{"en":"my sister","tr":"kişi"}]'::jsonb,'61191619-612d-5027-a1fe-6212fc28bc5e',array['Tanışma','Sohbet']::text[],array['Günlük']::text[],'… ile yaşıyorum.','draft');
insert into public.patterns (id,template_en,slot_key,example_en,example_tr,chunks,grammar_note_id,context_tags,tone_tags,template_tr,status) values ('d6c652c6-66be-51a5-8eb9-1798060ac6cb','See you …!','See you','See you on Monday!','Pazartesi görüşürüz!','[{"en":"See you","tr":"görüşürüz"},{"en":"on Monday","tr":"zaman"}]'::jsonb,'61191619-612d-5027-a1fe-6212fc28bc5e',array['Selamlaşma']::text[],array['Samimi']::text[],'… görüşürüz!','draft');
insert into public.patterns (id,template_en,slot_key,example_en,example_tr,chunks,grammar_note_id,context_tags,tone_tags,template_tr,status) values ('10d64ffe-9f09-5040-8b56-7e4a270ffba3','I''d like …, please.','like','I''d like a glass of water, please.','Bir bardak su istiyorum, lütfen.','[{"en":"I''d like","tr":"istiyorum (kibar)"},{"en":"a glass of water","tr":"istenen şey"},{"en":"please","tr":"lütfen"}]'::jsonb,'851477de-6cca-5819-9b94-be7428c7eb31',array['Restoran','Mağaza']::text[],array['Nazik']::text[],'… istiyorum, lütfen.','draft');
insert into public.patterns (id,template_en,slot_key,example_en,example_tr,chunks,grammar_note_id,context_tags,tone_tags,template_tr,status) values ('727a54da-9ef5-5b2d-9394-2fdff91cf41a','Could I have …?','have','Could I have the menu, please?','Menüyü alabilir miyim, lütfen?','[{"en":"Could I","tr":"-ebilir miyim"},{"en":"have","tr":"al-"},{"en":"the menu","tr":"istenen şey"}]'::jsonb,'d5daeed1-3188-5fc9-bf18-7fc0d1d582be',array['Restoran','Otel']::text[],array['Nazik']::text[],'Şunu alabilir miyim: …?','draft');
insert into public.patterns (id,template_en,slot_key,example_en,example_tr,chunks,grammar_note_id,context_tags,tone_tags,template_tr,status) values ('1df442b0-c7a8-59d9-9dfd-be153e6f2fbe','Is it okay if I …?','if','Is it okay if I open the window?','Pencereyi açsam olur mu?','[{"en":"Is it okay","tr":"olur mu"},{"en":"if I","tr":"-sam"},{"en":"open the window","tr":"eylem"}]'::jsonb,'d5daeed1-3188-5fc9-bf18-7fc0d1d582be',array['İzin isteme']::text[],array['Nazik']::text[],'Şunu yapsam olur mu: …?','draft');
insert into public.patterns (id,template_en,slot_key,example_en,example_tr,chunks,grammar_note_id,context_tags,tone_tags,template_tr,status) values ('7beabc93-c6b3-5b6c-9027-6cec8ebddde9','There''s a problem with …','with','There''s a problem with my room key.','Oda anahtarımda bir sorun var.','[{"en":"There''s a problem","tr":"bir sorun var"},{"en":"with","tr":"… ile ilgili"},{"en":"my room key","tr":"sorunlu şey"}]'::jsonb,'61191619-612d-5027-a1fe-6212fc28bc5e',array['Otel','Mağaza']::text[],array['Nötr']::text[],'Şunda bir sorun var: ….','draft');
insert into public.patterns (id,template_en,slot_key,example_en,example_tr,chunks,grammar_note_id,context_tags,tone_tags,template_tr,status) values ('6a192f9c-3be6-5aff-a1da-9492fda3e953','The … doesn''t work.','doesn''t','The air conditioner doesn''t work.','Klima çalışmıyor.','[{"en":"The air conditioner","tr":"arızalı şey"},{"en":"doesn''t work","tr":"çalışmıyor"}]'::jsonb,'61191619-612d-5027-a1fe-6212fc28bc5e',array['Otel','Ev']::text[],array['Nötr']::text[],'… çalışmıyor.','draft');
insert into public.patterns (id,template_en,slot_key,example_en,example_tr,chunks,grammar_note_id,context_tags,tone_tags,template_tr,status) values ('16272a2c-0563-58b3-a73e-c009c5f16e96','How much is …?','is','How much is this backpack?','Bu sırt çantası ne kadar?','[{"en":"How much","tr":"ne kadar"},{"en":"is","tr":"-dir"},{"en":"this backpack","tr":"ürün"}]'::jsonb,'451cf418-a1b2-5782-8a95-8dc5c6a0b92d',array['Mağaza']::text[],array['Günlük']::text[],'… ne kadar?','draft');
insert into public.patterns (id,template_en,slot_key,example_en,example_tr,chunks,grammar_note_id,context_tags,tone_tags,template_tr,status) values ('6bcef6ab-b76c-5166-b900-231dc9b01e8c','Can you help me …?','carry','Can you help me carry these boxes?','Bu kutuları taşımama yardım edebilir misin?','[{"en":"Can you help me","tr":"bana yardım edebilir misin"},{"en":"carry these boxes","tr":"eylem (yalın fiil)"}]'::jsonb,'d5daeed1-3188-5fc9-bf18-7fc0d1d582be',array['Yardım isteme']::text[],array['Samimi']::text[],'Şunu yapmama yardım edebilir misin: …?','draft');
insert into public.patterns (id,template_en,slot_key,example_en,example_tr,chunks,grammar_note_id,context_tags,tone_tags,template_tr,status) values ('ec6bfe1f-0a2e-588f-8973-2b0aa48c2ee4','I think I was charged …','was charged','I think I was charged twice for this.','Sanırım bunun için benden iki kez ücret alındı.','[{"en":"I think","tr":"sanırım"},{"en":"I was charged","tr":"benden ücret alındı"},{"en":"twice","tr":"iki kez"}]'::jsonb,'65dafd22-780c-55e5-96c7-520eb58691f9',array['Mağaza','Otel','Banka']::text[],array['Nazik']::text[],'Sanırım benden ücret alındı: ….','draft');
insert into public.patterns (id,template_en,slot_key,example_en,example_tr,chunks,grammar_note_id,context_tags,tone_tags,template_tr,status) values ('9c898ed0-b425-5670-b1db-1dc730b61d07','Would you mind …-ing?','turning','Would you mind turning the music down?','Müziğin sesini kısar mısınız?','[{"en":"Would you mind","tr":"… mısınız (çok nazik)"},{"en":"turning the music down","tr":"eylem (-ing)"}]'::jsonb,'851477de-6cca-5819-9b94-be7428c7eb31',array['Komşu','Rica']::text[],array['Çok nazik']::text[],'Şunu yapar mısınız: …?','draft');
insert into public.patterns (id,template_en,slot_key,example_en,example_tr,chunks,grammar_note_id,context_tags,tone_tags,template_tr,status) values ('b769039c-eb8f-564a-8dfb-0a14f19d03d3','I ordered …, but I got …','but','I ordered a medium, but I got a large.','Orta boy sipariş ettim ama bana büyük boy geldi.','[{"en":"I ordered","tr":"sipariş ettim"},{"en":"a medium","tr":"istenen"},{"en":"but I got a large","tr":"ama gelen"}]'::jsonb,'6abb00b5-f7d0-5462-97e1-00928664f27f',array['Restoran','Online alışveriş']::text[],array['Nötr']::text[],'Şunu sipariş ettim ama başka bir şey geldi: ….','draft');
insert into public.patterns (id,template_en,slot_key,example_en,example_tr,chunks,grammar_note_id,context_tags,tone_tags,template_tr,status) values ('7adbf318-5efd-5e2e-b28e-14d3f40a48bb','What do you think about …?','think about','What do you think about moving this to a helper?','Bunu bir yardımcı fonksiyona taşımaya ne dersin?','[{"en":"What do you think","tr":"ne dersin"},{"en":"about","tr":"… hakkında"},{"en":"moving this to a helper","tr":"öneri (-ing)"}]'::jsonb,'61191619-612d-5027-a1fe-6212fc28bc5e',array['Kod inceleme','Toplantı']::text[],array['Nazik']::text[],'Şuna ne dersin: …?','draft');
insert into public.patterns (id,template_en,slot_key,example_en,example_tr,chunks,grammar_note_id,context_tags,tone_tags,template_tr,status) values ('bd7477cd-2b4e-52f7-840d-a02dcc5cdf29','Maybe we could …','could','Maybe we could add a test for this case.','Belki bu durum için bir test ekleyebiliriz.','[{"en":"Maybe","tr":"belki"},{"en":"we could","tr":"-ebiliriz"},{"en":"add a test","tr":"öneri"}]'::jsonb,'a5f9d0fc-be42-50ae-afd1-5c3a477c4150',array['Kod inceleme','Toplantı']::text[],array['Nazik']::text[],'Belki şunu yapabiliriz: ….','draft');
insert into public.patterns (id,template_en,slot_key,example_en,example_tr,chunks,grammar_note_id,context_tags,tone_tags,template_tr,status) values ('31d6953c-039d-5f1f-89e0-643298800389','This should be moved to …','should be moved','This logic should be moved to the service layer.','Bu mantık servis katmanına taşınmalı.','[{"en":"This logic","tr":"bu mantık"},{"en":"should be moved","tr":"taşınmalı"},{"en":"to the service layer","tr":"hedef yer"}]'::jsonb,'65dafd22-780c-55e5-96c7-520eb58691f9',array['Kod inceleme']::text[],array['Nötr']::text[],'Bu mantık şuraya taşınmalı: ….','draft');
insert into public.patterns (id,template_en,slot_key,example_en,example_tr,chunks,grammar_note_id,context_tags,tone_tags,template_tr,status) values ('31fb5980-d444-5978-a927-eebca21d5000','Can we use … instead of …?','instead of','Can we use a map instead of two arrays?','İki dizi yerine bir map kullanabilir miyiz?','[{"en":"Can we use","tr":"kullanabilir miyiz"},{"en":"a map","tr":"önerilen"},{"en":"instead of two arrays","tr":"iki dizi yerine"}]'::jsonb,'a5f9d0fc-be42-50ae-afd1-5c3a477c4150',array['Kod inceleme']::text[],array['Nazik']::text[],'İki dizi yerine şunu kullanabilir miyiz: …?','draft');
insert into public.patterns (id,template_en,slot_key,example_en,example_tr,chunks,grammar_note_id,context_tags,tone_tags,template_tr,status) values ('fa696a34-1ee7-519b-8ae1-f8b27c398f19','I left a few comments on …','left','I left a few comments on your PR.','PR''ına birkaç yorum bıraktım.','[{"en":"I left","tr":"bıraktım"},{"en":"a few comments","tr":"birkaç yorum"},{"en":"on your PR","tr":"PR''ına"}]'::jsonb,'6abb00b5-f7d0-5462-97e1-00928664f27f',array['Kod inceleme','Ekip mesajı']::text[],array['Nötr']::text[],'Şuna birkaç yorum bıraktım: ….','draft');
insert into public.patterns (id,template_en,slot_key,example_en,example_tr,chunks,grammar_note_id,context_tags,tone_tags,template_tr,status) values ('d4c7c769-160e-5c0c-becf-f5944cd54fe2','I''m not sure about …','sure about','I''m not sure about this approach.','Bu yaklaşımdan emin değilim.','[{"en":"I''m not sure","tr":"emin değilim"},{"en":"about","tr":"… hakkında"},{"en":"this approach","tr":"konu"}]'::jsonb,'451cf418-a1b2-5782-8a95-8dc5c6a0b92d',array['Kod inceleme','Toplantı']::text[],array['Temkinli']::text[],'Şundan emin değilim: ….','draft');
insert into public.patterns (id,template_en,slot_key,example_en,example_tr,chunks,grammar_note_id,context_tags,tone_tags,template_tr,status) values ('3be75488-3984-5917-bb89-9e4a1be97536','I''ve updated the PR based on …','based on','I''ve updated the PR based on your feedback.','PR''ı geri bildirimine göre güncelledim.','[{"en":"I''ve updated the PR","tr":"PR''ı güncelledim"},{"en":"based on","tr":"… göre"},{"en":"your feedback","tr":"dayanak"}]'::jsonb,'6a11b3cb-d93f-533d-b6d2-56af6ab35df5',array['Kod inceleme']::text[],array['Nötr']::text[],'PR''ı şuna göre güncelledim: ….','draft');
insert into public.patterns (id,template_en,slot_key,example_en,example_tr,chunks,grammar_note_id,context_tags,tone_tags,template_tr,status) values ('27660a55-2c0a-5838-a593-1f521e61139e','Is there a reason why …?','reason why','Is there a reason why we don''t use the existing helper?','Mevcut yardımcı fonksiyonu kullanmamamızın bir nedeni var mı?','[{"en":"Is there a reason","tr":"bir nedeni var mı"},{"en":"why","tr":"neden"},{"en":"we don''t use the existing helper","tr":"sorulan durum"}]'::jsonb,'61191619-612d-5027-a1fe-6212fc28bc5e',array['Kod inceleme']::text[],array['Nazik']::text[],'Şunun bir nedeni var mı: …?','draft');
insert into public.patterns (id,template_en,slot_key,example_en,example_tr,chunks,grammar_note_id,context_tags,tone_tags,template_tr,status) values ('0262ab52-1953-59c0-88b3-a66f7846d997','This will break … if …','break','This will break the build if the file is missing.','Dosya yoksa bu, derlemeyi bozar.','[{"en":"This will break","tr":"bu bozar"},{"en":"the build","tr":"etkilenen şey"},{"en":"if the file is missing","tr":"dosya yoksa"}]'::jsonb,'3bf15cc6-24b0-5ade-bd72-578e2cc35706',array['Kod inceleme']::text[],array['Uyarı']::text[],'Dosya yoksa bu, şunu bozar: ….','draft');
insert into public.patterns (id,template_en,slot_key,example_en,example_tr,chunks,grammar_note_id,context_tags,tone_tags,template_tr,status) values ('3af08709-f3b4-500f-a3b2-c517c381a237','Thanks for …','for the review','Thanks for the review, I''ll fix it now.','İnceleme için teşekkürler, hemen düzeltiyorum.','[{"en":"Thanks","tr":"teşekkürler"},{"en":"for the review","tr":"… için"}]'::jsonb,'61191619-612d-5027-a1fe-6212fc28bc5e',array['Kod inceleme','Ekip mesajı']::text[],array['Nazik']::text[],'Şunun için teşekkürler: ….','draft');
insert into public.patterns (id,template_en,slot_key,example_en,example_tr,chunks,grammar_note_id,context_tags,tone_tags,template_tr,status) values ('e10e4121-d7f2-5c7a-bd28-373f13b7e08b','I''m getting … when …','getting','I''m getting a 500 error when I log in.','Giriş yaptığımda 500 hatası alıyorum.','[{"en":"I''m getting","tr":"alıyorum"},{"en":"a 500 error","tr":"hata"},{"en":"when I log in","tr":"giriş yaptığımda"}]'::jsonb,'07f46ae3-6018-5f8f-8bda-377e874ddc92',array['Hata bildirme','Ekip mesajı']::text[],array['Nötr']::text[],'Giriş yaptığımda şunu alıyorum: ….','draft');
insert into public.patterns (id,template_en,slot_key,example_en,example_tr,chunks,grammar_note_id,context_tags,tone_tags,template_tr,status) values ('755b710c-445c-547f-84be-10b8a1f1284d','It started … after …','failing','It started failing after the last update.','Son güncellemeden sonra hata vermeye başladı.','[{"en":"It started","tr":"başladı"},{"en":"failing","tr":"hata vermeye"},{"en":"after the last update","tr":"son güncellemeden sonra"}]'::jsonb,'6abb00b5-f7d0-5462-97e1-00928664f27f',array['Hata bildirme']::text[],array['Nötr']::text[],'Son güncellemeden sonra şu başladı: ….','draft');
insert into public.patterns (id,template_en,slot_key,example_en,example_tr,chunks,grammar_note_id,context_tags,tone_tags,template_tr,status) values ('66196c9f-b01a-554f-9d1d-4ac6f93654ca','Have you tried …?','tried','Have you tried clearing the cache?','Önbelleği temizlemeyi denedin mi?','[{"en":"Have you tried","tr":"denedin mi"},{"en":"clearing the cache","tr":"önerilen çözüm (-ing)"}]'::jsonb,'6a11b3cb-d93f-533d-b6d2-56af6ab35df5',array['Yardım etme','Ekip mesajı']::text[],array['Nazik']::text[],'Şunu denedin mi: …?','draft');
insert into public.patterns (id,template_en,slot_key,example_en,example_tr,chunks,grammar_note_id,context_tags,tone_tags,template_tr,status) values ('a862f106-bdc7-5ce7-92a5-09b434ddf592','The problem seems to be …','seems to be','The problem seems to be in the config file.','Sorun yapılandırma dosyasında gibi görünüyor.','[{"en":"The problem","tr":"sorun"},{"en":"seems to be","tr":"gibi görünüyor"},{"en":"in the config file","tr":"yer"}]'::jsonb,'61191619-612d-5027-a1fe-6212fc28bc5e',array['Hata bildirme','Toplantı']::text[],array['Temkinli']::text[],'Sorun şurada gibi görünüyor: ….','draft');
insert into public.patterns (id,template_en,slot_key,example_en,example_tr,chunks,grammar_note_id,context_tags,tone_tags,template_tr,status) values ('d9336008-94f9-53fc-92f4-49edce0f2b3b','I fixed it by …','by','I fixed it by updating the driver.','Sürücüyü güncelleyerek düzelttim.','[{"en":"I fixed it","tr":"düzelttim"},{"en":"by","tr":"-erek"},{"en":"updating the driver","tr":"yöntem (-ing)"}]'::jsonb,'6abb00b5-f7d0-5462-97e1-00928664f27f',array['Durum bildirme','Ekip mesajı']::text[],array['Nötr']::text[],'Şunu yaparak düzelttim: ….','draft');
insert into public.patterns (id,template_en,slot_key,example_en,example_tr,chunks,grammar_note_id,context_tags,tone_tags,template_tr,status) values ('aaea652c-a224-5827-ad3c-e171af3c00b2','It should be fixed in …','should be fixed','It should be fixed in the next build.','Bir sonraki derlemede düzelmiş olması gerekiyor.','[{"en":"It should be","tr":"olması gerekir"},{"en":"fixed","tr":"düzeltilmiş"},{"en":"in the next build","tr":"zaman/yer"}]'::jsonb,'65dafd22-780c-55e5-96c7-520eb58691f9',array['Durum bildirme','Müşteriye yanıt']::text[],array['Temkinli']::text[],'Şurada düzelmiş olması gerekiyor: ….','draft');
insert into public.patterns (id,template_en,slot_key,example_en,example_tr,chunks,grammar_note_id,context_tags,tone_tags,template_tr,status) values ('a3ee9ff0-d785-58f8-bfba-5e3f82526356','Can you check if …?','check if','Can you check if the API is up?','API''nin çalışıp çalışmadığını kontrol edebilir misin?','[{"en":"Can you","tr":"-ebilir misin"},{"en":"check if","tr":"… mı diye kontrol et-"},{"en":"the API is up","tr":"kontrol edilen durum"}]'::jsonb,'d5e18b4b-8396-58e1-90d3-60ff590c1767',array['Yardım isteme','Ekip mesajı']::text[],array['Samimi']::text[],'Şunu kontrol edebilir misin: …?','draft');
insert into public.patterns (id,template_en,slot_key,example_en,example_tr,chunks,grammar_note_id,context_tags,tone_tags,template_tr,status) values ('e591c7a6-b124-5edf-9378-7bc920446660','I noticed that …','noticed','I noticed that the images load slowly.','Görsellerin yavaş yüklendiğini fark ettim.','[{"en":"I noticed","tr":"fark ettim"},{"en":"that","tr":"-dığını"},{"en":"the images load slowly","tr":"fark edilen durum"}]'::jsonb,'6abb00b5-f7d0-5462-97e1-00928664f27f',array['Hata bildirme','Kod inceleme']::text[],array['Nötr']::text[],'Şunu fark ettim: ….','draft');
insert into public.patterns (id,template_en,slot_key,example_en,example_tr,chunks,grammar_note_id,context_tags,tone_tags,template_tr,status) values ('bfc1c6cb-3136-5e4f-8d52-83f5736da428','The error says …','says','The error says ''permission denied''.','Hata “izin reddedildi” diyor.','[{"en":"The error","tr":"hata (mesajı)"},{"en":"says","tr":"diyor"},{"en":"''permission denied''","tr":"mesaj metni"}]'::jsonb,'61191619-612d-5027-a1fe-6212fc28bc5e',array['Hata bildirme']::text[],array['Nötr']::text[],'Hata şunu diyor: ….','draft');
insert into public.patterns (id,template_en,slot_key,example_en,example_tr,chunks,grammar_note_id,context_tags,tone_tags,template_tr,status) values ('f3c2001f-a806-553f-92f5-d033846c3723','It only happens when …','happens','It only happens when the user is offline.','Yalnızca kullanıcı çevrimdışıyken oluyor.','[{"en":"It only happens","tr":"yalnızca oluyor"},{"en":"when","tr":"-dığında"},{"en":"the user is offline","tr":"koşul"}]'::jsonb,'61191619-612d-5027-a1fe-6212fc28bc5e',array['Hata bildirme']::text[],array['Nötr']::text[],'Yalnızca şu durumda oluyor: ….','draft');
insert into public.patterns (id,template_en,slot_key,example_en,example_tr,chunks,grammar_note_id,context_tags,tone_tags,template_tr,status) values ('0c511d7b-7bdb-525e-b42f-491f0ca4abe5','I''m working on …','working on','I''m working on the login page.','Giriş sayfası üzerinde çalışıyorum.','[{"en":"I''m","tr":"ben (-yorum)"},{"en":"working on","tr":"üzerinde çalış-"},{"en":"the login page","tr":"değişen iş"}]'::jsonb,'07f46ae3-6018-5f8f-8bda-377e874ddc92',array['Toplantı','Ekip mesajı']::text[],array['Günlük']::text[],'… üzerinde çalışıyorum.','draft');
insert into public.patterns (id,template_en,slot_key,example_en,example_tr,chunks,grammar_note_id,context_tags,tone_tags,template_tr,status) values ('08114d70-ea33-5db5-b4e5-64308c03b4e6','I''m stuck on …','stuck on','I''m stuck on the database migration.','Veritabanı taşıma işinde takıldım.','[{"en":"I''m stuck","tr":"takıldım"},{"en":"on","tr":"(bir şey) üzerinde"},{"en":"the database migration","tr":"sorunlu iş"}]'::jsonb,'451cf418-a1b2-5782-8a95-8dc5c6a0b92d',array['Toplantı','Yardım isteme']::text[],array['Günlük']::text[],'Şurada takıldım: ….','draft');
insert into public.patterns (id,template_en,slot_key,example_en,example_tr,chunks,grammar_note_id,context_tags,tone_tags,template_tr,status) values ('0a8b2822-c804-515d-a3ee-f4608831c53d','Could you take a look at …?','Could you take a look at','Could you take a look at my pull request?','Pull request''ime bir göz atabilir misin?','[{"en":"Could you","tr":"-ebilir misin"},{"en":"take a look at","tr":"bir göz at-"},{"en":"my pull request","tr":"bakılacak şey"}]'::jsonb,'d5e18b4b-8396-58e1-90d3-60ff590c1767',array['Kod inceleme','Yardım isteme']::text[],array['Nazik']::text[],'Şuna bir göz atabilir misin: …?','draft');
insert into public.patterns (id,template_en,slot_key,example_en,example_tr,chunks,grammar_note_id,context_tags,tone_tags,template_tr,status) values ('9b236b92-c4ad-5f11-b132-30bc7756cf22','I''ve finished …','finished','I''ve finished the API integration.','API entegrasyonunu bitirdim.','[{"en":"I''ve","tr":"(ben) -dim"},{"en":"finished","tr":"bitir-"},{"en":"the API integration","tr":"biten iş"}]'::jsonb,'6a11b3cb-d93f-533d-b6d2-56af6ab35df5',array['Toplantı','Durum raporu']::text[],array['Günlük']::text[],'Şunu bitirdim: ….','draft');
insert into public.patterns (id,template_en,slot_key,example_en,example_tr,chunks,grammar_note_id,context_tags,tone_tags,template_tr,status) values ('55b74f94-6c30-5a3a-81c8-835664822b71','Today I''m going to …','going to','Today I''m going to write the unit tests.','Bugün birim testlerini yazacağım.','[{"en":"Today","tr":"bugün"},{"en":"I''m going to","tr":"-eceğim (plan)"},{"en":"write the unit tests","tr":"yapılacak iş"}]'::jsonb,'4a9d24f3-029d-5fcb-bf70-fa727ed9e5c5',array['Toplantı','Durum raporu']::text[],array['Günlük']::text[],'Bugün şunu yapacağım: ….','draft');
insert into public.patterns (id,template_en,slot_key,example_en,example_tr,chunks,grammar_note_id,context_tags,tone_tags,template_tr,status) values ('c1739b6d-bfe2-50d6-9e70-023b3cee37ad','I need some help with …','help with','I need some help with the deployment script.','Dağıtım betiğinde biraz yardıma ihtiyacım var.','[{"en":"I need","tr":"ihtiyacım var"},{"en":"some help with","tr":"biraz yardım (… konusunda)"},{"en":"the deployment script","tr":"konu"}]'::jsonb,'61191619-612d-5027-a1fe-6212fc28bc5e',array['Yardım isteme','Ekip mesajı']::text[],array['Nötr']::text[],'Şu konuda biraz yardıma ihtiyacım var: ….','draft');
insert into public.patterns (id,template_en,slot_key,example_en,example_tr,chunks,grammar_note_id,context_tags,tone_tags,template_tr,status) values ('05080be0-da92-5dc0-bde9-c3bdf334f1cf','I''m waiting for …','waiting for','I''m waiting for feedback from the client.','Müşteriden geri bildirim bekliyorum.','[{"en":"I''m waiting","tr":"bekliyorum"},{"en":"for","tr":"(bir şeyi)"},{"en":"feedback from the client","tr":"beklenen şey"}]'::jsonb,'07f46ae3-6018-5f8f-8bda-377e874ddc92',array['Toplantı','Durum raporu']::text[],array['Nötr']::text[],'Şunu bekliyorum: ….','draft');
insert into public.patterns (id,template_en,slot_key,example_en,example_tr,chunks,grammar_note_id,context_tags,tone_tags,template_tr,status) values ('10ad0c1a-14fa-5a1d-81d3-e0fbe3fb0cac','Any updates on …?','updates on','Any updates on the payment bug?','Ödeme hatasıyla ilgili yeni bir gelişme var mı?','[{"en":"Any updates","tr":"yeni gelişme var mı"},{"en":"on","tr":"… ile ilgili"},{"en":"the payment bug","tr":"konu"}]'::jsonb,'61191619-612d-5027-a1fe-6212fc28bc5e',array['Ekip mesajı','Toplantı']::text[],array['Samimi']::text[],'Şu konuda yeni bir gelişme var mı: …?','draft');
insert into public.patterns (id,template_en,slot_key,example_en,example_tr,chunks,grammar_note_id,context_tags,tone_tags,template_tr,status) values ('0b2c5e67-1b09-55b8-86e7-127253fb9537','I''ll share … with the team.','share','I''ll share the meeting notes with the team.','Toplantı notlarını ekiple paylaşacağım.','[{"en":"I''ll","tr":"-eceğim"},{"en":"share","tr":"paylaş-"},{"en":"the meeting notes","tr":"paylaşılan şey"},{"en":"with the team","tr":"ekiple"}]'::jsonb,'4a9d24f3-029d-5fcb-bf70-fa727ed9e5c5',array['Toplantı','Ekip mesajı']::text[],array['Nötr']::text[],'Şunu ekiple paylaşacağım: ….','draft');
insert into public.patterns (id,template_en,slot_key,example_en,example_tr,chunks,grammar_note_id,context_tags,tone_tags,template_tr,status) values ('70f85303-5ca0-5b90-8c2c-66222b65a74b','Could we move … to …?','move','Could we move the demo to Thursday?','Demoyu perşembeye alabilir miyiz?','[{"en":"Could we","tr":"-ebilir miyiz"},{"en":"move","tr":"taşı-, al-"},{"en":"the demo","tr":"etkinlik"},{"en":"to Thursday","tr":"perşembeye"}]'::jsonb,'d5e18b4b-8396-58e1-90d3-60ff590c1767',array['Planlama','Ekip mesajı']::text[],array['Nazik']::text[],'Şunu başka bir güne alabilir miyiz: …?','draft');
insert into public.patterns (id,template_en,slot_key,example_en,example_tr,chunks,grammar_note_id,context_tags,tone_tags,template_tr,status) values ('c05b1a7e-f245-527a-b8ce-551e51fd5a75','Although …, …','Although','Although the test was difficult, most students passed.','Sınav zor olmasına rağmen öğrencilerin çoğu geçti.','[{"en":"Although","tr":"-e rağmen (+ cümle)"},{"en":"the test was difficult","tr":"sınav zordu"},{"en":"most students passed","tr":"öğrencilerin çoğu geçti"}]'::jsonb,'18bb25a1-8990-5403-bef1-60ed86047678',array['Cümle tamamlama']::text[],array['Akademik']::text[],'… olmasına rağmen öğrencilerin çoğu geçti.','draft');
insert into public.patterns (id,template_en,slot_key,example_en,example_tr,chunks,grammar_note_id,context_tags,tone_tags,template_tr,status) values ('a308e396-daed-5e15-8493-d90b33730bd0','Despite …, …','Despite','Despite the rain, the event was a success.','Yağmura rağmen etkinlik başarılı geçti.','[{"en":"Despite","tr":"-e rağmen (+ isim)"},{"en":"the rain","tr":"yağmur"},{"en":"the event was a success","tr":"etkinlik başarılıydı"}]'::jsonb,'18bb25a1-8990-5403-bef1-60ed86047678',array['Cümle tamamlama']::text[],array['Akademik']::text[],'… rağmen etkinlik başarılı geçti.','draft');
insert into public.patterns (id,template_en,slot_key,example_en,example_tr,chunks,grammar_note_id,context_tags,tone_tags,template_tr,status) values ('47739fcc-552d-50cf-a5f0-3088a32d88f9','…, whereas …','whereas','Some species adapt quickly, whereas others die out.','Bazı türler hızla uyum sağlarken diğerleri yok oluyor.','[{"en":"Some species adapt quickly","tr":"bazı türler hızla uyum sağlar"},{"en":"whereas","tr":"oysa, -iken"},{"en":"others die out","tr":"diğerleri yok olur"}]'::jsonb,'18bb25a1-8990-5403-bef1-60ed86047678',array['Cümle tamamlama','Paragraf']::text[],array['Akademik']::text[],'Bazı türler hızla uyum sağlarken diğerleri ….','draft');
insert into public.patterns (id,template_en,slot_key,example_en,example_tr,chunks,grammar_note_id,context_tags,tone_tags,template_tr,status) values ('8e266ee9-5c45-5ac3-a74b-fc5c7672ee47','…; however, …','however','The method is cheap; however, it is not very accurate.','Yöntem ucuz; ancak çok hassas değil.','[{"en":"The method is cheap","tr":"yöntem ucuz"},{"en":"however","tr":"ancak"},{"en":"it is not very accurate","tr":"karşıt bilgi"}]'::jsonb,'18bb25a1-8990-5403-bef1-60ed86047678',array['Paragraf','Cümle tamamlama']::text[],array['Akademik']::text[],'Yöntem ucuz; ancak ….','draft');
insert into public.patterns (id,template_en,slot_key,example_en,example_tr,chunks,grammar_note_id,context_tags,tone_tags,template_tr,status) values ('741d4a17-0c9c-596b-b053-aa2e824c1ea8','…; therefore, …','therefore','Fuel prices rose sharply; therefore, airline tickets became more expensive.','Yakıt fiyatları keskin biçimde arttı; bu nedenle uçak biletleri pahalandı.','[{"en":"Fuel prices rose sharply","tr":"yakıt fiyatları keskin biçimde arttı"},{"en":"therefore","tr":"bu nedenle"},{"en":"airline tickets became more expensive","tr":"sonuç"}]'::jsonb,'1b0b85f6-765e-57cd-838b-8e483d2c0e86',array['Paragraf','Cümle tamamlama']::text[],array['Akademik']::text[],'Yakıt fiyatları keskin biçimde arttı; bu nedenle ….','draft');
insert into public.patterns (id,template_en,slot_key,example_en,example_tr,chunks,grammar_note_id,context_tags,tone_tags,template_tr,status) values ('491fdfae-8975-5b64-8f3e-a20c495494e6','… because of …','because of','The match was postponed because of heavy snow.','Maç yoğun kar yüzünden ertelendi.','[{"en":"The match was postponed","tr":"maç ertelendi"},{"en":"because of","tr":"yüzünden (+ isim)"},{"en":"heavy snow","tr":"neden"}]'::jsonb,'1b0b85f6-765e-57cd-838b-8e483d2c0e86',array['Cümle tamamlama']::text[],array['Akademik']::text[],'Maç şu yüzden ertelendi: ….','draft');
insert into public.patterns (id,template_en,slot_key,example_en,example_tr,chunks,grammar_note_id,context_tags,tone_tags,template_tr,status) values ('c564e1d1-c506-558a-b3f2-0faf2fb1a93b','… so that …','so that','She saved money so that she could study abroad.','Yurt dışında okuyabilmek için para biriktirdi.','[{"en":"She saved money","tr":"para biriktirdi"},{"en":"so that","tr":"-sın diye, -mek için"},{"en":"she could study abroad","tr":"amaç"}]'::jsonb,'1b0b85f6-765e-57cd-838b-8e483d2c0e86',array['Cümle tamamlama']::text[],array['Akademik']::text[],'Şunu yapabilmek için para biriktirdi: ….','draft');
insert into public.patterns (id,template_en,slot_key,example_en,example_tr,chunks,grammar_note_id,context_tags,tone_tags,template_tr,status) values ('40d0887e-dd6d-5339-a2b9-90f7f45c5c3a','Unlike …, …','Unlike','Unlike her brother, she enjoys math.','Ağabeyinin aksine matematiği seviyor.','[{"en":"Unlike her brother","tr":"ağabeyinin aksine"},{"en":"she enjoys math","tr":"matematiği seviyor"}]'::jsonb,'18bb25a1-8990-5403-bef1-60ed86047678',array['Cümle tamamlama']::text[],array['Akademik']::text[],'… aksine matematiği seviyor.','draft');
insert into public.patterns (id,template_en,slot_key,example_en,example_tr,chunks,grammar_note_id,context_tags,tone_tags,template_tr,status) values ('f87f9b2d-a453-5086-a2db-d9df4d2d27ce','…. In contrast, …','In contrast','Northern cities are cold. In contrast, southern cities are warm.','Kuzey şehirleri soğuk. Buna karşılık güney şehirleri sıcak.','[{"en":"Northern cities are cold","tr":"kuzey şehirleri soğuk"},{"en":"In contrast","tr":"buna karşılık"},{"en":"southern cities are warm","tr":"karşıt bilgi"}]'::jsonb,'18bb25a1-8990-5403-bef1-60ed86047678',array['Paragraf']::text[],array['Akademik']::text[],'Kuzey şehirleri soğuk. Buna karşılık ….','draft');
insert into public.patterns (id,template_en,slot_key,example_en,example_tr,chunks,grammar_note_id,context_tags,tone_tags,template_tr,status) values ('051fdaf0-b840-5e97-8f70-f497e7bc526c','…; otherwise, …','otherwise','Save your work often; otherwise, you may lose it.','Çalışmanı sık sık kaydet; aksi takdirde kaybedebilirsin.','[{"en":"Save your work often","tr":"çalışmanı sık kaydet"},{"en":"otherwise","tr":"aksi takdirde"},{"en":"you may lose it","tr":"olası sonuç"}]'::jsonb,'1b0b85f6-765e-57cd-838b-8e483d2c0e86',array['Cümle tamamlama']::text[],array['Akademik']::text[],'Çalışmanı sık sık kaydet; aksi takdirde ….','draft');
insert into public.patterns (id,template_en,slot_key,example_en,example_tr,chunks,grammar_note_id,context_tags,tone_tags,template_tr,status) values ('9db36306-fe3c-5d1b-bbea-8ac38cf71dc2','… increased from … to …','from','The price increased from 10 to 15 dollars.','Fiyat 10 dolardan 15 dolara çıktı.','[{"en":"The price increased","tr":"fiyat arttı"},{"en":"from 10","tr":"10''dan"},{"en":"to 15 dollars","tr":"15 dolara"}]'::jsonb,'720f608f-5573-5769-bc14-e12bd1dbaa95',array['Grafik']::text[],array['Akademik']::text[],'Fiyat … çıktı.','draft');
insert into public.patterns (id,template_en,slot_key,example_en,example_tr,chunks,grammar_note_id,context_tags,tone_tags,template_tr,status) values ('59a7a2e0-846d-5b5c-bdd1-eac4c14ea33b','… has risen since …','has risen','The number of users has risen since 2020.','Kullanıcı sayısı 2020''den beri arttı.','[{"en":"The number of users","tr":"kullanıcı sayısı"},{"en":"has risen","tr":"arttı (ve etkisi sürüyor)"},{"en":"since 2020","tr":"2020''den beri"}]'::jsonb,'c2448d19-7c6a-5373-b84f-f0ecdb345163',array['Grafik','Paragraf']::text[],array['Akademik']::text[],'Kullanıcı sayısı şundan beri arttı: ….','draft');
insert into public.patterns (id,template_en,slot_key,example_en,example_tr,chunks,grammar_note_id,context_tags,tone_tags,template_tr,status) values ('3596ab13-2220-56c8-9621-91e020c26711','There was a … rise in …','in','There was a sharp rise in food prices.','Gıda fiyatlarında keskin bir artış oldu.','[{"en":"There was","tr":"oldu"},{"en":"a sharp rise","tr":"keskin bir artış"},{"en":"in food prices","tr":"gıda fiyatlarında"}]'::jsonb,'720f608f-5573-5769-bc14-e12bd1dbaa95',array['Grafik']::text[],array['Akademik']::text[],'Şunda keskin bir artış oldu: ….','draft');
insert into public.patterns (id,template_en,slot_key,example_en,example_tr,chunks,grammar_note_id,context_tags,tone_tags,template_tr,status) values ('f1de5645-020e-5650-8cce-58a1314f2ad0','… fell by …','by','Unemployment fell by two percentage points.','İşsizlik iki yüzde puan düştü.','[{"en":"Unemployment fell","tr":"işsizlik düştü"},{"en":"by","tr":"… kadar (değişim miktarı)"},{"en":"two percentage points","tr":"miktar"}]'::jsonb,'720f608f-5573-5769-bc14-e12bd1dbaa95',array['Grafik']::text[],array['Akademik']::text[],'İşsizlik şu kadar düştü: ….','draft');
insert into public.patterns (id,template_en,slot_key,example_en,example_tr,chunks,grammar_note_id,context_tags,tone_tags,template_tr,status) values ('90c1b6e1-c1d7-5d96-97ce-bc88f62844d0','The number of … has …','The number of','The number of students has grown.','Öğrenci sayısı arttı.','[{"en":"The number of","tr":"… sayısı (tekil)"},{"en":"students","tr":"sayılan şey"},{"en":"has grown","tr":"arttı"}]'::jsonb,'c2448d19-7c6a-5373-b84f-f0ecdb345163',array['Grafik','Paragraf']::text[],array['Akademik']::text[],'… sayısı arttı.','draft');
insert into public.patterns (id,template_en,slot_key,example_en,example_tr,chunks,grammar_note_id,context_tags,tone_tags,template_tr,status) values ('c5cc0df3-9d95-5b15-8249-397e06245ade','… -er than in …','than','Sales were higher than in 2022.','Satışlar 2022''dekinden daha yüksekti.','[{"en":"Sales were higher","tr":"satışlar daha yüksekti"},{"en":"than","tr":"-den"},{"en":"in 2022","tr":"karşılaştırılan"}]'::jsonb,'456ec5da-d7b5-550b-9e0c-056b23139658',array['Grafik']::text[],array['Akademik']::text[],'Satışlar şundan daha yüksekti: ….','draft');
insert into public.patterns (id,template_en,slot_key,example_en,example_tr,chunks,grammar_note_id,context_tags,tone_tags,template_tr,status) values ('74f8fdaa-2059-5ee6-98f4-9cef001337e2','… remained … throughout …','throughout','Prices remained stable throughout the year.','Fiyatlar yıl boyunca sabit kaldı.','[{"en":"Prices remained stable","tr":"fiyatlar sabit kaldı"},{"en":"throughout","tr":"boyunca"},{"en":"the year","tr":"süre"}]'::jsonb,'720f608f-5573-5769-bc14-e12bd1dbaa95',array['Grafik']::text[],array['Akademik']::text[],'Fiyatlar şu süre boyunca sabit kaldı: ….','draft');
