insert into public.patterns (id,template_en,slot_key,example_en,example_tr,chunks,grammar_note_id,context_tags,tone_tags,template_tr,status) values ('4248f873-b86f-5f7b-8444-9e6136ab04c1','By the end of …, …','By the end of','By the end of 2030, the population will reach 90 million.','2030 sonuna kadar nüfus 90 milyona ulaşacak.','[{"en":"By the end of 2030","tr":"2030 sonuna kadar"},{"en":"the population will reach","tr":"nüfus ulaşacak"},{"en":"90 million","tr":"değer"}]'::jsonb,'4a9d24f3-029d-5fcb-bf70-fa727ed9e5c5',array['Tahmin','Paragraf']::text[],array['Akademik']::text[],'… sonuna kadar nüfus 90 milyona ulaşacak.','draft');
insert into public.patterns (id,template_en,slot_key,example_en,example_tr,chunks,grammar_note_id,context_tags,tone_tags,template_tr,status) values ('4c6a8ae5-21b6-508c-82a9-9df47b76da57','The results suggest that …','suggest that','The results suggest that exercise improves memory.','Sonuçlar egzersizin hafızayı geliştirdiğini düşündürüyor.','[{"en":"The results","tr":"sonuçlar"},{"en":"suggest that","tr":"-dığını düşündürüyor (temkinli)"},{"en":"exercise improves memory","tr":"bulgu"}]'::jsonb,'bfcf9a85-caf2-5d11-b852-1fdd48d940df',array['Akademik metin']::text[],array['Temkinli']::text[],'Sonuçlar şunu düşündürüyor: ….','draft');
insert into public.patterns (id,template_en,slot_key,example_en,example_tr,chunks,grammar_note_id,context_tags,tone_tags,template_tr,status) values ('9ff6ccc1-c387-514e-9147-ef4c5603a985','It has been shown that …','has been shown','It has been shown that bilingual children learn faster.','İki dilli çocukların daha hızlı öğrendiği gösterilmiştir.','[{"en":"It has been shown","tr":"gösterilmiştir"},{"en":"that","tr":"-dığı"},{"en":"bilingual children learn faster","tr":"bulgu"}]'::jsonb,'65dafd22-780c-55e5-96c7-520eb58691f9',array['Akademik metin']::text[],array['Resmî']::text[],'Şu gösterilmiştir: ….','draft');
insert into public.patterns (id,template_en,slot_key,example_en,example_tr,chunks,grammar_note_id,context_tags,tone_tags,template_tr,status) values ('735d5503-77b9-568d-b56d-6b379ac285ba','a study which …','which','This is a study which examined 500 schools.','Bu, 500 okulu inceleyen bir çalışma.','[{"en":"a study","tr":"bir çalışma"},{"en":"which","tr":"ki o (nesne için)"},{"en":"examined 500 schools","tr":"açıklama"}]'::jsonb,'5745b079-cf8a-5e9d-9c2f-f10b9ed53ed7',array['Akademik metin']::text[],array['Resmî']::text[],'Bu, şunu yapan bir çalışma: ….','draft');
