insert into public.patterns (id,template_en,slot_key,example_en,example_tr,chunks,grammar_note_id,context_tags,tone_tags,template_tr,status) values ('2194e5c3-6f95-56b8-8095-110bbd026f15','The aim of this study is to …','The aim of this study is','The aim of this study is to investigate the effects of noise.','Bu çalışmanın amacı gürültünün etkilerini araştırmaktır.','[{"en":"The aim of this study","tr":"bu çalışmanın amacı"},{"en":"is","tr":"-dır"},{"en":"to investigate …","tr":"amaç (to + fiil)"}]'::jsonb,'61191619-612d-5027-a1fe-6212fc28bc5e',array['Akademik metin']::text[],array['Resmî']::text[],'Bu çalışmanın amacı şudur: ….','draft');
