insert into public.exercises (id,target_id,type,skill,prompt,answer,accepted_answers,distractor_notes,explanation_tr,difficulty,status) values ('151cf7e7-52d1-53b8-9785-55c50739ee0b','732e3b35-32db-5648-9e2c-379ba6239a2a','listen_choice','listening','{"instruction_tr":"Cümleyi dinle. Anlamı hangisi?","audio_text":"We have an issue with the cooling system.","options":["En basit çözüm bir fan eklemek.","Yüksek hızda güçlü bir titreşim var.","Boru bağlantısında sızıntı bulduk.","Soğutma sisteminde bir sorunumuz var."]}'::jsonb,'{"index":3}'::jsonb,array[]::text[],'{"Boru bağlantısında sızıntı bulduk.":"Bu, “leakage” örneğinin çevirisi.","Yüksek hızda güçlü bir titreşim var.":"Bu, “vibration” örneğinin çevirisi.","En basit çözüm bir fan eklemek.":"Bu, “solution” örneğinin çevirisi."}'::jsonb,'“We have an issue with the cooling system.” = Soğutma sisteminde bir sorunumuz var.',1,'draft');
