insert into public.exercises (id,target_id,type,skill,prompt,answer,accepted_answers,distractor_notes,explanation_tr,difficulty,status) values ('789d702a-cc10-58e2-abba-c99e2e85ba00','97410850-04ff-57c6-822b-9b1eebc41dce','meaning_choice','reading','{"instruction_tr":"Bu cümlenin anlamı hangisi?","text":"We could either repair the pump or buy a new one.","options":["Ya pompayı tamir edebiliriz ya da yenisini alabiliriz.","Güvenlik nedeniyle laboratuvarda eldiven tak.","Bir fan eklersek sıcaklık düşer.","Sorun, kablonun fazla ince olması."]}'::jsonb,'{"index":0}'::jsonb,array[]::text[],'{"Güvenlik nedeniyle laboratuvarda eldiven tak.":"Bu, “For safety reasons, wear gloves in the lab.” cümlesinin anlamı.","Bir fan eklersek sıcaklık düşer.":"Bu, “If we add a fan, the temperature will drop.” cümlesinin anlamı.","Sorun, kablonun fazla ince olması.":"Bu, “The problem is that the cable is too thin.” cümlesinin anlamı."}'::jsonb,'We could either repair the pump or buy a new one. = Ya pompayı tamir edebiliriz ya da yenisini alabiliriz.',2,'draft');
