insert into public.exercises (id,target_id,type,skill,prompt,answer,accepted_answers,distractor_notes,explanation_tr,difficulty,status) values ('faa82c9d-9f4b-5067-b6b0-58ef96752d07','ab707def-a7f0-5fe4-afb2-0cc8f0cf2568','meaning_choice','reading','{"instruction_tr":"Bu cümlenin anlamı hangisi?","text":"For safety reasons, wear gloves in the lab.","options":["Bir fan eklersek sıcaklık düşer.","Seçeneklerden biri rulmanı değiştirmek.","Güvenlik nedeniyle laboratuvarda eldiven tak.","Sorun, kablonun fazla ince olması."]}'::jsonb,'{"index":2}'::jsonb,array[]::text[],'{"Bir fan eklersek sıcaklık düşer.":"Bu, “If we add a fan, the temperature will drop.” cümlesinin anlamı.","Sorun, kablonun fazla ince olması.":"Bu, “The problem is that the cable is too thin.” cümlesinin anlamı.","Seçeneklerden biri rulmanı değiştirmek.":"Bu, “One option is to replace the bearing.” cümlesinin anlamı."}'::jsonb,'For safety reasons, wear gloves in the lab. = Güvenlik nedeniyle laboratuvarda eldiven tak.',1,'draft');
insert into public.exercises (id,target_id,type,skill,prompt,answer,accepted_answers,distractor_notes,explanation_tr,difficulty,status) values ('1b632bc7-b17b-59ed-9c7d-14ba76551dc1','bd452d1c-f72a-5a10-aba9-dcb781346581','dialogue_choice','reading','{"instruction_tr":"Diyalogda en uygun yanıtı seç.","context":[{"speaker":"Manager","en":"Why does the machine keep stopping?"}],"options":["It overheats after about an hour. The problem is that the fan is too small.","It is overheat because the fan small.","It overhears after about an hour."],"scenario_id":"4ccdde2c-4345-55a0-a739-3b81887070ae"}'::jsonb,'{"index":0}'::jsonb,array[]::text[],'{"It is overheat because the fan small.":"Fiil yapısı bozuk ve ikinci cümlede “is” eksik.","It overhears after about an hour.":"“overhear” kulak misafiri olmak demektir."}'::jsonb,'Belirtiyi ve nedeni net anlatıyor.',2,'draft');
insert into public.exercises (id,target_id,type,skill,prompt,answer,accepted_answers,distractor_notes,explanation_tr,difficulty,status) values ('50469cec-1355-590a-bbf3-ef7dd6f0a266','bd452d1c-f72a-5a10-aba9-dcb781346581','dialogue_choice','reading','{"instruction_tr":"Diyalogda en uygun yanıtı seç.","context":[{"speaker":"Manager","en":"Why does the machine keep stopping?"},{"speaker":"Manager","en":"What do you suggest?"}],"options":["I suggest you to install a larger fan.","If we install a larger fan, the temperature will drop. It''s a cheap solution.","If we will install a larger fan, the temperature drops."],"scenario_id":"4ccdde2c-4345-55a0-a739-3b81887070ae"}'::jsonb,'{"index":1}'::jsonb,array[]::text[],'{"I suggest you to install a larger fan.":"“suggest you to” yanlış; “I suggest that we install …” denir.","If we will install a larger fan, the temperature drops.":"If''li kısımda “will” kullanılmaz; sonuç kısmında gerekir."}'::jsonb,'First conditional doğru kullanılmış ve gerekçe veriyor.',2,'draft');
insert into public.exercises (id,target_id,type,skill,prompt,answer,accepted_answers,distractor_notes,explanation_tr,difficulty,status) values ('413d7842-d6c6-5219-9f20-fd836fc459cc','43bfccda-4491-56cb-827f-e769d98cef4a','dialogue_choice','reading','{"instruction_tr":"Diyalogda en uygun yanıtı seç.","context":[{"speaker":"Colleague","en":"The new part won''t arrive until Friday. What can we do now?"}],"options":["As a temporary fix, we could use the spare part from line 2.","As a permanent fix, we can wait until Friday.","As a temporal fix, we could use the spare part from line 2."],"scenario_id":"b01af5ca-9ef0-5201-8c89-7ffabce2585b"}'::jsonb,'{"index":0}'::jsonb,array[]::text[],'{"As a permanent fix, we can wait until Friday.":"Beklemek kalıcı bir çözüm değildir; anlam çelişkili.","As a temporal fix, we could use the spare part from line 2.":"“temporal” zamanla ilgili demektir; “geçici” için “temporary” kullanılır."}'::jsonb,'Uygulanabilir geçici bir çözüm öneriyor.',3,'draft');
insert into public.exercises (id,target_id,type,skill,prompt,answer,accepted_answers,distractor_notes,explanation_tr,difficulty,status) values ('12378971-14c7-55a1-be3e-402e2a0c9267','43bfccda-4491-56cb-827f-e769d98cef4a','dialogue_choice','reading','{"instruction_tr":"Diyalogda en uygun yanıtı seç.","context":[{"speaker":"Colleague","en":"The new part won''t arrive until Friday. What can we do now?"},{"speaker":"Colleague","en":"Good idea, but line 2 will have some downtime."}],"options":["True, it''s a take-off.","True, it''s a trade-off. Two hours of downtime is better than three days.","True, so line 2 has no downtime."],"scenario_id":"b01af5ca-9ef0-5201-8c89-7ffabce2585b"}'::jsonb,'{"index":1}'::jsonb,array[]::text[],'{"True, it''s a take-off.":"“take-off” kalkış demektir.","True, so line 2 has no downtime.":"Az önce söyleneni inkâr ediyor; çelişkili."}'::jsonb,'Ödünleşimi görüp gerekçeyle karar veriyor.',3,'draft');
