insert into public.exercises (id,target_id,type,skill,prompt,answer,accepted_answers,distractor_notes,explanation_tr,difficulty,status) values ('4753dce7-a9e8-5e10-963b-d21211532554','a6858448-fbfc-5e83-a8af-7ce4d0a864a9','dialogue_choice','reading','{"instruction_tr":"Diyalogda en uygun yanıtı seç.","context":[{"speaker":"Test manager","en":"How did the vibration test go yesterday?"}],"options":["Eight units past, but two felt after 200 cycles.","Eight units are passing yesterday.","Eight units passed, but two failed after 200 cycles."],"scenario_id":"ad597b64-bc91-5e6a-ac47-51367354f2fa"}'::jsonb,'{"index":2}'::jsonb,array[]::text[],'{"Eight units past, but two felt after 200 cycles.":"“past” ve “felt” yanlış kelimeler: passed, failed.","Eight units are passing yesterday.":"“yesterday” ile geçmiş zaman gerekir."}'::jsonb,'Sonucu sayılarla ve net biçimde veriyor.',2,'draft');
insert into public.exercises (id,target_id,type,skill,prompt,answer,accepted_answers,distractor_notes,explanation_tr,difficulty,status) values ('791d470b-936f-52fb-a73c-537b94b545a3','a6858448-fbfc-5e83-a8af-7ce4d0a864a9','dialogue_choice','reading','{"instruction_tr":"Diyalogda en uygun yanıtı seç.","context":[{"speaker":"Test manager","en":"How did the vibration test go yesterday?"},{"speaker":"Test manager","en":"Do we know why the two units failed?"}],"options":["Yes, because they passed.","We found a small crack near the weld. We need to repeat the test with new samples.","We found a small crab near the weld."],"scenario_id":"ad597b64-bc91-5e6a-ac47-51367354f2fa"}'::jsonb,'{"index":1}'::jsonb,array[]::text[],'{"Yes, because they passed.":"Anlamsız: geçtikleri için başarısız olmadılar.","We found a small crab near the weld.":"“crab” yengeç demektir."}'::jsonb,'Nedeni ve sonraki adımı açıklıyor.',2,'draft');
