insert into public.exercises (id,target_id,type,skill,prompt,answer,accepted_answers,distractor_notes,explanation_tr,difficulty,status) values ('6191dbf7-6c14-5656-af63-64ba75187dcf','a10a7580-2b12-58a6-9341-3078301c7d05','dialogue_choice','reading','{"instruction_tr":"Diyalogda en uygun yanıtı seç.","context":[{"speaker":"Murat","en":"Hi, I''m Murat from the design team. You must be new here."},{"speaker":"Murat","en":"Nice to meet you too. Where are you from?"}],"options":["I''m originally from Trabzon, but I''ve lived in İstanbul for five years.","I''m from Trabzon since five years.","I live from Trabzon."],"scenario_id":"6549ddd3-72d2-5c59-9ad4-fed64eb0ee28"}'::jsonb,'{"index":0}'::jsonb,array[]::text[],'{"I''m from Trabzon since five years.":"Süre için “for” ve present perfect gerekir.","I live from Trabzon.":"“live from” denmez; “I''m from Trabzon” denir."}'::jsonb,'Aslen nereli olduğunu ve ne zamandır nerede yaşadığını doğru anlatıyor.',1,'draft');
