insert into public.exercises (id,target_id,type,skill,prompt,answer,accepted_answers,distractor_notes,explanation_tr,difficulty,status) values ('be7312d2-e03c-545f-a230-9117023f76c0','4d000725-ddb0-56f9-8259-b32b3a7f742c','dialogue_choice','reading','{"instruction_tr":"Diyalogda en uygun yanıtı seç.","context":[{"speaker":"Reviewer","en":"This logic is duplicated in two components. Could we move it to a shared helper?"},{"speaker":"Reviewer","en":"Thanks! Let me know when it''s ready for another look."}],"options":["Will do. I addressing all comments yesterday.","Will do. I''ve added all your comments to the code.","Will do. I''ve addressed all your comments now."],"scenario_id":"6f7cc84f-f7ed-58e0-b82b-3e642f341c02"}'::jsonb,'{"index":2}'::jsonb,array[]::text[],'{"Will do. I addressing all comments yesterday.":"Fiil zamanı yanlış.","Will do. I''ve added all your comments to the code.":"Yorumlar koda eklenmez; gereği yapılır (addressed)."}'::jsonb,'Kısa ve net; yorumların gereğinin yapıldığını bildiriyor.',2,'draft');
insert into public.exercises (id,target_id,type,skill,prompt,answer,accepted_answers,distractor_notes,explanation_tr,difficulty,status) values ('8e50cdfd-7b61-5edc-b834-5dcf4a93353f','b989cb15-0fba-5e2a-8780-384bfb12e524','dialogue_choice','reading','{"instruction_tr":"Diyalogda en uygun yanıtı seç.","context":[{"speaker":"Author","en":"Hi! Did you have a chance to look at my PR?"}],"options":["Yes, it is a nitpick, so I can''t approve.","Yes, looks good to me. Just one nitpick about a variable name.","Yes, looks good at me, no nitpicks for merge."],"scenario_id":"4775ddb6-ac52-573d-9c2d-5dfc36ad0202"}'::jsonb,'{"index":1}'::jsonb,array[]::text[],'{"Yes, it is a nitpick, so I can''t approve.":"Küçük bir not onayı engellemez; anlam çelişkili.","Yes, looks good at me, no nitpicks for merge.":"Edat yanlış ve cümle bozuk."}'::jsonb,'Onay veriyor ve küçük notu belirtiyor.',1,'draft');
insert into public.exercises (id,target_id,type,skill,prompt,answer,accepted_answers,distractor_notes,explanation_tr,difficulty,status) values ('5cb09299-e21f-5731-9598-f63b8b5acf44','b989cb15-0fba-5e2a-8780-384bfb12e524','dialogue_choice','reading','{"instruction_tr":"Diyalogda en uygun yanıtı seç.","context":[{"speaker":"Author","en":"Hi! Did you have a chance to look at my PR?"},{"speaker":"Author","en":"Thanks! Can I merge it after I fix that?"}],"options":["Sure, feel free to merge once the tests pass.","Sure, feel free merge.","Sure, feel free to merge before you write it."],"scenario_id":"4775ddb6-ac52-573d-9c2d-5dfc36ad0202"}'::jsonb,'{"index":0}'::jsonb,array[]::text[],'{"Sure, feel free merge.":"“feel free to + fiil” kalıbında “to” eksik.","Sure, feel free to merge before you write it.":"Mantıksız: henüz yazılmamış kod birleştirilmez."}'::jsonb,'Onay veriyor ve koşulu net söylüyor.',1,'draft');
