insert into public.exercises (id,target_id,type,skill,prompt,answer,accepted_answers,distractor_notes,explanation_tr,difficulty,status) values ('2c3d47bc-4222-5606-b6f7-23cea8df2f77','7dd75870-4837-51ab-9284-2f5fbcd9adc0','recall_typing','vocab','{"instruction_tr":"Boşluğa uygun İngilizce ifadei yaz.","sentence":"____? It appears after login.","sentence_tr":"Bu hatayı daha önce gören oldu mu? Girişten sonra çıkıyor.","hints_tr":["Bu hatayı daha önce gören oldu mu?","H________________________________ (33 karakter)"]}'::jsonb,'{"text":"Has anyone seen this error before"}'::jsonb,array['Has anyone seen this error before']::text[],'{}'::jsonb,'Doğru cevap: Has anyone seen this error before. Has anyone seen this error before? = Bu hatayı daha önce gören oldu mu?.',3,'draft');
