insert into public.exercises (id,target_id,type,skill,prompt,answer,accepted_answers,distractor_notes,explanation_tr,difficulty,status) values ('7a5c26f9-feff-5d2d-9d63-6fd6057ff188','f85403c0-3b3d-5399-bf66-f470cc930b4b','meaning_choice','reading','{"instruction_tr":"Bu cümlenin anlamı hangisi?","text":"Can you check if the API is up?","options":["Hata “izin reddedildi” diyor.","API''nin çalışıp çalışmadığını kontrol edebilir misin?","Görsellerin yavaş yüklendiğini fark ettim.","Yalnızca kullanıcı çevrimdışıyken oluyor."]}'::jsonb,'{"index":1}'::jsonb,array[]::text[],'{"Görsellerin yavaş yüklendiğini fark ettim.":"Bu, “I noticed that the images load slowly.” cümlesinin anlamı.","Hata “izin reddedildi” diyor.":"Bu, “The error says ''permission denied''.” cümlesinin anlamı.","Yalnızca kullanıcı çevrimdışıyken oluyor.":"Bu, “It only happens when the user is offline.” cümlesinin anlamı."}'::jsonb,'Can you check if the API is up? = API''nin çalışıp çalışmadığını kontrol edebilir misin?',2,'draft');
