insert into public.exercises (id,target_id,type,skill,prompt,answer,accepted_answers,distractor_notes,explanation_tr,difficulty,status) values ('1cdc6d79-2937-56c5-a714-a7d6fc0e7355','0b91a6e5-5195-579d-b951-a9997b904f8a','meaning_choice','reading','{"instruction_tr":"Bu cümlenin anlamı hangisi?","text":"I noticed that the images load slowly.","options":["Görsellerin yavaş yüklendiğini fark ettim.","Yalnızca kullanıcı çevrimdışıyken oluyor.","Hata “izin reddedildi” diyor.","Giriş yaptığımda 500 hatası alıyorum."]}'::jsonb,'{"index":0}'::jsonb,array[]::text[],'{"Hata “izin reddedildi” diyor.":"Bu, “The error says ''permission denied''.” cümlesinin anlamı.","Yalnızca kullanıcı çevrimdışıyken oluyor.":"Bu, “It only happens when the user is offline.” cümlesinin anlamı.","Giriş yaptığımda 500 hatası alıyorum.":"Bu, “I''m getting a 500 error when I log in.” cümlesinin anlamı."}'::jsonb,'I noticed that the images load slowly. = Görsellerin yavaş yüklendiğini fark ettim.',2,'draft');
