insert into public.exercises (id,target_id,type,skill,prompt,answer,accepted_answers,distractor_notes,explanation_tr,difficulty,status) values ('58fe0252-036a-57e5-8f2a-e3107b0cd4dd','362f7d42-7058-57c2-a233-cfe2d2cff6e7','meaning_choice','reading','{"instruction_tr":"Bu cümlenin anlamı hangisi?","text":"The error says ''permission denied''.","options":["Hata “izin reddedildi” diyor.","Yalnızca kullanıcı çevrimdışıyken oluyor.","Giriş yaptığımda 500 hatası alıyorum.","Son güncellemeden sonra hata vermeye başladı."]}'::jsonb,'{"index":0}'::jsonb,array[]::text[],'{"Yalnızca kullanıcı çevrimdışıyken oluyor.":"Bu, “It only happens when the user is offline.” cümlesinin anlamı.","Giriş yaptığımda 500 hatası alıyorum.":"Bu, “I''m getting a 500 error when I log in.” cümlesinin anlamı.","Son güncellemeden sonra hata vermeye başladı.":"Bu, “It started failing after the last update.” cümlesinin anlamı."}'::jsonb,'The error says ''permission denied''. = Hata “izin reddedildi” diyor.',1,'draft');
insert into public.exercises (id,target_id,type,skill,prompt,answer,accepted_answers,distractor_notes,explanation_tr,difficulty,status) values ('f0c2fc5e-d7ae-50b7-887a-40732c716f3c','3c66ff5d-3a6b-5b37-bb5c-f399695c2661','cloze_choice','vocab','{"instruction_tr":"Kalıbı tamamla.","sentence":"It only ____ when the user is offline.","sentence_tr":"Yalnızca kullanıcı çevrimdışıyken oluyor.","options":["happens","happen","happens to","happened"],"hints_tr":["Kalıp: It only happens when …"]}'::jsonb,'{"index":0,"text":"happens"}'::jsonb,array[]::text[],'{"happen":"Tekil özne -s ister: happens.","happened":"Cümlenin geri kalanı geniş zamanda; zamanlar uyuşmaz.","happens to":"Ardından fiil gelir; burada “when” var."}'::jsonb,'Kalıp: It only happens when … — Yalnızca kullanıcı çevrimdışıyken oluyor.',2,'draft');
