insert into public.exercises (id,target_id,type,skill,prompt,answer,accepted_answers,distractor_notes,explanation_tr,difficulty,status) values ('c2834795-e0d7-53f7-9376-55cc4abf1dff','3c66ff5d-3a6b-5b37-bb5c-f399695c2661','meaning_choice','reading','{"instruction_tr":"Bu cümlenin anlamı hangisi?","text":"It only happens when the user is offline.","options":["Son güncellemeden sonra hata vermeye başladı.","Yalnızca kullanıcı çevrimdışıyken oluyor.","Giriş yaptığımda 500 hatası alıyorum.","Önbelleği temizlemeyi denedin mi?"]}'::jsonb,'{"index":1}'::jsonb,array[]::text[],'{"Giriş yaptığımda 500 hatası alıyorum.":"Bu, “I''m getting a 500 error when I log in.” cümlesinin anlamı.","Son güncellemeden sonra hata vermeye başladı.":"Bu, “It started failing after the last update.” cümlesinin anlamı.","Önbelleği temizlemeyi denedin mi?":"Bu, “Have you tried clearing the cache?” cümlesinin anlamı."}'::jsonb,'It only happens when the user is offline. = Yalnızca kullanıcı çevrimdışıyken oluyor.',2,'draft');
insert into public.exercises (id,target_id,type,skill,prompt,answer,accepted_answers,distractor_notes,explanation_tr,difficulty,status) values ('7b5a19a0-cb6c-5081-8d01-d976d749826a','f280db72-ad91-5c7a-a568-581292437396','dialogue_choice','reading','{"instruction_tr":"Diyalogda en uygun yanıtı seç.","context":[{"speaker":"QA engineer","en":"Hey, did you see the crash report from this morning?"}],"options":["Yes. I reproduced it never.","Yes. It crashes when I upload a large file, and I can reproduce it every time.","Yes. It crushes when I upload a large file."],"scenario_id":"01d466c0-5cd1-5ef2-8f8a-2276d54e1f2a"}'::jsonb,'{"index":1}'::jsonb,array[]::text[],'{"Yes. I reproduced it never.":"“never” bu konumda kullanılmaz; doğrusu “I''ve never reproduced it.”","Yes. It crushes when I upload a large file.":"“crush” ezmek demektir; uygulama için “crash” kullanılır."}'::jsonb,'Ne olduğunu ve her seferinde yeniden oluşturulabildiğini net anlatıyor.',2,'draft');
insert into public.exercises (id,target_id,type,skill,prompt,answer,accepted_answers,distractor_notes,explanation_tr,difficulty,status) values ('8a8ae71f-c770-5034-b9c5-068d0b86fde6','f280db72-ad91-5c7a-a568-581292437396','dialogue_choice','reading','{"instruction_tr":"Diyalogda en uygun yanıtı seç.","context":[{"speaker":"QA engineer","en":"Hey, did you see the crash report from this morning?"},{"speaker":"QA engineer","en":"Great. Can you add the steps to reproduce to the ticket?"}],"options":["Sure, I''ll remove them from the ticket.","Sure, I''ll add them yesterday.","Sure, I''ll add them with the full stack trace."],"scenario_id":"01d466c0-5cd1-5ef2-8f8a-2276d54e1f2a"}'::jsonb,'{"index":2}'::jsonb,array[]::text[],'{"Sure, I''ll remove them from the ticket.":"İstenenin tersi: eklemek yerine kaldırmak.","Sure, I''ll add them yesterday.":"“will” ile “yesterday” birlikte kullanılmaz."}'::jsonb,'İsteği kabul edip faydalı bir ek bilgi sunuyor.',2,'draft');
insert into public.exercises (id,target_id,type,skill,prompt,answer,accepted_answers,distractor_notes,explanation_tr,difficulty,status) values ('9ad6483d-12be-5b2d-8d45-f94760558705','dd6348f0-0616-5661-830b-41055252e91b','dialogue_choice','reading','{"instruction_tr":"Diyalogda en uygun yanıtı seç.","context":[{"speaker":"Team lead","en":"What happened during the outage?"}],"options":["A bad config change caused timeouts, so we rolled back the release.","We rolled out the outage to all users.","The outage caused a bad config change."],"scenario_id":"b36504e8-cf8e-568e-89d9-fe5249ebfdc3"}'::jsonb,'{"index":0}'::jsonb,array[]::text[],'{"We rolled out the outage to all users.":"Kesinti “roll out” edilmez; anlam saçma.","The outage caused a bad config change.":"Neden-sonuç ters kurulmuş."}'::jsonb,'Nedeni ve alınan önlemi doğru sırayla anlatıyor.',3,'draft');
insert into public.exercises (id,target_id,type,skill,prompt,answer,accepted_answers,distractor_notes,explanation_tr,difficulty,status) values ('524e3e6e-a642-577b-b3ed-8ab8b02310ee','dd6348f0-0616-5661-830b-41055252e91b','dialogue_choice','reading','{"instruction_tr":"Diyalogda en uygun yanıtı seç.","context":[{"speaker":"Team lead","en":"What happened during the outage?"},{"speaker":"Team lead","en":"Do we know the root cause yet?"}],"options":["Not yet, so the root cause fixed it.","Not yet. For now, we have a workaround: we restart the service every hour.","Yes, the root cause is a workaround."],"scenario_id":"b36504e8-cf8e-568e-89d9-fe5249ebfdc3"}'::jsonb,'{"index":1}'::jsonb,array[]::text[],'{"Not yet, so the root cause fixed it.":"Anlamsız: bir neden bir şeyi düzeltmez.","Yes, the root cause is a workaround.":"Geçici çözüm bir neden değildir."}'::jsonb,'Durumu dürüstçe söylüyor ve geçici çözümü açıklıyor.',3,'draft');
insert into public.exercises (id,target_id,type,skill,prompt,answer,accepted_answers,distractor_notes,explanation_tr,difficulty,status) values ('b9e8515d-8d6b-5b5f-a82e-6d6f38ef938b','d9d18a04-8e67-515f-9a2a-a9d76e0ab7d2','meaning_choice','vocab','{"instruction_tr":"Bu kelime bu cümlede ne anlama geliyor?","text":"blocker","sentence":"My only blocker is the missing API key.","options":["güncel durum bilgisi","önceden haber, ön uyarı","tahmin (süre veya maliyet)","engel, işi durduran sorun"]}'::jsonb,'{"index":3}'::jsonb,array[]::text[],'{"güncel durum bilgisi":"Bu anlam “update” için geçerli.","tahmin (süre veya maliyet)":"Bu anlam “estimate” için geçerli.","önceden haber, ön uyarı":"Bu anlam “heads-up” için geçerli."}'::jsonb,'blocker = engel, işi durduran sorun.',1,'draft');
insert into public.exercises (id,target_id,type,skill,prompt,answer,accepted_answers,distractor_notes,explanation_tr,difficulty,status) values ('b7e1398d-19b2-5b6c-a2be-8a502ebf06b7','d9d18a04-8e67-515f-9a2a-a9d76e0ab7d2','cloze_choice','vocab','{"instruction_tr":"Boşluğa en uygun seçeneği seç.","sentence":"My only ____ is the missing API key.","sentence_tr":"Tek engelim eksik API anahtarı.","options":["feature","blocker","deadline","release"],"hints_tr":["Sık birlikte: no blockers, a major blocker","İlk harf: b"]}'::jsonb,'{"index":1,"text":"blocker"}'::jsonb,array[]::text[],'{"deadline":"Son tarih demektir; eksik bir anahtar son tarih olamaz.","feature":"Özellik demektir; cümlenin anlamına uymaz.","release":"Sürüm demektir; bir engel bildirmez."}'::jsonb,'“blocker” bu cümleye uyar: engel, işi durduran sorun.',1,'draft');
