insert into public.exercises (id,target_id,type,skill,prompt,answer,accepted_answers,distractor_notes,explanation_tr,difficulty,status) values ('6562d894-4052-5f3c-90f6-ba893c20f1e4','0006e22f-6efb-5de9-89ed-3f08260f8bf7','meaning_choice','reading','{"instruction_tr":"Bu cümlenin anlamı hangisi?","text":"Although the test was difficult, most students passed.","options":["Yöntem ucuz; ancak çok hassas değil.","Bazı türler hızla uyum sağlarken diğerleri yok oluyor.","Yağmura rağmen etkinlik başarılı geçti.","Sınav zor olmasına rağmen öğrencilerin çoğu geçti."]}'::jsonb,'{"index":3}'::jsonb,array[]::text[],'{"Yağmura rağmen etkinlik başarılı geçti.":"Bu, “Despite the rain, the event was a success.” cümlesinin anlamı.","Bazı türler hızla uyum sağlarken diğerleri yok oluyor.":"Bu, “Some species adapt quickly, whereas others die out.” cümlesinin anlamı.","Yöntem ucuz; ancak çok hassas değil.":"Bu, “The method is cheap; however, it is not very accurate.” cümlesinin anlamı."}'::jsonb,'Although the test was difficult, most students passed. = Sınav zor olmasına rağmen öğrencilerin çoğu geçti.',2,'draft');
