insert into public.exercises (id,target_id,type,skill,prompt,answer,accepted_answers,distractor_notes,explanation_tr,difficulty,status) values ('fac6e646-c822-513d-aaec-b38d15cd6243','0e2c327e-80cc-56e2-9752-58465a408009','meaning_choice','reading','{"instruction_tr":"Bu cümlenin anlamı hangisi?","text":"Unlike her brother, she enjoys math.","options":["Sınav zor olmasına rağmen öğrencilerin çoğu geçti.","Kuzey şehirleri soğuk. Buna karşılık güney şehirleri sıcak.","Ağabeyinin aksine matematiği seviyor.","Çalışmanı sık sık kaydet; aksi takdirde kaybedebilirsin."]}'::jsonb,'{"index":2}'::jsonb,array[]::text[],'{"Kuzey şehirleri soğuk. Buna karşılık güney şehirleri sıcak.":"Bu, “Northern cities are cold. In contrast, southern cities are warm.” cümlesinin anlamı.","Çalışmanı sık sık kaydet; aksi takdirde kaybedebilirsin.":"Bu, “Save your work often; otherwise, you may lose it.” cümlesinin anlamı.","Sınav zor olmasına rağmen öğrencilerin çoğu geçti.":"Bu, “Although the test was difficult, most students passed.” cümlesinin anlamı."}'::jsonb,'Unlike her brother, she enjoys math. = Ağabeyinin aksine matematiği seviyor.',2,'draft');
