insert into public.exercises (id,target_id,type,skill,prompt,answer,accepted_answers,distractor_notes,explanation_tr,difficulty,status) values ('a99c3ba8-2619-5a42-bab8-db0d37d64c20','a5ecea77-2f37-5f5b-8ee7-93c4e63dda47','meaning_choice','reading','{"instruction_tr":"Bu cümlenin anlamı hangisi?","text":"Northern cities are cold. In contrast, southern cities are warm.","options":["Yağmura rağmen etkinlik başarılı geçti.","Çalışmanı sık sık kaydet; aksi takdirde kaybedebilirsin.","Sınav zor olmasına rağmen öğrencilerin çoğu geçti.","Kuzey şehirleri soğuk. Buna karşılık güney şehirleri sıcak."]}'::jsonb,'{"index":3}'::jsonb,array[]::text[],'{"Çalışmanı sık sık kaydet; aksi takdirde kaybedebilirsin.":"Bu, “Save your work often; otherwise, you may lose it.” cümlesinin anlamı.","Sınav zor olmasına rağmen öğrencilerin çoğu geçti.":"Bu, “Although the test was difficult, most students passed.” cümlesinin anlamı.","Yağmura rağmen etkinlik başarılı geçti.":"Bu, “Despite the rain, the event was a success.” cümlesinin anlamı."}'::jsonb,'Northern cities are cold. In contrast, southern cities are warm. = Kuzey şehirleri soğuk. Buna karşılık güney şehirleri sıcak.',2,'draft');
