insert into public.exercises (id,target_id,type,skill,prompt,answer,accepted_answers,distractor_notes,explanation_tr,difficulty,status) values ('8cc451ff-8197-5c7a-a719-64e9d4428cf2','722a759f-6d82-51e0-b66f-993944ff660e','meaning_choice','reading','{"instruction_tr":"Bu cümlenin anlamı hangisi?","text":"Save your work often; otherwise, you may lose it.","options":["Bazı türler hızla uyum sağlarken diğerleri yok oluyor.","Yağmura rağmen etkinlik başarılı geçti.","Sınav zor olmasına rağmen öğrencilerin çoğu geçti.","Çalışmanı sık sık kaydet; aksi takdirde kaybedebilirsin."]}'::jsonb,'{"index":3}'::jsonb,array[]::text[],'{"Sınav zor olmasına rağmen öğrencilerin çoğu geçti.":"Bu, “Although the test was difficult, most students passed.” cümlesinin anlamı.","Yağmura rağmen etkinlik başarılı geçti.":"Bu, “Despite the rain, the event was a success.” cümlesinin anlamı.","Bazı türler hızla uyum sağlarken diğerleri yok oluyor.":"Bu, “Some species adapt quickly, whereas others die out.” cümlesinin anlamı."}'::jsonb,'Save your work often; otherwise, you may lose it. = Çalışmanı sık sık kaydet; aksi takdirde kaybedebilirsin.',2,'draft');
insert into public.exercises (id,target_id,type,skill,prompt,answer,accepted_answers,distractor_notes,explanation_tr,difficulty,status) values ('c030857e-1cd2-54ea-8de5-7cb85196f007','546660da-64cf-55e1-9800-dec52ed32589','dialogue_choice','reading','{"instruction_tr":"Diyalogda en uygun yanıtı seç.","context":[{"speaker":"Friend","en":"The sentence is: ''___ the high cost, many people buy electric cars.'' Which word fits?"}],"options":["''Although'', because the sentence shows contrast.","''Because of'', because the cost is the reason.","''Despite'', because a noun follows and the sentence shows contrast."],"scenario_id":"187b5a27-e2a5-5cb3-9a39-db48c2d9041e"}'::jsonb,'{"index":2}'::jsonb,array[]::text[],'{"''Although'', because the sentence shows contrast.":"Karşıtlık doğru ama “although” sonrası cümle gelir; burada isim var.","''Because of'', because the cost is the reason.":"Yüksek maliyet satın almanın nedeni değildir; anlam ters."}'::jsonb,'Ardından isim (the high cost) geliyor ve karşıtlık var.',3,'draft');
insert into public.exercises (id,target_id,type,skill,prompt,answer,accepted_answers,distractor_notes,explanation_tr,difficulty,status) values ('b1494726-f740-5998-a9a2-cafb8e220ca9','546660da-64cf-55e1-9800-dec52ed32589','dialogue_choice','reading','{"instruction_tr":"Diyalogda en uygun yanıtı seç.","context":[{"speaker":"Friend","en":"The sentence is: ''___ the high cost, many people buy electric cars.'' Which word fits?"},{"speaker":"Friend","en":"And what about ''___ the cost was high, many people bought them.''?"}],"options":["''Despite'', because it shows contrast.","''Therefore'', because it''s a result.","''Although'', because a full clause follows."],"scenario_id":"187b5a27-e2a5-5cb3-9a39-db48c2d9041e"}'::jsonb,'{"index":2}'::jsonb,array[]::text[],'{"''Despite'', because it shows contrast.":"Ardından tam cümle geldiği için “despite” kullanılamaz.","''Therefore'', because it''s a result.":"Anlam karşıtlıktır, sonuç değil."}'::jsonb,'Ardından tam bir cümle (özne + fiil) geliyor.',3,'draft');
insert into public.exercises (id,target_id,type,skill,prompt,answer,accepted_answers,distractor_notes,explanation_tr,difficulty,status) values ('6e69deae-9272-5a5e-a375-5e97d2f43861','5b0f2ac9-f377-5853-9e36-2b03192fb39e','dialogue_choice','reading','{"instruction_tr":"Diyalogda en uygun yanıtı seç.","context":[{"speaker":"Lecturer","en":"What are the main factors behind the rise in air pollution?"}],"options":["Traffic contributes with it, mainly because factories.","Traffic and factories contribute to it, but the increase is mainly due to traffic.","The main factor is that pollution causes traffic."],"scenario_id":"428e7fec-318d-5b98-85a7-6915c0c3136b"}'::jsonb,'{"index":1}'::jsonb,array[]::text[],'{"Traffic contributes with it, mainly because factories.":"Yapı yanlış: contribute to, because of.","The main factor is that pollution causes traffic.":"Neden-sonuç ters kurulmuş."}'::jsonb,'Etkenleri sayıyor ve hangisinin ağır bastığını söylüyor.',3,'draft');
insert into public.exercises (id,target_id,type,skill,prompt,answer,accepted_answers,distractor_notes,explanation_tr,difficulty,status) values ('6fe2db84-7d35-51d8-9833-340992a10de4','5b0f2ac9-f377-5853-9e36-2b03192fb39e','dialogue_choice','reading','{"instruction_tr":"Diyalogda en uygun yanıtı seç.","context":[{"speaker":"Lecturer","en":"What are the main factors behind the rise in air pollution?"},{"speaker":"Lecturer","en":"And what are the consequences for public health?"}],"options":["It has no consequences; therefore, it is dangerous.","It can lead to breathing problems, especially in children.","It can lead from breathing problems."],"scenario_id":"428e7fec-318d-5b98-85a7-6915c0c3136b"}'::jsonb,'{"index":1}'::jsonb,array[]::text[],'{"It has no consequences; therefore, it is dangerous.":"Kendiyle çelişen bir mantık.","It can lead from breathing problems.":"“lead from” denmez; doğrusu “lead to”."}'::jsonb,'Sonucu doğru kalıpla (lead to) anlatıyor.',3,'draft');
insert into public.exercises (id,target_id,type,skill,prompt,answer,accepted_answers,distractor_notes,explanation_tr,difficulty,status) values ('ce696f47-2f6f-55b9-9df5-dcd077778892','8a7b1308-47ec-5620-bca8-8b81d8d29626','meaning_choice','vocab','{"instruction_tr":"Bu kelime bu cümlede ne anlama geliyor?","text":"increase","sentence":"The number of tourists increased by 20% last year.","options":["dalgalanmak, inip çıkmak","(aynı) kalmak","artmak, artırmak","düşmek, azalmak"]}'::jsonb,'{"index":2}'::jsonb,array[]::text[],'{"düşmek, azalmak":"Bu anlam “decline” için geçerli.","dalgalanmak, inip çıkmak":"Bu anlam “fluctuate” için geçerli.","(aynı) kalmak":"Bu anlam “remain” için geçerli."}'::jsonb,'increase = artmak, artırmak.',1,'draft');
insert into public.exercises (id,target_id,type,skill,prompt,answer,accepted_answers,distractor_notes,explanation_tr,difficulty,status) values ('c241f143-2d07-505e-92fd-aee0022b2cf3','8a7b1308-47ec-5620-bca8-8b81d8d29626','cloze_choice','vocab','{"instruction_tr":"Boşluğa en uygun seçeneği seç.","sentence":"The number of tourists ____ by 20% last year.","sentence_tr":"Turist sayısı geçen yıl %20 arttı.","options":["inherited","creased","incised","increased"],"hints_tr":["Anlamı: artmak, artırmak","İlk harf: i"]}'::jsonb,'{"index":3,"text":"increased"}'::jsonb,array[]::text[],'{"incised":"Kesilmiş, oyulmuş demektir.","creased":"Kırışmış demektir.","inherited":"Miras kaldı demektir."}'::jsonb,'“increased” bu cümleye uyar: artmak, artırmak.',1,'draft');
