insert into public.exercises (id,target_id,type,skill,prompt,answer,accepted_answers,distractor_notes,explanation_tr,difficulty,status) values ('af26bac1-ce1d-5be9-a479-33185a1685f1','8a7b1308-47ec-5620-bca8-8b81d8d29626','listen_choice','listening','{"instruction_tr":"Cümleyi dinle. Anlamı hangisi?","audio_text":"The number of tourists increased by 20% last year.","options":["Turist sayısı geçen yıl %20 arttı.","Petrol fiyatları yıl boyunca dalgalandı.","Nüfus on yıl boyunca sabit kaldı.","Satışlar ikinci çeyrekte keskin biçimde düştü."]}'::jsonb,'{"index":0}'::jsonb,array[]::text[],'{"Satışlar ikinci çeyrekte keskin biçimde düştü.":"Bu, “decline” örneğinin çevirisi.","Petrol fiyatları yıl boyunca dalgalandı.":"Bu, “fluctuate” örneğinin çevirisi.","Nüfus on yıl boyunca sabit kaldı.":"Bu, “remain” örneğinin çevirisi."}'::jsonb,'“The number of tourists increased by 20% last year.” = Turist sayısı geçen yıl %20 arttı.',1,'draft');
