insert into public.exercises (id,target_id,type,skill,prompt,answer,accepted_answers,distractor_notes,explanation_tr,difficulty,status) values ('8fe1891d-471b-596a-b8bd-358d392460b1','ef0e5eba-c261-58cc-acfe-965908a8b2e4','listen_choice','listening','{"instruction_tr":"Cümleyi dinle. Anlamı hangisi?","audio_text":"Life expectancy has increased over the last decade.","options":["Resmî rakamlara göre iki milyon kişi yurt dışına taşındı.","İşsizlik oranı %8''e düştü.","Ortalama yaşam süresi son on yılda arttı.","Satışlar aralıkta zirveye ulaştı."]}'::jsonb,'{"index":2}'::jsonb,array[]::text[],'{"Resmî rakamlara göre iki milyon kişi yurt dışına taşındı.":"Bu, “figure” örneğinin çevirisi.","İşsizlik oranı %8''e düştü.":"Bu, “rate” örneğinin çevirisi.","Satışlar aralıkta zirveye ulaştı.":"Bu, “peak” örneğinin çevirisi."}'::jsonb,'“Life expectancy has increased over the last decade.” = Ortalama yaşam süresi son on yılda arttı.',1,'draft');
