insert into public.exercises (id,target_id,type,skill,prompt,answer,accepted_answers,distractor_notes,explanation_tr,difficulty,status) values ('448cb4e8-a6e3-52f6-a94a-c2d59b462719','c0465e2b-27c6-5691-830d-e135f91d7d7f','meaning_choice','reading','{"instruction_tr":"Bu cümlenin anlamı hangisi?","text":"The price increased from 10 to 15 dollars.","options":["Gıda fiyatlarında keskin bir artış oldu.","İşsizlik iki yüzde puan düştü.","Kullanıcı sayısı 2020''den beri arttı.","Fiyat 10 dolardan 15 dolara çıktı."]}'::jsonb,'{"index":3}'::jsonb,array[]::text[],'{"Kullanıcı sayısı 2020''den beri arttı.":"Bu, “The number of users has risen since 2020.” cümlesinin anlamı.","Gıda fiyatlarında keskin bir artış oldu.":"Bu, “There was a sharp rise in food prices.” cümlesinin anlamı.","İşsizlik iki yüzde puan düştü.":"Bu, “Unemployment fell by two percentage points.” cümlesinin anlamı."}'::jsonb,'The price increased from 10 to 15 dollars. = Fiyat 10 dolardan 15 dolara çıktı.',1,'draft');
