insert into public.exercises (id,target_id,type,skill,prompt,answer,accepted_answers,distractor_notes,explanation_tr,difficulty,status) values ('a3f0f880-2dee-5b4b-bab3-77aa23da2def','1c0db14a-8049-51be-af24-34ce62de5c85','meaning_choice','reading','{"instruction_tr":"Bu cümlenin anlamı hangisi?","text":"By the end of 2030, the population will reach 90 million.","options":["2030 sonuna kadar nüfus 90 milyona ulaşacak.","Gıda fiyatlarında keskin bir artış oldu.","Fiyat 10 dolardan 15 dolara çıktı.","Kullanıcı sayısı 2020''den beri arttı."]}'::jsonb,'{"index":0}'::jsonb,array[]::text[],'{"Fiyat 10 dolardan 15 dolara çıktı.":"Bu, “The price increased from 10 to 15 dollars.” cümlesinin anlamı.","Kullanıcı sayısı 2020''den beri arttı.":"Bu, “The number of users has risen since 2020.” cümlesinin anlamı.","Gıda fiyatlarında keskin bir artış oldu.":"Bu, “There was a sharp rise in food prices.” cümlesinin anlamı."}'::jsonb,'By the end of 2030, the population will reach 90 million. = 2030 sonuna kadar nüfus 90 milyona ulaşacak.',2,'draft');
