insert into public.exercises (id,target_id,type,skill,prompt,answer,accepted_answers,distractor_notes,explanation_tr,difficulty,status) values ('dce26e62-f0d6-54da-8514-0f87da3cd665','8a7b1308-47ec-5620-bca8-8b81d8d29626','dialogue_choice','reading','{"instruction_tr":"Diyalogda en uygun yanıtı seç.","context":[{"speaker":"Lecturer","en":"Can you describe the trend in sales?"},{"speaker":"Lecturer","en":"And what happened after 2020?"}],"options":["They have fallen in 2021 by slightly.","They fell slight and then leveled up.","They fell slightly and then leveled off."],"scenario_id":"fe40c5ab-c9ec-5af1-8c5e-f427e0fd11c3"}'::jsonb,'{"index":2}'::jsonb,array[]::text[],'{"They have fallen in 2021 by slightly.":"Belirli bir yılla present perfect kullanılmaz; “by slightly” yanlış.","They fell slight and then leveled up.":"Zarf gerekir (slightly); “level up” seviye atlamak demektir."}'::jsonb,'Hafif düşüşü ve sabitlenmeyi doğru anlatıyor.',3,'draft');
insert into public.exercises (id,target_id,type,skill,prompt,answer,accepted_answers,distractor_notes,explanation_tr,difficulty,status) values ('74915a96-3025-58e6-915c-55681b4d9bef','94696ac6-ac6e-5a6e-aa72-5f7813d67e59','dialogue_choice','reading','{"instruction_tr":"Diyalogda en uygun yanıtı seç.","context":[{"speaker":"Friend","en":"The report says women accounted for 60% of the participants. What does that mean?"}],"options":["It means that six out of ten participants were women.","It means that women counted the participants.","It means that exactly 60 women took part."],"scenario_id":"32d1bc34-393a-5e7d-8eab-6732a4e7908d"}'::jsonb,'{"index":0}'::jsonb,array[]::text[],'{"It means that women counted the participants.":"“account for” burada saymak anlamında değildir.","It means that exactly 60 women took part.":"Oran ile sayı karıştırılmış; toplam katılımcı sayısı verilmiyor."}'::jsonb,'“account for” burada “oluşturmak” demektir.',2,'draft');
insert into public.exercises (id,target_id,type,skill,prompt,answer,accepted_answers,distractor_notes,explanation_tr,difficulty,status) values ('57de94f6-a750-5de3-b53a-541c3b5ff4ae','94696ac6-ac6e-5a6e-aa72-5f7813d67e59','dialogue_choice','reading','{"instruction_tr":"Diyalogda en uygun yanıtı seç.","context":[{"speaker":"Friend","en":"The report says women accounted for 60% of the participants. What does that mean?"},{"speaker":"Friend","en":"Is that a large proportion?"}],"options":["Yes, it''s more than half.","No, it''s less than a third.","Yes, it''s more than double."],"scenario_id":"32d1bc34-393a-5e7d-8eab-6732a4e7908d"}'::jsonb,'{"index":0}'::jsonb,array[]::text[],'{"No, it''s less than a third.":"%60 üçte birden fazladır.","Yes, it''s more than double.":"%60 yarıdan fazladır; iki kat değildir."}'::jsonb,'%60 yarıdan fazladır.',2,'draft');
insert into public.exercises (id,target_id,type,skill,prompt,answer,accepted_answers,distractor_notes,explanation_tr,difficulty,status) values ('50e10f23-305d-5c01-9f1b-d7071270ff5a','4d056db7-9cbe-579f-a583-3e4b7ea23510','meaning_choice','vocab','{"instruction_tr":"Bu kelime bu cümlede ne anlama geliyor?","text":"hypothesis","sentence":"The hypothesis was supported by the data.","options":["kanıt","bulgu(lar)","katılımcı","hipotez, varsayım"]}'::jsonb,'{"index":3}'::jsonb,array[]::text[],'{"bulgu(lar)":"Bu anlam “finding” için geçerli.","katılımcı":"Bu anlam “participant” için geçerli.","kanıt":"Bu anlam “evidence” için geçerli."}'::jsonb,'hypothesis = hipotez, varsayım.',2,'draft');
insert into public.exercises (id,target_id,type,skill,prompt,answer,accepted_answers,distractor_notes,explanation_tr,difficulty,status) values ('0ca51c31-993f-5e92-b4d1-e9b516656744','4d056db7-9cbe-579f-a583-3e4b7ea23510','cloze_choice','vocab','{"instruction_tr":"Boşluğa en uygun seçeneği seç.","sentence":"The ____ was supported by the data.","sentence_tr":"Hipotez veriler tarafından desteklendi.","options":["hypocrisy","hypothesis","hyphen","hypnosis"],"hints_tr":["Anlamı: hipotez, varsayım","İlk harf: h"]}'::jsonb,'{"index":1,"text":"hypothesis"}'::jsonb,array[]::text[],'{"hypocrisy":"İkiyüzlülük demektir.","hyphen":"Kısa çizgi demektir.","hypnosis":"Hipnoz demektir."}'::jsonb,'“hypothesis” bu cümleye uyar: hipotez, varsayım.',2,'draft');
insert into public.exercises (id,target_id,type,skill,prompt,answer,accepted_answers,distractor_notes,explanation_tr,difficulty,status) values ('93648304-fca7-5e32-bbfc-e7dae9bb8e48','4d056db7-9cbe-579f-a583-3e4b7ea23510','recall_typing','vocab','{"instruction_tr":"Boşluğa uygun İngilizce kelimei yaz.","sentence":"The ____ was supported by the data.","sentence_tr":"Hipotez veriler tarafından desteklendi.","hints_tr":["hipotez, varsayım","h_________ (10 karakter)"]}'::jsonb,'{"text":"hypothesis"}'::jsonb,array['hypothesis']::text[],'{}'::jsonb,'Doğru cevap: hypothesis. hypothesis = hipotez, varsayım.',3,'draft');
insert into public.exercises (id,target_id,type,skill,prompt,answer,accepted_answers,distractor_notes,explanation_tr,difficulty,status) values ('85649633-cff6-5b3c-94c7-a791ede6002d','4d056db7-9cbe-579f-a583-3e4b7ea23510','listen_choice','listening','{"instruction_tr":"Cümleyi dinle. Anlamı hangisi?","audio_text":"The hypothesis was supported by the data.","options":["Bulgular uykunun hafızayı etkilediğini düşündürüyor.","Hipotez veriler tarafından desteklendi.","Her katılımcı kısa bir anket doldurdu.","İlacın işe yaradığına dair çok az kanıt var."]}'::jsonb,'{"index":1}'::jsonb,array[]::text[],'{"Bulgular uykunun hafızayı etkilediğini düşündürüyor.":"Bu, “finding” örneğinin çevirisi.","Her katılımcı kısa bir anket doldurdu.":"Bu, “participant” örneğinin çevirisi.","İlacın işe yaradığına dair çok az kanıt var.":"Bu, “evidence” örneğinin çevirisi."}'::jsonb,'“The hypothesis was supported by the data.” = Hipotez veriler tarafından desteklendi.',2,'draft');
