insert into public.exercises (id,target_id,type,skill,prompt,answer,accepted_answers,distractor_notes,explanation_tr,difficulty,status) values ('72f9b670-0a55-5478-a316-fbadd56db0ab','4a71443f-7aec-54e4-8fac-e8634d80e98e','cloze_choice','vocab','{"instruction_tr":"Boşluğa en uygun seçeneği seç.","sentence":"The ____ suggest that sleep affects memory.","sentence_tr":"Bulgular uykunun hafızayı etkilediğini düşündürüyor.","options":["feelings","findings","fittings","fundings"],"hints_tr":["Sık birlikte: key findings, research findings","İlk harf: f"]}'::jsonb,'{"index":1,"text":"findings"}'::jsonb,array[]::text[],'{"fittings":"Bağlantı parçaları demektir.","feelings":"Duygular demektir.","fundings":"“funding” fon demektir ve çoğul kullanılmaz."}'::jsonb,'“findings” bu cümleye uyar: bulgu(lar).',2,'draft');
