insert into public.exercises (id,target_id,type,skill,prompt,answer,accepted_answers,distractor_notes,explanation_tr,difficulty,status) values ('1201659f-01c3-5808-ba0e-833afd7e2a01','f12b2874-89a3-5097-912e-78164c9d60c7','listen_choice','listening','{"instruction_tr":"Cümleyi dinle. Anlamı hangisi?","audio_text":"The study was conducted in three countries.","options":["Çalışma üç ülkede yürütüldü.","Sonuçları istatistik yazılımı kullanarak analiz ettik.","Sonuçlar beslenme ile sağlık arasında güçlü bir bağlantıya işaret ediyor.","Bazı bilim insanları etkinin geçici olduğunu iddia ediyor."]}'::jsonb,'{"index":0}'::jsonb,array[]::text[],'{"Sonuçlar beslenme ile sağlık arasında güçlü bir bağlantıya işaret ediyor.":"Bu, “indicate” örneğinin çevirisi.","Bazı bilim insanları etkinin geçici olduğunu iddia ediyor.":"Bu, “claim” örneğinin çevirisi.","Sonuçları istatistik yazılımı kullanarak analiz ettik.":"Bu, “analyze” örneğinin çevirisi."}'::jsonb,'“The study was conducted in three countries.” = Çalışma üç ülkede yürütüldü.',3,'draft');
