insert into public.exercises (id,target_id,type,skill,prompt,answer,accepted_answers,distractor_notes,explanation_tr,difficulty,status) values ('59893188-a0ab-5f72-8722-c51a4598d991','895ad263-5ece-55a2-b2df-31abbc741792','tr_to_en','writing','{"instruction_tr":"İngilizcesini yaz.","text_tr":"Araştırmacılar tedavinin ağrıyı azalttığını buldu.","hints_tr":["Kalıp: Researchers found that …","Başlangıç: Researchers found …"]}'::jsonb,'{"text":"Researchers found that the treatment reduced pain."}'::jsonb,array['Researchers found that the treatment reduced pain.']::text[],'{}'::jsonb,'Örnek cevap: Researchers found that the treatment reduced pain.',2,'draft');
insert into public.exercises (id,target_id,type,skill,prompt,answer,accepted_answers,distractor_notes,explanation_tr,difficulty,status) values ('67ca27b8-b541-5b8b-bed8-f78ea985547d','895ad263-5ece-55a2-b2df-31abbc741792','meaning_choice','reading','{"instruction_tr":"Bu cümlenin anlamı hangisi?","text":"Researchers found that the treatment reduced pain.","options":["Araştırmacılar tedavinin ağrıyı azalttığını buldu.","Eğilimin devam etmesi muhtemeldir.","Sonuçlar egzersizin hafızayı geliştirdiğini düşündürüyor.","Bu, küçük örneklem büyüklüğünden kaynaklanıyor olabilir."]}'::jsonb,'{"index":0}'::jsonb,array[]::text[],'{"Eğilimin devam etmesi muhtemeldir.":"Bu, “It is likely that the trend will continue.” cümlesinin anlamı.","Bu, küçük örneklem büyüklüğünden kaynaklanıyor olabilir.":"Bu, “This may be due to the small sample size.” cümlesinin anlamı.","Sonuçlar egzersizin hafızayı geliştirdiğini düşündürüyor.":"Bu, “The results suggest that exercise improves memory.” cümlesinin anlamı."}'::jsonb,'Researchers found that the treatment reduced pain. = Araştırmacılar tedavinin ağrıyı azalttığını buldu.',1,'draft');
insert into public.exercises (id,target_id,type,skill,prompt,answer,accepted_answers,distractor_notes,explanation_tr,difficulty,status) values ('f6bcdd48-b5e5-5beb-862d-36a4e96c3a13','400c9bda-1587-53bc-8925-fae727102eb8','cloze_choice','vocab','{"instruction_tr":"Kalıbı tamamla.","sentence":"It is ____ that the trend will continue.","sentence_tr":"Eğilimin devam etmesi muhtemeldir.","options":["likely to","likeness","liking","likely"],"hints_tr":["Kalıp: It is likely that …"]}'::jsonb,'{"index":3,"text":"likely"}'::jsonb,array[]::text[],'{"likely to":"Ardından “that” cümlesi geldiği için “to” kullanılmaz.","likeness":"Benzerlik demektir.","liking":"Hoşlanma demektir."}'::jsonb,'Kalıp: It is likely that … — Eğilimin devam etmesi muhtemeldir.',2,'draft');
insert into public.exercises (id,target_id,type,skill,prompt,answer,accepted_answers,distractor_notes,explanation_tr,difficulty,status) values ('eb90b2c5-7107-519e-9c69-794802d00287','400c9bda-1587-53bc-8925-fae727102eb8','tr_to_en','writing','{"instruction_tr":"İngilizcesini yaz.","text_tr":"Eğilimin devam etmesi muhtemeldir.","hints_tr":["Kalıp: It is likely that …","Başlangıç: It is …"]}'::jsonb,'{"text":"It is likely that the trend will continue."}'::jsonb,array['It is likely that the trend will continue.']::text[],'{}'::jsonb,'Örnek cevap: It is likely that the trend will continue.',3,'draft');
insert into public.exercises (id,target_id,type,skill,prompt,answer,accepted_answers,distractor_notes,explanation_tr,difficulty,status) values ('ba8c9d03-7569-5149-9c44-15ff748751d9','400c9bda-1587-53bc-8925-fae727102eb8','meaning_choice','reading','{"instruction_tr":"Bu cümlenin anlamı hangisi?","text":"It is likely that the trend will continue.","options":["Eğilimin devam etmesi muhtemeldir.","İki dilli çocukların daha hızlı öğrendiği gösterilmiştir.","Bu, küçük örneklem büyüklüğünden kaynaklanıyor olabilir.","Sonuçlar egzersizin hafızayı geliştirdiğini düşündürüyor."]}'::jsonb,'{"index":0}'::jsonb,array[]::text[],'{"Bu, küçük örneklem büyüklüğünden kaynaklanıyor olabilir.":"Bu, “This may be due to the small sample size.” cümlesinin anlamı.","Sonuçlar egzersizin hafızayı geliştirdiğini düşündürüyor.":"Bu, “The results suggest that exercise improves memory.” cümlesinin anlamı.","İki dilli çocukların daha hızlı öğrendiği gösterilmiştir.":"Bu, “It has been shown that bilingual children learn faster.” cümlesinin anlamı."}'::jsonb,'It is likely that the trend will continue. = Eğilimin devam etmesi muhtemeldir.',2,'draft');
insert into public.exercises (id,target_id,type,skill,prompt,answer,accepted_answers,distractor_notes,explanation_tr,difficulty,status) values ('859f90bb-d5fe-579a-8e1c-f15cf0967af0','a874e378-882e-5a57-9860-1a40125b961e','cloze_choice','vocab','{"instruction_tr":"Kalıbı tamamla.","sentence":"This may be ____ the small sample size.","sentence_tr":"Bu, küçük örneklem büyüklüğünden kaynaklanıyor olabilir.","options":["do to","due for","due of","due to"],"hints_tr":["Kalıp: This may be due to …"]}'::jsonb,'{"index":3,"text":"due to"}'::jsonb,array[]::text[],'{"due of":"Edat yanlış: due to.","do to":"“do” bir fiildir; doğrusu “due to”.","due for":"“due for” bir şeyin vakti gelmiş demektir."}'::jsonb,'Kalıp: This may be due to … — Bu, küçük örneklem büyüklüğünden kaynaklanıyor olabilir.',2,'draft');
insert into public.exercises (id,target_id,type,skill,prompt,answer,accepted_answers,distractor_notes,explanation_tr,difficulty,status) values ('5bb6f42b-3c57-50d9-a474-d11a52f94ee8','a874e378-882e-5a57-9860-1a40125b961e','tr_to_en','writing','{"instruction_tr":"İngilizcesini yaz.","text_tr":"Bu, küçük örneklem büyüklüğünden kaynaklanıyor olabilir.","hints_tr":["Kalıp: This may be due to …","Başlangıç: This may …"]}'::jsonb,'{"text":"This may be due to the small sample size."}'::jsonb,array['This may be due to the small sample size.']::text[],'{}'::jsonb,'Örnek cevap: This may be due to the small sample size.',3,'draft');
insert into public.exercises (id,target_id,type,skill,prompt,answer,accepted_answers,distractor_notes,explanation_tr,difficulty,status) values ('95861327-b566-5551-9ae0-8667dae37326','a874e378-882e-5a57-9860-1a40125b961e','meaning_choice','reading','{"instruction_tr":"Bu cümlenin anlamı hangisi?","text":"This may be due to the small sample size.","options":["İki dilli çocukların daha hızlı öğrendiği gösterilmiştir.","Sonuçlar egzersizin hafızayı geliştirdiğini düşündürüyor.","Bu, 500 okulu inceleyen bir çalışma.","Bu, küçük örneklem büyüklüğünden kaynaklanıyor olabilir."]}'::jsonb,'{"index":3}'::jsonb,array[]::text[],'{"Sonuçlar egzersizin hafızayı geliştirdiğini düşündürüyor.":"Bu, “The results suggest that exercise improves memory.” cümlesinin anlamı.","İki dilli çocukların daha hızlı öğrendiği gösterilmiştir.":"Bu, “It has been shown that bilingual children learn faster.” cümlesinin anlamı.","Bu, 500 okulu inceleyen bir çalışma.":"Bu, “This is a study which examined 500 schools.” cümlesinin anlamı."}'::jsonb,'This may be due to the small sample size. = Bu, küçük örneklem büyüklüğünden kaynaklanıyor olabilir.',2,'draft');
insert into public.exercises (id,target_id,type,skill,prompt,answer,accepted_answers,distractor_notes,explanation_tr,difficulty,status) values ('4c9edeae-954a-565b-b54f-f55d5014e6e3','4a71443f-7aec-54e4-8fac-e8634d80e98e','dialogue_choice','reading','{"instruction_tr":"Diyalogda en uygun yanıtı seç.","context":[{"speaker":"Classmate","en":"The abstract says: ''The findings suggest that exercise may improve memory in older adults.'' What does that mean?"}],"options":["The study found that older adults don''t like exercise.","The study proved that exercise always improves memory.","The study found a possible positive effect of exercise on memory, but it isn''t certain."],"scenario_id":"2395615d-48ce-59f6-bacb-a46363b07e11"}'::jsonb,'{"index":2}'::jsonb,array[]::text[],'{"The study found that older adults don''t like exercise.":"Cümlede böyle bir bilgi yok.","The study proved that exercise always improves memory.":"“suggest” ve “may” kesin kanıt anlamına gelmez; “always” da cümlede yok."}'::jsonb,'“suggest” ve “may” temkinli dildir; kesinlik bildirmez.',3,'draft');
insert into public.exercises (id,target_id,type,skill,prompt,answer,accepted_answers,distractor_notes,explanation_tr,difficulty,status) values ('596c81f6-fa62-5119-80bf-479999c95c98','4a71443f-7aec-54e4-8fac-e8634d80e98e','dialogue_choice','reading','{"instruction_tr":"Diyalogda en uygun yanıtı seç.","context":[{"speaker":"Classmate","en":"The abstract says: ''The findings suggest that exercise may improve memory in older adults.'' What does that mean?"},{"speaker":"Classmate","en":"So was their hypothesis supported?"}],"options":["Yes, so no further research is needed.","Partly. The results point in that direction, but they are not conclusive.","No, because the hypothesis was a participant."],"scenario_id":"2395615d-48ce-59f6-bacb-a46363b07e11"}'::jsonb,'{"index":1}'::jsonb,array[]::text[],'{"Yes, so no further research is needed.":"Temkinli bulgular kesin sonuç sayılmaz; çıkarım yanlış.","No, because the hypothesis was a participant.":"Hipotez bir katılımcı değildir; anlamsız."}'::jsonb,'Temkinli bulguyu doğru yorumluyor.',3,'draft');
insert into public.exercises (id,target_id,type,skill,prompt,answer,accepted_answers,distractor_notes,explanation_tr,difficulty,status) values ('a0f01f2b-bd12-5db8-bea8-6cbda55a8d61','83cc93e4-da20-54fa-8a46-a4fec28d34a7','dialogue_choice','reading','{"instruction_tr":"Diyalogda en uygun yanıtı seç.","context":[{"speaker":"Professor","en":"What is one limitation of this study?"}],"options":["The sample was very small, so the results are more reliable.","The sample was very small, so the results may not be reliable.","The limitation is that the study was conducted."],"scenario_id":"9a3142fd-5e83-5f4b-b49b-83f05ab9110d"}'::jsonb,'{"index":1}'::jsonb,array[]::text[],'{"The sample was very small, so the results are more reliable.":"Küçük örneklem güvenilirliği artırmaz; mantık hatası.","The limitation is that the study was conducted.":"Anlamsız bir gerekçe."}'::jsonb,'Kısıtlılığı ve sonucunu mantıklı biçimde bağlıyor.',3,'draft');
insert into public.exercises (id,target_id,type,skill,prompt,answer,accepted_answers,distractor_notes,explanation_tr,difficulty,status) values ('fc3bed94-864a-5e79-ae44-fca216be3429','83cc93e4-da20-54fa-8a46-a4fec28d34a7','dialogue_choice','reading','{"instruction_tr":"Diyalogda en uygun yanıtı seç.","context":[{"speaker":"Professor","en":"What is one limitation of this study?"},{"speaker":"Professor","en":"Good. Why do you think the two groups gave different answers?"}],"options":["This may be due to cultural differences between the groups.","This may be do to cultural differences.","This may be due of cultural differences."],"scenario_id":"9a3142fd-5e83-5f4b-b49b-83f05ab9110d"}'::jsonb,'{"index":0}'::jsonb,array[]::text[],'{"This may be do to cultural differences.":"“do” bir fiildir; doğrusu “due to”.","This may be due of cultural differences.":"Edat yanlış: due to."}'::jsonb,'Olası nedeni temkinli bir dille söylüyor.',3,'draft');
insert into public.scenarios (id,pack_id,title_tr,situation_tr,turns,target_ids,mode,difficulty,status) values ('4ccdde2c-4345-55a0-a739-3b81887070ae','6fbbf6ec-47c4-5a61-ae2a-085acb973117','Aşırı ısınma toplantısı','Bir makine sürekli aşırı ısınıp duruyor. Ekip toplantısında sorunu ve çözümü anlatıyorsun.','[{"speaker":"Manager","en":"Why does the machine keep stopping?","tr":"Makine neden sürekli duruyor?"},{"choose":[{"en":"It overheats after about an hour. The problem is that the fan is too small.","correct":true,"why_tr":"Belirtiyi ve nedeni net anlatıyor."},{"en":"It is overheat because the fan small.","correct":false,"why_tr":"Fiil yapısı bozuk ve ikinci cümlede “is” eksik."},{"en":"It overhears after about an hour.","correct":false,"why_tr":"“overhear” kulak misafiri olmak demektir."}],"q":"En uygun yanıt hangisi?"},{"speaker":"Manager","en":"What do you suggest?","tr":"Ne öneriyorsun?"},{"choose":[{"en":"I suggest you to install a larger fan.","correct":false,"why_tr":"“suggest you to” yanlış; “I suggest that we install …” denir."},{"en":"If we install a larger fan, the temperature will drop. It''s a cheap solution.","correct":true,"why_tr":"First conditional doğru kullanılmış ve gerekçe veriyor."},{"en":"If we will install a larger fan, the temperature drops.","correct":false,"why_tr":"If''li kısımda “will” kullanılmaz; sonuç kısmında gerekir."}],"q":"En uygun yanıt hangisi?"}]'::jsonb,array['bd452d1c-f72a-5a10-aba9-dcb781346581','6877aabb-c98a-547c-b67d-a552a9ba7300','0c94d6d1-8459-5bc8-ada3-ba0c8b61c22a']::uuid[],'choice',2,'draft');
insert into public.scenarios (id,pack_id,title_tr,situation_tr,turns,target_ids,mode,difficulty,status) values ('b01af5ca-9ef0-5201-8c89-7ffabce2585b','6fbbf6ec-47c4-5a61-ae2a-085acb973117','Geçici ve kalıcı çözüm','Üretim hattında bir parça arızalandı. Yeni parça gelene kadar ne yapacağınızı konuşuyorsunuz.','[{"speaker":"Colleague","en":"The new part won''t arrive until Friday. What can we do now?","tr":"Yeni parça cumaya kadar gelmeyecek. Şimdi ne yapabiliriz?"},{"choose":[{"en":"As a temporary fix, we could use the spare part from line 2.","correct":true,"why_tr":"Uygulanabilir geçici bir çözüm öneriyor."},{"en":"As a permanent fix, we can wait until Friday.","correct":false,"why_tr":"Beklemek kalıcı bir çözüm değildir; anlam çelişkili."},{"en":"As a temporal fix, we could use the spare part from line 2.","correct":false,"why_tr":"“temporal” zamanla ilgili demektir; “geçici” için “temporary” kullanılır."}],"q":"En uygun yanıt hangisi?"},{"speaker":"Colleague","en":"Good idea, but line 2 will have some downtime.","tr":"İyi fikir ama 2. hatta biraz duruş olacak."},{"choose":[{"en":"True, it''s a take-off.","correct":false,"why_tr":"“take-off” kalkış demektir."},{"en":"True, it''s a trade-off. Two hours of downtime is better than three days.","correct":true,"why_tr":"Ödünleşimi görüp gerekçeyle karar veriyor."},{"en":"True, so line 2 has no downtime.","correct":false,"why_tr":"Az önce söyleneni inkâr ediyor; çelişkili."}],"q":"En uygun yanıt hangisi?"}]'::jsonb,array['43bfccda-4491-56cb-827f-e769d98cef4a','0f930437-1ce5-5c0e-b449-d3f922be758c','c876530d-4950-5c77-8df6-ca2e0792b84c']::uuid[],'choice',3,'draft');
insert into public.scenarios (id,pack_id,title_tr,situation_tr,turns,target_ids,mode,difficulty,status) values ('f195b6de-af95-580f-aa74-2d350cf8bf5e','c016cb37-6858-58cd-ae01-49689b107921','Tedarikçiyle teknik görüşme','Bir tedarikçiyle yeni bir pompanın teknik özelliklerini konuşuyorsun.','[{"speaker":"Supplier","en":"This model can pump up to 40 liters per minute.","tr":"Bu model dakikada 40 litreye kadar pompalayabilir."},{"choose":[{"en":"That''s good. What''s the total wait of the unit?","correct":false,"why_tr":"“wait” beklemek demektir."},{"en":"That''s good. How much weights the unit?","correct":false,"why_tr":"Soru yapısı bozuk; doğrusu “How much does it weigh?”"},{"en":"That''s good. What''s the total weight of the unit?","correct":true,"why_tr":"Doğru ve ilgili bir soru soruyor."}],"q":"En uygun yanıt hangisi?"},{"speaker":"Supplier","en":"It weighs about 18 kg, and the tank capacity is 50 liters.","tr":"Yaklaşık 18 kg ağırlığında ve depo kapasitesi 50 litre."},{"choose":[{"en":"Great. Could you sent me the datasheet?","correct":false,"why_tr":"“could” sonrası fiil yalın olur: send."},{"en":"Great. Could you send me the datasheet with all the speculations?","correct":false,"why_tr":"“speculations” spekülasyon demektir."},{"en":"Great. Could you send me the datasheet with all the specifications?","correct":true,"why_tr":"Kibar ve somut bir istek."}],"q":"En uygun yanıt hangisi?"}]'::jsonb,array['12dbb87c-76e8-5812-a127-a4be97017eb6','d1711756-5239-586c-a974-19406657411b','e04967ef-0be8-5ae7-b43f-12351446c933']::uuid[],'choice',2,'draft');
insert into public.scenarios (id,pack_id,title_tr,situation_tr,turns,target_ids,mode,difficulty,status) values ('81f5e814-fd79-5170-a9c6-a4bb60566203','c016cb37-6858-58cd-ae01-49689b107921','Malzeme seçimi','Ekip toplantısında bir drone gövdesi için malzeme seçiyorsunuz.','[{"speaker":"Engineer","en":"Should we use steel or aluminum for the frame?","tr":"Gövde için çelik mi alüminyum mu kullanalım?"},{"choose":[{"en":"Steel, because it''s lighter than aluminum.","correct":false,"why_tr":"Teknik olarak yanlış: çelik alüminyumdan ağırdır."},{"en":"Aluminum, because it is more heavier than steel.","correct":false,"why_tr":"“more heavier” yanlış; ayrıca alüminyum çelikten hafiftir."},{"en":"Aluminum. Compared to steel, it''s much lighter, and we need a lightweight frame.","correct":true,"why_tr":"Seçimi doğru bir gerekçeyle yapıyor."}],"q":"En uygun yanıt hangisi?"},{"speaker":"Engineer","en":"But is it durable enough in wet conditions?","tr":"Peki ıslak koşullarda yeterince dayanıklı mı?"},{"choose":[{"en":"Yes, if we add a protective coating.","correct":true,"why_tr":"Koşulu belirterek yanıt veriyor."},{"en":"Yes, it''s during in wet conditions.","correct":false,"why_tr":"“during” bir edattır."},{"en":"Yes, it is enough durable.","correct":false,"why_tr":"Kelime sırası yanlış: durable enough."}],"q":"En uygun yanıt hangisi?"}]'::jsonb,array['f6d2dbda-03bc-5ea5-bdf8-aefc05a08842','097fac93-06b0-55ab-b550-2027b4c25fcc','22b27d26-4cf8-5f33-8519-f5a260a3fca9']::uuid[],'choice',2,'draft');
insert into public.scenarios (id,pack_id,title_tr,situation_tr,turns,target_ids,mode,difficulty,status) values ('ad597b64-bc91-5e6a-ac47-51367354f2fa','233b0925-1efe-5baa-9090-54d6f8aef7d6','Test sonucunu bildirme','Test yöneticisi, dünkü titreşim testinin nasıl geçtiğini soruyor.','[{"speaker":"Test manager","en":"How did the vibration test go yesterday?","tr":"Dünkü titreşim testi nasıl geçti?"},{"choose":[{"en":"Eight units past, but two felt after 200 cycles.","correct":false,"why_tr":"“past” ve “felt” yanlış kelimeler: passed, failed."},{"en":"Eight units are passing yesterday.","correct":false,"why_tr":"“yesterday” ile geçmiş zaman gerekir."},{"en":"Eight units passed, but two failed after 200 cycles.","correct":true,"why_tr":"Sonucu sayılarla ve net biçimde veriyor."}],"q":"En uygun yanıt hangisi?"},{"speaker":"Test manager","en":"Do we know why the two units failed?","tr":"İki ünitenin neden başarısız olduğunu biliyor muyuz?"},{"choose":[{"en":"Yes, because they passed.","correct":false,"why_tr":"Anlamsız: geçtikleri için başarısız olmadılar."},{"en":"We found a small crack near the weld. We need to repeat the test with new samples.","correct":true,"why_tr":"Nedeni ve sonraki adımı açıklıyor."},{"en":"We found a small crab near the weld.","correct":false,"why_tr":"“crab” yengeç demektir."}],"q":"En uygun yanıt hangisi?"}]'::jsonb,array['a6858448-fbfc-5e83-a8af-7ce4d0a864a9','062925df-3b46-54be-8c2b-607fbf414f63','d2ea5cdd-0eb6-52c6-ad12-575f51457852']::uuid[],'choice',2,'draft');
insert into public.scenarios (id,pack_id,title_tr,situation_tr,turns,target_ids,mode,difficulty,status) values ('12d5757e-7898-5966-a985-2afd20a2f227','233b0925-1efe-5baa-9090-54d6f8aef7d6','Sensör sapması','Laboratuvarda bir meslektaşın bir sensörün değerlerinin tuhaf olduğunu söylüyor.','[{"speaker":"Colleague","en":"The readings from sensor B look strange today.","tr":"B sensöründen gelen değerler bugün tuhaf görünüyor."},{"choose":[{"en":"Yes, we celebrate it every month.","correct":false,"why_tr":"“celebrate” kutlamak demektir."},{"en":"Yes, there''s a deviation of about 2%. When was it last calibrated?","correct":true,"why_tr":"Gözlemi sayıyla veriyor ve doğru soruyu soruyor."},{"en":"Yes, there''s a devotion of about 2%.","correct":false,"why_tr":"“devotion” bağlılık demektir."}],"q":"En uygun yanıt hangisi?"},{"speaker":"Colleague","en":"Last month. I''ll calibrate it again and repeat the measurement.","tr":"Geçen ay. Tekrar kalibre edip ölçümü tekrarlayacağım."},{"choose":[{"en":"Good idea, but don''t repeat nothing.","correct":false,"why_tr":"Çift olumsuzluk ve anlam bozuk."},{"en":"Good idea. Then we can check if the results are reputable.","correct":false,"why_tr":"“reputable” saygın demektir."},{"en":"Good idea. Then we can check if the results are repeatable.","correct":true,"why_tr":"Mantıklı bir sonraki adımı söylüyor."}],"q":"En uygun yanıt hangisi?"}]'::jsonb,array['4a53e8a5-376b-5f6b-a0a2-5ef8ae419739','643a2090-eb26-5f9d-a24b-6a8144033ea4','56a6bfb7-69aa-5ed1-8230-274315630873']::uuid[],'choice',3,'draft');
insert into public.scenarios (id,pack_id,title_tr,situation_tr,turns,target_ids,mode,difficulty,status) values ('c14cf23a-7068-591e-8333-463f9c43cdd8','1ec86e14-8694-5f09-89f1-2ad9ef7f19f5','Hafta sonu planı','Bir arkadaşın seni cumartesi müzedeki yeni sergiye çağırıyor.','[{"speaker":"Zeynep","en":"Are you free on Saturday? There''s a new exhibition at the museum.","tr":"Cumartesi müsait misin? Müzede yeni bir sergi var."},{"choose":[{"en":"Yes, I''m free in the afternoon. How about meeting at two?","correct":true,"why_tr":"Müsaitliğini söyleyip somut bir saat öneriyor."},{"en":"Yes, I''m going to free on Saturday.","correct":false,"why_tr":"“going to” sonrası fiil gerekir; doğrusu “I''m free”."},{"en":"Yes, I''m fee in the afternoon.","correct":false,"why_tr":"“fee” ücret demektir."}],"q":"En uygun yanıt hangisi?"},{"speaker":"Zeynep","en":"Two o''clock works for me. Let''s meet at the main entrance.","tr":"Saat iki bana uyar. Ana girişte buluşalım."},{"choose":[{"en":"Sound good, see you yesterday.","correct":false,"why_tr":"“Sounds” gerekir; “yesterday” ise anlamsız."},{"en":"Sounds good! See you on Saturday.","correct":true,"why_tr":"Kabul ediyor ve doğal biçimde vedalaşıyor."},{"en":"Sounds goods! See you on Saturday.","correct":false,"why_tr":"“goods” mal, eşya demektir."}],"q":"En uygun yanıt hangisi?"}]'::jsonb,array['4cd556b3-816a-522a-b69c-e9ed338b3d4b','1e9e12b5-cf63-550f-818c-d7d45e2dddb1','5711851b-1aa6-5815-903e-a06483040924']::uuid[],'choice',1,'draft');
insert into public.scenarios (id,pack_id,title_tr,situation_tr,turns,target_ids,mode,difficulty,status) values ('a87f13c2-a1e7-58c0-87ba-8441378bc5b7','1ec86e14-8694-5f09-89f1-2ad9ef7f19f5','Yemeği erteleme','Bu akşamki yemeğe gidemeyeceksin. Arkadaşına nazikçe haber veriyorsun.','[{"speaker":"Kerem","en":"We''re still meeting for dinner tonight, right?","tr":"Bu akşam yemekte buluşuyoruz, değil mi?"},{"choose":[{"en":"I''m afraid I can. I have to work late.","correct":false,"why_tr":"Olumlu cevap ardından gelen mazeretle çelişiyor."},{"en":"I''m afraid of I can''t, I postpone Friday.","correct":false,"why_tr":"“of” fazla ve cümle bozuk."},{"en":"I''m afraid I can''t. I have to work late. Can we postpone it until Friday?","correct":true,"why_tr":"Nazikçe reddediyor, nedenini söylüyor ve yeni bir zaman öneriyor."}],"q":"En uygun yanıt hangisi?"},{"speaker":"Kerem","en":"No problem. Friday works for me.","tr":"Sorun değil. Cuma bana uyar."},{"choose":[{"en":"Great, thanks for understanding!","correct":true,"why_tr":"Anlayış gösterdiği için teşekkür ediyor."},{"en":"Great, I cancel Friday too.","correct":false,"why_tr":"Az önce önerdiği günü iptal ediyor; anlamsız."},{"en":"Great, thanks for understand!","correct":false,"why_tr":"“for” sonrası -ing gerekir: understanding."}],"q":"En uygun yanıt hangisi?"}]'::jsonb,array['346aafd8-1adc-5fc5-adda-cd7f5aa4096e','e74c0c92-6868-55b0-9f8a-a88f7e4c2d42','cc4ec634-3c5a-5409-b2f5-cca746cf6536']::uuid[],'choice',2,'draft');
insert into public.scenarios (id,pack_id,title_tr,situation_tr,turns,target_ids,mode,difficulty,status) values ('6549ddd3-72d2-5c59-9ad4-fed64eb0ee28','2fe5da34-f4cb-5c47-8c4e-d94faab76c7f','İlk iş günü','Yeni işinde ilk günün. Tasarım ekibinden bir iş arkadaşı kendini tanıtıyor.','[{"speaker":"Murat","en":"Hi, I''m Murat from the design team. You must be new here.","tr":"Selam, ben tasarım ekibinden Murat. Burada yenisin galiba."},{"choose":[{"en":"Yes, I started today. I''m Deniz. Nice to meet you!","correct":true,"why_tr":"Kendini tanıtıyor ve uygun selamlaşmayı kullanıyor."},{"en":"No, I''m Deniz. How do you do it?","correct":false,"why_tr":"“How do you do it?” “Bunu nasıl yapıyorsun?” demektir."},{"en":"Yes, I start yesterday. Nice to meat you!","correct":false,"why_tr":"Zaman yanlış; ayrıca “meat” et demektir."}],"q":"En uygun yanıt hangisi?"},{"speaker":"Murat","en":"Nice to meet you too. Where are you from?","tr":"Ben de memnun oldum. Nerelisin?"},{"choose":[{"en":"I''m originally from Trabzon, but I''ve lived in İstanbul for five years.","correct":true,"why_tr":"Aslen nereli olduğunu ve ne zamandır nerede yaşadığını doğru anlatıyor."},{"en":"I''m from Trabzon since five years.","correct":false,"why_tr":"Süre için “for” ve present perfect gerekir."},{"en":"I live from Trabzon.","correct":false,"why_tr":"“live from” denmez; “I''m from Trabzon” denir."}],"q":"En uygun yanıt hangisi?"}]'::jsonb,array['a10a7580-2b12-58a6-9341-3078301c7d05','a1b411b0-1da5-5f14-9e8f-0899e95821b3','ca08e11a-a09d-5b11-a14f-f39400ba8ca0']::uuid[],'choice',1,'draft');
insert into public.scenarios (id,pack_id,title_tr,situation_tr,turns,target_ids,mode,difficulty,status) values ('32120165-547a-5028-876c-56b4ae993734','2fe5da34-f4cb-5c47-8c4e-d94faab76c7f','Partide sohbet','Bir arkadaşının doğum günü partisindesin ve yeni tanıştığın biriyle sohbet ediyorsun.','[{"speaker":"Lena","en":"So, what do you do in your spare time?","tr":"Peki, boş zamanında neler yaparsın?"},{"choose":[{"en":"My spare time is on Saturday.","correct":false,"why_tr":"Soru ne yaptığını soruyor, ne zaman boş olduğunu değil."},{"en":"I like hike and take photo.","correct":false,"why_tr":"“like” sonrası -ing gerekir; “photos” çoğul olmalı."},{"en":"I like hiking and taking photos. What about you?","correct":true,"why_tr":"Soruyu yanıtlıyor ve sohbeti sürdürmek için geri soruyor."}],"q":"En uygun yanıt hangisi?"},{"speaker":"Lena","en":"I love hiking too! There''s a nice trail near the lake.","tr":"Ben de yürüyüşe bayılırım! Gölün yakınında güzel bir parkur var."},{"choose":[{"en":"Really? Me neither.","correct":false,"why_tr":"“Me neither” olumsuz bir cümleye verilir."},{"en":"Really? I''m not interested on it.","correct":false,"why_tr":"Edat yanlış ve sohbeti kaba biçimde kapatıyor."},{"en":"Really? That sounds great. We should go together sometime.","correct":true,"why_tr":"İlgi gösteriyor ve doğal bir öneri yapıyor."}],"q":"En uygun yanıt hangisi?"}]'::jsonb,array['2f943885-32d9-5760-babf-f15db7430c23','d3dbc965-20b5-5453-8d7b-3655064a251c','6d77ac97-dead-53c4-be13-a5c0dc202b65']::uuid[],'choice',1,'draft');
insert into public.scenarios (id,pack_id,title_tr,situation_tr,turns,target_ids,mode,difficulty,status) values ('350f12c6-217e-5741-8741-5eeac61e4cd2','9fec7c37-b21c-53df-8fc9-49684d6cfa85','Otelde arıza bildirme','Otel odanda klima çalışmıyor. Resepsiyonu arıyorsun.','[{"speaker":"Receptionist","en":"Good evening, reception. How can I help you?","tr":"İyi akşamlar, resepsiyon. Size nasıl yardımcı olabilirim?"},{"choose":[{"en":"Hi, room 304. The air conditioner don''t work.","correct":false,"why_tr":"Tekil özne ile “doesn''t” gerekir."},{"en":"Hi, I''m the air conditioner in room 304.","correct":false,"why_tr":"Kendini klima olarak tanıtıyor; anlamsız."},{"en":"Hi, this is room 304. The air conditioner doesn''t work.","correct":true,"why_tr":"Oda numarasını ve sorunu net söylüyor."}],"q":"En uygun yanıt hangisi?"},{"speaker":"Receptionist","en":"I''m sorry about that. Someone will come to fix it in ten minutes.","tr":"Bunun için üzgünüm. On dakika içinde biri gelip tamir edecek."},{"choose":[{"en":"Thank you. Could I also has an extra blanket?","correct":false,"why_tr":"“could” sonrası fiil yalın olur: have."},{"en":"Thank you, but it''s not urgent, so fix it now.","correct":false,"why_tr":"Çelişkili: acil değil deyip hemen istiyor."},{"en":"Thank you. Could I also have an extra blanket, please?","correct":true,"why_tr":"Teşekkür ediyor ve kibar bir ek istekte bulunuyor."}],"q":"En uygun yanıt hangisi?"}]'::jsonb,array['b7fab66e-d891-5139-9870-c333d6c6b3e1','65e28ef2-98ad-5705-aafd-4d3b7e637fa7','f9ed532c-f561-5409-84ed-e0327f0b1dec']::uuid[],'choice',1,'draft');
insert into public.scenarios (id,pack_id,title_tr,situation_tr,turns,target_ids,mode,difficulty,status) values ('902ecaed-f548-54ca-82f3-0550526d7166','9fec7c37-b21c-53df-8fc9-49684d6cfa85','Mağazada ürün değiştirme','Dün aldığın gömlek küçük geldi. Mağazada daha büyük bir bedenle değiştirmek istiyorsun.','[{"speaker":"Shop assistant","en":"Hello! Can I help you?","tr":"Merhaba! Yardımcı olabilir miyim?"},{"choose":[{"en":"Yes, I buyed this shirt, it''s too small.","correct":false,"why_tr":"“buy” düzensiz bir fiildir: bought."},{"en":"Yes, can I exchange me a medium?","correct":false,"why_tr":"Yapı bozuk; doğrusu “exchange it for a medium”."},{"en":"Yes, I bought this shirt yesterday, but it''s too small. Can I exchange it for a medium?","correct":true,"why_tr":"Durumu ve isteğini açık ve kibar biçimde anlatıyor."}],"q":"En uygun yanıt hangisi?"},{"speaker":"Shop assistant","en":"Of course. Do you have the receipt?","tr":"Elbette. Fişiniz var mı?"},{"choose":[{"en":"Yes, here is it.","correct":false,"why_tr":"Kelime sırası yanlış: here it is."},{"en":"Yes, here it is.","correct":true,"why_tr":"Bir şeyi uzatırken kullanılan doğal kalıp."},{"en":"Yes, I have the recipe.","correct":false,"why_tr":"“recipe” yemek tarifidir."}],"q":"En uygun yanıt hangisi?"}]'::jsonb,array['30e2fa1c-d797-579a-b17f-e512f4d2e8d5','7bf53bc7-0a5c-5e6d-a432-93e882fd214d','691a24be-eb96-5a09-b1f4-54b43ee23d53']::uuid[],'choice',2,'draft');
insert into public.scenarios (id,pack_id,title_tr,situation_tr,turns,target_ids,mode,difficulty,status) values ('6f7cc84f-f7ed-58e0-b82b-3e642f341c02','26515c63-3bd4-5d24-9fbd-336e392868a3','İnceleme yorumuna yanıt verme','Bir ekip arkadaşın PR''ına yorum bıraktı: aynı mantık iki bileşende tekrarlanmış.','[{"speaker":"Reviewer","en":"This logic is duplicated in two components. Could we move it to a shared helper?","tr":"Bu mantık iki bileşende tekrarlanmış. Ortak bir yardımcıya taşıyabilir miyiz?"},{"choose":[{"en":"Good point. I''ll move it to a helper and update the PR.","correct":true,"why_tr":"Yorumu kabul edip ne yapacağını söylüyor."},{"en":"Good paint. I''ll move it to a helper.","correct":false,"why_tr":"“paint” boya demektir; doğru ifade “Good point”."},{"en":"No point. It is duplicated because duplicated.","correct":false,"why_tr":"Kaba ve anlamsız bir gerekçe."}],"q":"En uygun yanıt hangisi?"},{"speaker":"Reviewer","en":"Thanks! Let me know when it''s ready for another look.","tr":"Teşekkürler! Tekrar bakmaya hazır olduğunda haber ver."},{"choose":[{"en":"Will do. I addressing all comments yesterday.","correct":false,"why_tr":"Fiil zamanı yanlış."},{"en":"Will do. I''ve added all your comments to the code.","correct":false,"why_tr":"Yorumlar koda eklenmez; gereği yapılır (addressed)."},{"en":"Will do. I''ve addressed all your comments now.","correct":true,"why_tr":"Kısa ve net; yorumların gereğinin yapıldığını bildiriyor."}],"q":"En uygun yanıt hangisi?"}]'::jsonb,array['4d000725-ddb0-56f9-8259-b32b3a7f742c','414b1b96-7f37-5533-ae80-d590497284bc','f8f7e7b1-953c-54f2-9fa3-c714e686ba94']::uuid[],'choice',2,'draft');
insert into public.scenarios (id,pack_id,title_tr,situation_tr,turns,target_ids,mode,difficulty,status) values ('4775ddb6-ac52-573d-9c2d-5dfc36ad0202','26515c63-3bd4-5d24-9fbd-336e392868a3','PR onaylama','Bir PR''ı inceledin. Küçük bir öneri dışında her şey iyi görünüyor.','[{"speaker":"Author","en":"Hi! Did you have a chance to look at my PR?","tr":"Merhaba! PR''ıma bakma fırsatın oldu mu?"},{"choose":[{"en":"Yes, it is a nitpick, so I can''t approve.","correct":false,"why_tr":"Küçük bir not onayı engellemez; anlam çelişkili."},{"en":"Yes, looks good to me. Just one nitpick about a variable name.","correct":true,"why_tr":"Onay veriyor ve küçük notu belirtiyor."},{"en":"Yes, looks good at me, no nitpicks for merge.","correct":false,"why_tr":"Edat yanlış ve cümle bozuk."}],"q":"En uygun yanıt hangisi?"},{"speaker":"Author","en":"Thanks! Can I merge it after I fix that?","tr":"Teşekkürler! Onu düzelttikten sonra birleştirebilir miyim?"},{"choose":[{"en":"Sure, feel free to merge once the tests pass.","correct":true,"why_tr":"Onay veriyor ve koşulu net söylüyor."},{"en":"Sure, feel free merge.","correct":false,"why_tr":"“feel free to + fiil” kalıbında “to” eksik."},{"en":"Sure, feel free to merge before you write it.","correct":false,"why_tr":"Mantıksız: henüz yazılmamış kod birleştirilmez."}],"q":"En uygun yanıt hangisi?"}]'::jsonb,array['b989cb15-0fba-5e2a-8780-384bfb12e524','28fe1b03-a43d-5c98-9f2e-bd083346a336','0876e386-341f-5164-94ee-0fec3c70d5e8']::uuid[],'choice',1,'draft');
insert into public.scenarios (id,pack_id,title_tr,situation_tr,turns,target_ids,mode,difficulty,status) values ('01d466c0-5cd1-5ef2-8f8a-2276d54e1f2a','8c6847cf-f469-5cd6-b2d7-4c15dbfd531a','Çökmeyi bildirme','Ekip kanalındasın. Uygulama büyük dosya yüklenirken çöküyor ve sen bunu her seferinde yeniden oluşturabiliyorsun.','[{"speaker":"QA engineer","en":"Hey, did you see the crash report from this morning?","tr":"Selam, bu sabahki çökme raporunu gördün mü?"},{"choose":[{"en":"Yes. I reproduced it never.","correct":false,"why_tr":"“never” bu konumda kullanılmaz; doğrusu “I''ve never reproduced it.”"},{"en":"Yes. It crashes when I upload a large file, and I can reproduce it every time.","correct":true,"why_tr":"Ne olduğunu ve her seferinde yeniden oluşturulabildiğini net anlatıyor."},{"en":"Yes. It crushes when I upload a large file.","correct":false,"why_tr":"“crush” ezmek demektir; uygulama için “crash” kullanılır."}],"q":"En uygun yanıt hangisi?"},{"speaker":"QA engineer","en":"Great. Can you add the steps to reproduce to the ticket?","tr":"Harika. Yeniden oluşturma adımlarını kayda ekleyebilir misin?"},{"choose":[{"en":"Sure, I''ll remove them from the ticket.","correct":false,"why_tr":"İstenenin tersi: eklemek yerine kaldırmak."},{"en":"Sure, I''ll add them yesterday.","correct":false,"why_tr":"“will” ile “yesterday” birlikte kullanılmaz."},{"en":"Sure, I''ll add them with the full stack trace.","correct":true,"why_tr":"İsteği kabul edip faydalı bir ek bilgi sunuyor."}],"q":"En uygun yanıt hangisi?"}]'::jsonb,array['f280db72-ad91-5c7a-a568-581292437396','8a79cd26-bd6e-5349-95ef-ca5ca4931667','98e4bf70-ae82-5171-a032-baec8fa2108d']::uuid[],'choice',2,'draft');
insert into public.scenarios (id,pack_id,title_tr,situation_tr,turns,target_ids,mode,difficulty,status) values ('b36504e8-cf8e-568e-89d9-fe5249ebfdc3','8c6847cf-f469-5cd6-b2d7-4c15dbfd531a','Kesintiyi açıklama','Kısa bir hizmet kesintisi oldu. Ekip lideri ne olduğunu ve kök nedeni soruyor.','[{"speaker":"Team lead","en":"What happened during the outage?","tr":"Kesinti sırasında ne oldu?"},{"choose":[{"en":"A bad config change caused timeouts, so we rolled back the release.","correct":true,"why_tr":"Nedeni ve alınan önlemi doğru sırayla anlatıyor."},{"en":"We rolled out the outage to all users.","correct":false,"why_tr":"Kesinti “roll out” edilmez; anlam saçma."},{"en":"The outage caused a bad config change.","correct":false,"why_tr":"Neden-sonuç ters kurulmuş."}],"q":"En uygun yanıt hangisi?"},{"speaker":"Team lead","en":"Do we know the root cause yet?","tr":"Kök nedeni artık biliyor muyuz?"},{"choose":[{"en":"Not yet, so the root cause fixed it.","correct":false,"why_tr":"Anlamsız: bir neden bir şeyi düzeltmez."},{"en":"Not yet. For now, we have a workaround: we restart the service every hour.","correct":true,"why_tr":"Durumu dürüstçe söylüyor ve geçici çözümü açıklıyor."},{"en":"Yes, the root cause is a workaround.","correct":false,"why_tr":"Geçici çözüm bir neden değildir."}],"q":"En uygun yanıt hangisi?"}]'::jsonb,array['dd6348f0-0616-5661-830b-41055252e91b','9b01a6fc-4488-53fd-9b80-e50589889cc4','578b51f1-decc-5ff2-a3c1-c5c013ba7191','31432227-ee16-51fe-9e9e-dd96d70c358d']::uuid[],'choice',3,'draft');
insert into public.scenarios (id,pack_id,title_tr,situation_tr,turns,target_ids,mode,difficulty,status) values ('397399d1-1705-53cb-9114-55b027b305b5','b2d05b0d-3f42-5152-8985-f7b28dde1bdb','Toplantıda engeli açıklama','Günlük toplantıdasın. API değişikliği yüzünden ilerleyemiyorsun ve yardım istemek istiyorsun.','[{"speaker":"Team lead","en":"Morning, everyone! Any blockers today?","tr":"Herkese günaydın! Bugün bir engel var mı?"},{"choose":[{"en":"Yes, I''m blocked by the API change. Could someone from the backend team help me?","correct":true,"why_tr":"Engeli ve isteği açıkça söylüyor; “Could someone…” nazik bir istek."},{"en":"Yes, I block the API change today.","correct":false,"why_tr":"“I block” API''yi senin engellediğin anlamına gelir; anlam ters."},{"en":"No blockers, so I need help with the API.","correct":false,"why_tr":"Kendiyle çelişiyor: engel yok deyip yardım istiyor."}],"q":"En uygun yanıt hangisi?"},{"speaker":"Team lead","en":"Sure. Ali, can you pair with her after the meeting?","tr":"Tabii. Ali, toplantıdan sonra onunla eşli çalışabilir misin?"},{"speaker":"Ali","en":"Of course. I''ll message you at eleven.","tr":"Elbette. Saat on birde sana yazarım."}]'::jsonb,array['d9d18a04-8e67-515f-9a2a-a9d76e0ab7d2','b032299d-4f4a-549f-bdc7-98fac97f090c','d321734c-f8bd-55a5-a87e-5796e9a5455e']::uuid[],'choice',2,'draft');
insert into public.scenarios (id,pack_id,title_tr,situation_tr,turns,target_ids,mode,difficulty,status) values ('0bb4da08-039b-5f4b-8856-3f8e2540f6d7','b2d05b0d-3f42-5152-8985-f7b28dde1bdb','Durum bildirme','Scrum master senden günlük durum bilgisi istiyor. Dün arama filtrelerini bitirdin, bugün test yazacaksın.','[{"speaker":"Scrum master","en":"Deniz, what''s your update?","tr":"Deniz, son durum ne?"},{"choose":[{"en":"I finish yesterday the search filters and tomorrow tests.","correct":false,"why_tr":"Fiil zamanı ve kelime sırası yanlış."},{"en":"Yesterday I finished the search filters. Today I''m going to write the tests.","correct":true,"why_tr":"Dün için geçmiş zaman, bugün için plan kalıbı doğru kullanılmış."},{"en":"Yesterday I''m finishing the search filters. Today I wrote the tests.","correct":false,"why_tr":"Zamanlar ters: dün için geçmiş, bugün için gelecek gerekir."}],"q":"En uygun yanıt hangisi?"},{"speaker":"Scrum master","en":"Great. Are you still on track for Friday?","tr":"Harika. Cuma için hâlâ plana uygun mu gidiyorsun?"},{"choose":[{"en":"No, the deadline is on track.","correct":false,"why_tr":"Soru senin işinin durumunu soruyor; son tarih “on track” olmaz."},{"en":"Yes, I''m on board for Friday.","correct":false,"why_tr":"“on board” ekibe katılmak demektir; işin plana uygunluğunu anlatmaz."},{"en":"Yes, but I''ll need the API key by Wednesday.","correct":true,"why_tr":"Evet deyip bir koşulu net belirtiyor."}],"q":"En uygun yanıt hangisi?"}]'::jsonb,array['53347ac4-a54f-5723-9089-a284a5cc7ec0','2b2da3fb-2b99-5a05-8447-831c934b4add','2726a436-ecf6-5d10-8d91-7d00337fd354']::uuid[],'choice',2,'draft');
insert into public.scenarios (id,pack_id,title_tr,situation_tr,turns,target_ids,mode,difficulty,status) values ('187b5a27-e2a5-5cb3-9a39-db48c2d9041e','2e27320a-9d7f-514d-b3d5-0606c1f40344','Bağlaç seçimi','Bir arkadaşınla sınava çalışıyorsunuz. Boşluğa hangi bağlacın uyduğunu tartışıyorsunuz.','[{"speaker":"Friend","en":"The sentence is: ''___ the high cost, many people buy electric cars.'' Which word fits?","tr":"Cümle şu: “___ the high cost, many people buy electric cars.” Hangi kelime uyar?"},{"choose":[{"en":"''Although'', because the sentence shows contrast.","correct":false,"why_tr":"Karşıtlık doğru ama “although” sonrası cümle gelir; burada isim var."},{"en":"''Because of'', because the cost is the reason.","correct":false,"why_tr":"Yüksek maliyet satın almanın nedeni değildir; anlam ters."},{"en":"''Despite'', because a noun follows and the sentence shows contrast.","correct":true,"why_tr":"Ardından isim (the high cost) geliyor ve karşıtlık var."}],"q":"En uygun yanıt hangisi?"},{"speaker":"Friend","en":"And what about ''___ the cost was high, many people bought them.''?","tr":"Peki “___ the cost was high, many people bought them.” için?"},{"choose":[{"en":"''Despite'', because it shows contrast.","correct":false,"why_tr":"Ardından tam cümle geldiği için “despite” kullanılamaz."},{"en":"''Therefore'', because it''s a result.","correct":false,"why_tr":"Anlam karşıtlıktır, sonuç değil."},{"en":"''Although'', because a full clause follows.","correct":true,"why_tr":"Ardından tam bir cümle (özne + fiil) geliyor."}],"q":"En uygun yanıt hangisi?"}]'::jsonb,array['546660da-64cf-55e1-9800-dec52ed32589','0006e22f-6efb-5de9-89ed-3f08260f8bf7']::uuid[],'choice',3,'draft');
insert into public.scenarios (id,pack_id,title_tr,situation_tr,turns,target_ids,mode,difficulty,status) values ('428e7fec-318d-5b98-85a7-6915c0c3136b','2e27320a-9d7f-514d-b3d5-0606c1f40344','Grafiği yorumlama','Seminerde şehirlerde artan hava kirliliğini gösteren bir grafiği yorumluyorsun.','[{"speaker":"Lecturer","en":"What are the main factors behind the rise in air pollution?","tr":"Hava kirliliğindeki artışın arkasındaki temel etkenler neler?"},{"choose":[{"en":"Traffic contributes with it, mainly because factories.","correct":false,"why_tr":"Yapı yanlış: contribute to, because of."},{"en":"Traffic and factories contribute to it, but the increase is mainly due to traffic.","correct":true,"why_tr":"Etkenleri sayıyor ve hangisinin ağır bastığını söylüyor."},{"en":"The main factor is that pollution causes traffic.","correct":false,"why_tr":"Neden-sonuç ters kurulmuş."}],"q":"En uygun yanıt hangisi?"},{"speaker":"Lecturer","en":"And what are the consequences for public health?","tr":"Peki halk sağlığı açısından sonuçları neler?"},{"choose":[{"en":"It has no consequences; therefore, it is dangerous.","correct":false,"why_tr":"Kendiyle çelişen bir mantık."},{"en":"It can lead to breathing problems, especially in children.","correct":true,"why_tr":"Sonucu doğru kalıpla (lead to) anlatıyor."},{"en":"It can lead from breathing problems.","correct":false,"why_tr":"“lead from” denmez; doğrusu “lead to”."}],"q":"En uygun yanıt hangisi?"}]'::jsonb,array['5b0f2ac9-f377-5853-9e36-2b03192fb39e','99cd6020-2e82-5d54-97b0-59a50f0ccd62','4fcc5c6e-1c14-5c44-90c8-6c8fc86cb906','4c8dc184-ff13-570f-b5f9-6f357f2be096']::uuid[],'choice',3,'draft');
insert into public.scenarios (id,pack_id,title_tr,situation_tr,turns,target_ids,mode,difficulty,status) values ('fe40c5ab-c9ec-5af1-8c5e-f427e0fd11c3','e6ad2555-ff51-5462-82ce-6e582d7ec447','Grafiği anlatma','Seminerde bir şirketin 2015–2024 satışlarını gösteren çizgi grafiği anlatıyorsun.','[{"speaker":"Lecturer","en":"Can you describe the trend in sales?","tr":"Satışlardaki eğilimi anlatabilir misin?"},{"choose":[{"en":"Sales increased steady from 2015 to 2019.","correct":false,"why_tr":"Fiili niteleyen zarf gerekir: steadily."},{"en":"Sales has increase from 2015 to 2019.","correct":false,"why_tr":"Çoğul özne ve fiil biçimi yanlış; bitmiş dönem için past simple gerekir."},{"en":"Sales increased steadily from 2015 to 2019 and reached a peak in 2020.","correct":true,"why_tr":"Zarf, zaman ve “reach a peak” kalıbı doğru."}],"q":"En uygun yanıt hangisi?"},{"speaker":"Lecturer","en":"And what happened after 2020?","tr":"Peki 2020''den sonra ne oldu?"},{"choose":[{"en":"They have fallen in 2021 by slightly.","correct":false,"why_tr":"Belirli bir yılla present perfect kullanılmaz; “by slightly” yanlış."},{"en":"They fell slight and then leveled up.","correct":false,"why_tr":"Zarf gerekir (slightly); “level up” seviye atlamak demektir."},{"en":"They fell slightly and then leveled off.","correct":true,"why_tr":"Hafif düşüşü ve sabitlenmeyi doğru anlatıyor."}],"q":"En uygun yanıt hangisi?"}]'::jsonb,array['8a7b1308-47ec-5620-bca8-8b81d8d29626','32e4d029-025b-5d5f-9dba-2d9853b41dee','9ab09d58-5c8f-5b1d-b2e1-cb760f2f35ae']::uuid[],'choice',3,'draft');
insert into public.scenarios (id,pack_id,title_tr,situation_tr,turns,target_ids,mode,difficulty,status) values ('32d1bc34-393a-5e7d-8eab-6732a4e7908d','e6ad2555-ff51-5462-82ce-6e582d7ec447','Oranı yorumlama','Bir rapordaki oranı arkadaşına açıklıyorsun.','[{"speaker":"Friend","en":"The report says women accounted for 60% of the participants. What does that mean?","tr":"Raporda katılımcıların %60''ını kadınların oluşturduğu yazıyor. Bu ne demek?"},{"choose":[{"en":"It means that six out of ten participants were women.","correct":true,"why_tr":"“account for” burada “oluşturmak” demektir."},{"en":"It means that women counted the participants.","correct":false,"why_tr":"“account for” burada saymak anlamında değildir."},{"en":"It means that exactly 60 women took part.","correct":false,"why_tr":"Oran ile sayı karıştırılmış; toplam katılımcı sayısı verilmiyor."}],"q":"En uygun yanıt hangisi?"},{"speaker":"Friend","en":"Is that a large proportion?","tr":"Bu büyük bir oran mı?"},{"choose":[{"en":"Yes, it''s more than half.","correct":true,"why_tr":"%60 yarıdan fazladır."},{"en":"No, it''s less than a third.","correct":false,"why_tr":"%60 üçte birden fazladır."},{"en":"Yes, it''s more than double.","correct":false,"why_tr":"%60 yarıdan fazladır; iki kat değildir."}],"q":"En uygun yanıt hangisi?"}]'::jsonb,array['94696ac6-ac6e-5a6e-aa72-5f7813d67e59','c7e29852-350e-55bf-86e9-f156b85a391a','b4447e5a-cc97-5e2e-9f44-4510209677d8']::uuid[],'choice',2,'draft');
insert into public.scenarios (id,pack_id,title_tr,situation_tr,turns,target_ids,mode,difficulty,status) values ('2395615d-48ce-59f6-bacb-a46363b07e11','de1b4712-7243-59d2-b591-86fd886a91fd','Özetteki cümleyi yorumlama','Bir makale özeti okudun. Ders arkadaşın bir cümlenin ne anlama geldiğini soruyor.','[{"speaker":"Classmate","en":"The abstract says: ''The findings suggest that exercise may improve memory in older adults.'' What does that mean?","tr":"Özette şöyle yazıyor: “Bulgular, egzersizin yaşlı yetişkinlerde hafızayı geliştirebileceğini düşündürüyor.” Bu ne demek?"},{"choose":[{"en":"The study found that older adults don''t like exercise.","correct":false,"why_tr":"Cümlede böyle bir bilgi yok."},{"en":"The study proved that exercise always improves memory.","correct":false,"why_tr":"“suggest” ve “may” kesin kanıt anlamına gelmez; “always” da cümlede yok."},{"en":"The study found a possible positive effect of exercise on memory, but it isn''t certain.","correct":true,"why_tr":"“suggest” ve “may” temkinli dildir; kesinlik bildirmez."}],"q":"En uygun yanıt hangisi?"},{"speaker":"Classmate","en":"So was their hypothesis supported?","tr":"Yani hipotezleri desteklendi mi?"},{"choose":[{"en":"Yes, so no further research is needed.","correct":false,"why_tr":"Temkinli bulgular kesin sonuç sayılmaz; çıkarım yanlış."},{"en":"Partly. The results point in that direction, but they are not conclusive.","correct":true,"why_tr":"Temkinli bulguyu doğru yorumluyor."},{"en":"No, because the hypothesis was a participant.","correct":false,"why_tr":"Hipotez bir katılımcı değildir; anlamsız."}],"q":"En uygun yanıt hangisi?"}]'::jsonb,array['4a71443f-7aec-54e4-8fac-e8634d80e98e','4d056db7-9cbe-579f-a583-3e4b7ea23510','3290fd7c-7d66-5125-8013-1c767dc343f0']::uuid[],'choice',3,'draft');
insert into public.scenarios (id,pack_id,title_tr,situation_tr,turns,target_ids,mode,difficulty,status) values ('9a3142fd-5e83-5f4b-b49b-83f05ab9110d','de1b4712-7243-59d2-b591-86fd886a91fd','Kısıtlılıkları tartışma','Seminerde hoca bir çalışmanın kısıtlılıklarını soruyor.','[{"speaker":"Professor","en":"What is one limitation of this study?","tr":"Bu çalışmanın bir kısıtlılığı nedir?"},{"choose":[{"en":"The sample was very small, so the results are more reliable.","correct":false,"why_tr":"Küçük örneklem güvenilirliği artırmaz; mantık hatası."},{"en":"The sample was very small, so the results may not be reliable.","correct":true,"why_tr":"Kısıtlılığı ve sonucunu mantıklı biçimde bağlıyor."},{"en":"The limitation is that the study was conducted.","correct":false,"why_tr":"Anlamsız bir gerekçe."}],"q":"En uygun yanıt hangisi?"},{"speaker":"Professor","en":"Good. Why do you think the two groups gave different answers?","tr":"Güzel. Sence iki grup neden farklı yanıtlar verdi?"},{"choose":[{"en":"This may be due to cultural differences between the groups.","correct":true,"why_tr":"Olası nedeni temkinli bir dille söylüyor."},{"en":"This may be do to cultural differences.","correct":false,"why_tr":"“do” bir fiildir; doğrusu “due to”."},{"en":"This may be due of cultural differences.","correct":false,"why_tr":"Edat yanlış: due to."}],"q":"En uygun yanıt hangisi?"}]'::jsonb,array['83cc93e4-da20-54fa-8a46-a4fec28d34a7','43b63a4d-cb25-5171-b72f-85d61185a166','a874e378-882e-5a57-9860-1a40125b961e']::uuid[],'choice',3,'draft');
insert into public.readings (id,pack_id,title,kind,sentences,glossary,questions,difficulty,status) values ('eb2863b0-d37e-544c-9dc1-5d68d26e76df','6fbbf6ec-47c4-5a61-ae2a-085acb973117','Incident report: conveyor stop','Arıza raporu','[{"en":"On 12 March, conveyor 4 stopped for two hours.","tr":"12 Mart''ta 4 numaralı konveyör iki saat durdu."},{"en":"The stop was caused by a worn bearing in the main motor.","tr":"Duruş, ana motordaki aşınmış bir rulmandan kaynaklandı."},{"en":"As a temporary fix, the team replaced the bearing with a spare part.","tr":"Geçici çözüm olarak ekip rulmanı yedek parçayla değiştirdi."},{"en":"To prevent this issue in the future, we recommend inspecting the bearings every month.","tr":"Bu sorunun gelecekte yaşanmaması için rulmanların her ay muayene edilmesini öneriyoruz."}]'::jsonb,'[{"term":"conveyor","tr":"konveyör, taşıma bandı"},{"term":"worn","tr":"aşınmış"},{"term":"spare part","tr":"yedek parça"},{"term":"inspecting","tr":"muayene etmek"}]'::jsonb,'[{"q_tr":"Konveyör neden durdu?","options":["Elektrik kesildi","Ana motordaki rulman aşınmıştı","Operatör hata yaptı"],"answer":1,"why_tr":"“caused by a worn bearing in the main motor”"},{"q_tr":"Gelecek için öneri ne?","options":["Konveyörü tamamen değiştirmek","Rulmanları her ay muayene etmek","Motoru kalıcı olarak kapatmak"],"answer":1,"why_tr":"“we recommend inspecting the bearings every month”"}]'::jsonb,3,'draft');
insert into public.readings (id,pack_id,title,kind,sentences,glossary,questions,difficulty,status) values ('efe30f1e-c47d-5777-afc2-49fcf46560be','6fbbf6ec-47c4-5a61-ae2a-085acb973117','Options for the cooling problem','E-posta','[{"en":"Hi team, here are two options for the cooling problem.","tr":"Herkese merhaba, soğutma sorunu için iki seçenek var."},{"en":"Option A is to add a second fan. It''s quick and cheap, but it''s noisy.","tr":"A seçeneği ikinci bir fan eklemek. Hızlı ve ucuz ama gürültülü."},{"en":"Option B is to redesign the housing for better airflow. It''s more cost-effective in the long term, but it will take six weeks.","tr":"B seçeneği, daha iyi hava akışı için gövdeyi yeniden tasarlamak. Uzun vadede maliyet açısından daha verimli ama altı hafta sürecek."},{"en":"I suggest that we start with option A and plan option B for the next version.","tr":"A seçeneğiyle başlayıp B seçeneğini bir sonraki sürüm için planlamamızı öneriyorum."}]'::jsonb,'[{"term":"option","tr":"seçenek"},{"term":"airflow","tr":"hava akışı"},{"term":"cost-effective","tr":"maliyet açısından verimli"},{"term":"in the long term","tr":"uzun vadede"}]'::jsonb,'[{"q_tr":"A seçeneğinin dezavantajı ne?","options":["Pahalı olması","Gürültülü olması","Altı hafta sürmesi"],"answer":1,"why_tr":"“It''s quick and cheap, but it''s noisy.”"},{"q_tr":"Yazar ne öneriyor?","options":["Yalnız B seçeneğini uygulamak","Önce A seçeneğini uygulayıp B''yi sonraki sürüme planlamak","Hiçbir şey yapmamak"],"answer":1,"why_tr":"“start with option A and plan option B for the next version”"}]'::jsonb,3,'draft');
insert into public.readings (id,pack_id,title,kind,sentences,glossary,questions,difficulty,status) values ('9d298179-c283-5f80-8e68-9a9726a305e6','c016cb37-6858-58cd-ae01-49689b107921','Datasheet: centrifugal pump CP-40','Veri sayfası','[{"en":"Rated power: 2.2 kW.","tr":"Anma gücü: 2,2 kW."},{"en":"Maximum flow rate: 40 liters per minute.","tr":"Azami debi: dakikada 40 litre."},{"en":"Operating temperature range: −10 to 80 °C.","tr":"Çalışma sıcaklığı aralığı: −10 ile 80 °C arası."},{"en":"Housing material: stainless steel.","tr":"Gövde malzemesi: paslanmaz çelik."},{"en":"Weight: approximately 18 kg.","tr":"Ağırlık: yaklaşık 18 kg."}]'::jsonb,'[{"term":"rated power","tr":"anma gücü"},{"term":"flow rate","tr":"debi"},{"term":"range","tr":"aralık"},{"term":"housing","tr":"gövde, muhafaza"}]'::jsonb,'[{"q_tr":"Pompa hangi sıcaklıkta çalıştırılmamalı?","options":["0 °C","50 °C","95 °C"],"answer":2,"why_tr":"Çalışma aralığı −10 ile 80 °C arası; 95 °C bu aralığın dışında."},{"q_tr":"Pompanın gövdesi hangi malzemeden?","options":["Alüminyum","Paslanmaz çelik","Plastik"],"answer":1,"why_tr":"“Housing material: stainless steel.”"},{"q_tr":"Pompa dakikada en fazla ne kadar sıvı basabilir?","options":["18 litre","40 litre","80 litre"],"answer":1,"why_tr":"“Maximum flow rate: 40 liters per minute.”"}]'::jsonb,2,'draft');
insert into public.readings (id,pack_id,title,kind,sentences,glossary,questions,difficulty,status) values ('0e6c6c67-fe81-5e68-86a2-b975577619ea','c016cb37-6858-58cd-ae01-49689b107921','Measurement results','E-posta','[{"en":"Hi Burak, I measured the ten sample parts this morning.","tr":"Merhaba Burak, bu sabah on numune parçayı ölçtüm."},{"en":"Eight parts are within tolerance.","tr":"Sekiz parça tolerans içinde."},{"en":"Two parts have a diameter of 25.08 mm, which is 0.03 mm above the limit.","tr":"İki parçanın çapı 25,08 mm; bu, sınırın 0,03 mm üzerinde."},{"en":"The new gauge is more accurate than the old one, so I''m confident about the results.","tr":"Yeni ölçü aleti eskisinden daha hassas, bu yüzden sonuçlardan eminim."}]'::jsonb,'[{"term":"sample","tr":"numune"},{"term":"within tolerance","tr":"tolerans içinde"},{"term":"above the limit","tr":"sınırın üzerinde"},{"term":"gauge","tr":"ölçü aleti"}]'::jsonb,'[{"q_tr":"Kaç parça tolerans dışında?","options":["İki","Sekiz","On"],"answer":0,"why_tr":"On parçanın sekizi tolerans içinde; iki parça sınırın üzerinde."},{"q_tr":"Yazar sonuçlardan neden emin?","options":["Parçalar yeni","Yeni ölçü aleti daha hassas","Burak sonuçları onayladı"],"answer":1,"why_tr":"“The new gauge is more accurate than the old one.”"}]'::jsonb,3,'draft');
insert into public.readings (id,pack_id,title,kind,sentences,glossary,questions,difficulty,status) values ('208368da-0b36-568f-881d-d1eb5948dc55','233b0925-1efe-5baa-9090-54d6f8aef7d6','Test report: seal durability','Test raporu özeti','[{"en":"Objective: to check the durability of the new rubber seal.","tr":"Amaç: yeni kauçuk contanın dayanıklılığını kontrol etmek."},{"en":"Ten samples were tested at 90 °C for 500 hours.","tr":"On numune 90 °C''de 500 saat boyunca test edildi."},{"en":"Nine samples passed; one sample failed after 420 hours.","tr":"Dokuz numune testi geçti; bir numune 420 saat sonra başarısız oldu."},{"en":"There was no sign of corrosion on the metal parts.","tr":"Metal parçalarda korozyon belirtisi yoktu."},{"en":"We recommend testing a second batch before mass production.","tr":"Seri üretimden önce ikinci bir partinin test edilmesini öneriyoruz."}]'::jsonb,'[{"term":"objective","tr":"amaç"},{"term":"seal","tr":"conta"},{"term":"mass production","tr":"seri üretim"},{"term":"corrosion","tr":"korozyon"}]'::jsonb,'[{"q_tr":"Kaç numune başarısız oldu?","options":["Bir","Dokuz","On"],"answer":0,"why_tr":"“one sample failed after 420 hours”"},{"q_tr":"Raporun önerisi ne?","options":["Seri üretime hemen başlamak","Seri üretimden önce ikinci bir partiyi test etmek","Metal parçaları değiştirmek"],"answer":1,"why_tr":"“We recommend testing a second batch before mass production.”"},{"q_tr":"Test hangi sıcaklıkta yapıldı?","options":["20 °C","90 °C","500 °C"],"answer":1,"why_tr":"“tested at 90 °C for 500 hours”"}]'::jsonb,3,'draft');
insert into public.readings (id,pack_id,title,kind,sentences,glossary,questions,difficulty,status) values ('e436f6ce-78a0-5e7b-becf-5da891d3cdd0','233b0925-1efe-5baa-9090-54d6f8aef7d6','Lab rules: test bench 3','Laboratuvar notu','[{"en":"Always calibrate the load cell before each test.","tr":"Her testten önce mutlaka yük hücresini kalibre et."},{"en":"If the temperature exceeds 100 °C, the system stops automatically.","tr":"Sıcaklık 100 °C''yi aşarsa sistem otomatik olarak durur."},{"en":"Record all results in the shared spreadsheet.","tr":"Tüm sonuçları ortak tabloya kaydet."},{"en":"If you see a significant deviation, repeat the test and inform the lab manager.","tr":"Belirgin bir sapma görürsen testi tekrarla ve laboratuvar yöneticisine haber ver."}]'::jsonb,'[{"term":"load cell","tr":"yük hücresi"},{"term":"exceeds","tr":"aşar"},{"term":"spreadsheet","tr":"hesap tablosu"},{"term":"inform","tr":"haber vermek"}]'::jsonb,'[{"q_tr":"Sıcaklık 100 °C''yi aşarsa ne olur?","options":["Alarm çalar ama sistem çalışmaya devam eder","Sistem otomatik olarak durur","Test kendiliğinden tekrarlanır"],"answer":1,"why_tr":"“the system stops automatically”"},{"q_tr":"Belirgin bir sapma görürsen ne yapmalısın?","options":["Sonuçları silmelisin","Testi tekrarlayıp laboratuvar yöneticisine haber vermelisin","Yük hücresini değiştirmelisin"],"answer":1,"why_tr":"“repeat the test and inform the lab manager”"}]'::jsonb,2,'draft');
insert into public.readings (id,pack_id,title,kind,sentences,glossary,questions,difficulty,status) values ('cbd55bc7-deb4-5e27-908b-0ea5244e35a0','1ec86e14-8694-5f09-89f1-2ad9ef7f19f5','My typical week','Kişisel blog','[{"en":"On weekdays, I usually get up at 6:30 and commute to work by ferry.","tr":"Hafta içi genellikle 6.30''da kalkarım ve işe vapurla gidip gelirim."},{"en":"The ferry takes about 25 minutes, so I read a book on the way.","tr":"Vapur yaklaşık 25 dakika sürüyor, bu yüzden yolda kitap okurum."},{"en":"I always avoid the roads during rush hour.","tr":"Yoğun saatlerde yollardan hep uzak dururum."},{"en":"On Saturdays, I do the laundry and the grocery shopping.","tr":"Cumartesileri çamaşır yıkar ve market alışverişi yaparım."},{"en":"Sundays are for my family, and sometimes I take a nap after lunch.","tr":"Pazarlar ailem içindir ve bazen öğle yemeğinden sonra kısa bir uyku çekerim."}]'::jsonb,'[{"term":"commute","tr":"işe gidip gelmek"},{"term":"rush hour","tr":"yoğun saat"},{"term":"laundry","tr":"çamaşır"},{"term":"take a nap","tr":"kısa uyku çekmek"}]'::jsonb,'[{"q_tr":"Yazar işe nasıl gidip geliyor?","options":["Metroyla","Vapurla","Arabayla"],"answer":1,"why_tr":"“commute to work by ferry”"},{"q_tr":"Yazar cumartesileri ne yapar?","options":["Ailesini ziyaret eder","Çamaşır yıkar ve market alışverişi yapar","İşe gider"],"answer":1,"why_tr":"“On Saturdays, I do the laundry and the grocery shopping.”"},{"q_tr":"Yazar yolculuk sırasında ne yapar?","options":["Kitap okur","Uyur","E-posta yazar"],"answer":0,"why_tr":"“I read a book on the way.”"}]'::jsonb,2,'draft');
insert into public.readings (id,pack_id,title,kind,sentences,glossary,questions,difficulty,status) values ('f6660a06-ad8c-5c06-963f-e3252e044206','1ec86e14-8694-5f09-89f1-2ad9ef7f19f5','Weekend plans','Mesajlaşma','[{"en":"Ayşe: Hi! Do you have any plans for the weekend?","tr":"Ayşe: Selam! Hafta sonu için bir planın var mı?"},{"en":"Ali: I''m going to visit my grandparents on Saturday, but I''m free on Sunday.","tr":"Ali: Cumartesi büyükannemlere gideceğim ama pazar boşum."},{"en":"Ayşe: Great! How about a picnic in the park on Sunday?","tr":"Ayşe: Harika! Pazar günü parkta pikniğe ne dersin?"},{"en":"Ali: Sounds good. Let me check the weather and get back to you.","tr":"Ali: Olur. Havaya bir bakıp sana döneyim."}]'::jsonb,'[{"term":"plans","tr":"planlar"},{"term":"free","tr":"boş, müsait"},{"term":"How about … ?","tr":"… ne dersin?"},{"term":"get back to you","tr":"sana dönmek"}]'::jsonb,'[{"q_tr":"Ali cumartesi ne yapacak?","options":["Pikniğe gidecek","Büyükannesine ve büyükbabasına gidecek","Evde dinlenecek"],"answer":1,"why_tr":"“I''m going to visit my grandparents on Saturday.”"},{"q_tr":"Ali piknik için ne zaman kesin cevap verecek?","options":["Hemen","Havaya baktıktan sonra","Pazartesi"],"answer":1,"why_tr":"“Let me check the weather and get back to you.”"}]'::jsonb,1,'draft');
insert into public.readings (id,pack_id,title,kind,sentences,glossary,questions,difficulty,status) values ('7665891e-040f-5ec4-ba01-806b14c9b55b','2fe5da34-f4cb-5c47-8c4e-d94faab76c7f','About me','Kısa tanıtım','[{"en":"Hi! My name is Selin and I''m a physiotherapist.","tr":"Merhaba! Adım Selin ve fizyoterapistim."},{"en":"I''m originally from Eskişehir, but I''ve lived in Ankara for six years.","tr":"Aslen Eskişehirliyim ama altı yıldır Ankara''da yaşıyorum."},{"en":"I work at a small clinic near my home.","tr":"Evimin yakınındaki küçük bir klinikte çalışıyorum."},{"en":"In my spare time, I go swimming and I''m learning to play the violin.","tr":"Boş zamanımda yüzmeye gidiyorum ve keman çalmayı öğreniyorum."},{"en":"I''m a bit shy at first, but I get along well with most people.","tr":"İlk başta biraz utangacım ama çoğu insanla iyi geçinirim."}]'::jsonb,'[{"term":"originally","tr":"aslen"},{"term":"spare time","tr":"boş zaman"},{"term":"shy","tr":"utangaç"},{"term":"get along","tr":"iyi geçinmek"}]'::jsonb,'[{"q_tr":"Selin şu anda nerede yaşıyor?","options":["Eskişehir''de","Ankara''da","İstanbul''da"],"answer":1,"why_tr":"“I''ve lived in Ankara for six years.”"},{"q_tr":"Selin şu sıralar ne öğreniyor?","options":["Yüzmeyi","Keman çalmayı","Fizyoterapiyi"],"answer":1,"why_tr":"“I''m learning to play the violin.”"}]'::jsonb,1,'draft');
insert into public.readings (id,pack_id,title,kind,sentences,glossary,questions,difficulty,status) values ('234bf142-2aaf-5085-8c8b-ba5c9c816043','2fe5da34-f4cb-5c47-8c4e-d94faab76c7f','New team member','E-posta','[{"en":"Hello everyone, I''d like to introduce our new colleague, Emre.","tr":"Herkese merhaba, yeni iş arkadaşımız Emre''yi tanıtmak istiyorum."},{"en":"He graduated from Hacettepe University and he''s interested in data analysis.","tr":"Hacettepe Üniversitesi''nden mezun oldu ve veri analizine ilgi duyuyor."},{"en":"Emre is fluent in English and German.","tr":"Emre İngilizce ve Almancayı akıcı konuşuyor."},{"en":"He''s based in our Ankara office, so please say hello if you see him!","tr":"Ankara ofisimizde çalışıyor; onu görürseniz lütfen merhaba deyin!"}]'::jsonb,'[{"term":"introduce","tr":"tanıtmak"},{"term":"graduated from","tr":"-den mezun oldu"},{"term":"fluent in","tr":"-i akıcı konuşan"},{"term":"based in","tr":"-de çalışan"}]'::jsonb,'[{"q_tr":"Emre hangi alana ilgi duyuyor?","options":["Veri analizi","Tasarım","Satış"],"answer":0,"why_tr":"“he''s interested in data analysis”"},{"q_tr":"Emre hangi ofiste çalışıyor?","options":["İstanbul","Ankara","İzmir"],"answer":1,"why_tr":"“He''s based in our Ankara office.”"}]'::jsonb,2,'draft');
insert into public.readings (id,pack_id,title,kind,sentences,glossary,questions,difficulty,status) values ('2ad7e786-efe2-55d6-bd6a-024de6615bbd','9fec7c37-b21c-53df-8fc9-49684d6cfa85','Complaint: damaged order','E-posta','[{"en":"Dear Customer Service, I ordered a coffee machine from your website on 3 May.","tr":"Sayın Müşteri Hizmetleri, 3 Mayıs''ta web sitenizden bir kahve makinesi sipariş ettim."},{"en":"It was delivered yesterday, but the box arrived damaged and the machine doesn''t work.","tr":"Dün teslim edildi ama kutu hasarlı geldi ve makine çalışmıyor."},{"en":"I''d like to exchange it for a new one or get a full refund.","tr":"Makineyi yenisiyle değiştirmek ya da paramın tamamını geri almak istiyorum."},{"en":"I''ve attached a photo of the box and my receipt.","tr":"Kutunun fotoğrafını ve fişimi ekledim."}]'::jsonb,'[{"term":"delivered","tr":"teslim edildi"},{"term":"damaged","tr":"hasarlı"},{"term":"refund","tr":"para iadesi"},{"term":"attached","tr":"(e-postaya) ekledim"}]'::jsonb,'[{"q_tr":"Sorun ne?","options":["Sipariş hiç gelmedi","Kutu hasarlı geldi ve makine çalışmıyor","Yanlış renk geldi"],"answer":1,"why_tr":"“the box arrived damaged and the machine doesn''t work”"},{"q_tr":"Yazar ne istiyor?","options":["Yeni bir makine ya da para iadesi","Bir indirim kodu","Teslimatın ertelenmesi"],"answer":0,"why_tr":"“exchange it for a new one or get a full refund”"}]'::jsonb,2,'draft');
insert into public.readings (id,pack_id,title,kind,sentences,glossary,questions,difficulty,status) values ('0e708355-73bc-5b4c-9f92-14df11576094','9fec7c37-b21c-53df-8fc9-49684d6cfa85','Notice to all residents','Duyuru','[{"en":"Dear residents, there is a water leak in the basement.","tr":"Sayın sakinler, bodrum katta bir su sızıntısı var."},{"en":"A plumber will come to fix it on Tuesday morning.","tr":"Salı sabahı bir tesisatçı gelip tamir edecek."},{"en":"There will be no hot water from 9 am to 12 pm.","tr":"Saat 9 ile 12 arasında sıcak su olmayacak."},{"en":"If you have an urgent problem, please call the building manager.","tr":"Acil bir sorununuz olursa lütfen bina yöneticisini arayın."},{"en":"We''re sorry for the inconvenience.","tr":"Verdiğimiz rahatsızlık için özür dileriz."}]'::jsonb,'[{"term":"leak","tr":"sızıntı"},{"term":"plumber","tr":"tesisatçı"},{"term":"urgent","tr":"acil"},{"term":"inconvenience","tr":"rahatsızlık"}]'::jsonb,'[{"q_tr":"Salı sabahı ne olacak?","options":["Bina boyanacak","Bir tesisatçı sızıntıyı tamir edecek","Asansör değiştirilecek"],"answer":1,"why_tr":"“A plumber will come to fix it on Tuesday morning.”"},{"q_tr":"Acil bir sorunda kimi aramalısın?","options":["Tesisatçıyı","Bina yöneticisini","Komşunu"],"answer":1,"why_tr":"“please call the building manager”"}]'::jsonb,2,'draft');
insert into public.readings (id,pack_id,title,kind,sentences,glossary,questions,difficulty,status) values ('81f037ee-9380-5bb3-a1f6-2dff7d490023','26515c63-3bd4-5d24-9fbd-336e392868a3','PR: Add search filters','PR açıklaması','[{"en":"This PR adds price and category filters to the search page.","tr":"Bu PR, arama sayfasına fiyat ve kategori filtreleri ekliyor."},{"en":"I refactored the search service so that each filter is a small function.","tr":"Arama servisini, her filtre küçük bir fonksiyon olacak şekilde yeniden düzenledim."},{"en":"Test coverage for the search module is now 85%.","tr":"Arama modülünün test kapsamı artık %85."},{"en":"The old filter API is deprecated but still works.","tr":"Eski filtre API''si kullanımdan kaldırıldı ama hâlâ çalışıyor."},{"en":"Please review the naming in filters.ts carefully.","tr":"Lütfen filters.ts dosyasındaki adlandırmayı dikkatle incele."}]'::jsonb,'[{"term":"refactored","tr":"yeniden düzenlendi"},{"term":"coverage","tr":"test kapsamı"},{"term":"deprecated","tr":"kullanımdan kaldırılmış"},{"term":"naming","tr":"adlandırma"}]'::jsonb,'[{"q_tr":"Bu PR ne ekliyor?","options":["Fiyat ve kategori filtreleri","Yeni bir giriş sayfası","Ödeme sistemi"],"answer":0,"why_tr":"“adds price and category filters to the search page”"},{"q_tr":"Eski filtre API''si için doğru olan hangisi?","options":["Artık hiç çalışmıyor","Kullanımdan kaldırıldı ama hâlâ çalışıyor","Yeni eklendi"],"answer":1,"why_tr":"“deprecated but still works”"},{"q_tr":"Yazar incelemecilerden özellikle neye bakmalarını istiyor?","options":["Test kapsamına","filters.ts dosyasındaki adlandırmaya","Ödeme ekranına"],"answer":1,"why_tr":"“Please review the naming in filters.ts carefully.”"}]'::jsonb,2,'draft');
insert into public.readings (id,pack_id,title,kind,sentences,glossary,questions,difficulty,status) values ('2240d1ac-de85-5905-8160-6d603f57ae22','26515c63-3bd4-5d24-9fbd-336e392868a3','Review comments','Kod inceleme yorumları','[{"en":"Reviewer: Nice catch on the empty list case!","tr":"İnceleyen: Boş liste durumunu iyi yakalamışsın!"},{"en":"Reviewer: The API URL is hardcoded here. Could we read it from the config instead?","tr":"İnceleyen: API adresi burada koda sabit yazılmış. Bunun yerine yapılandırmadan okuyabilir miyiz?"},{"en":"Author: Good point, I''ve moved it to the config file.","tr":"Yazar: Haklısın, yapılandırma dosyasına taşıdım."},{"en":"Reviewer: There is also a merge conflict in package.json.","tr":"İnceleyen: package.json dosyasında bir birleştirme çakışması da var."},{"en":"Author: Fixed. Ready for another look.","tr":"Yazar: Düzelttim. Tekrar bakmaya hazır."}]'::jsonb,'[{"term":"nice catch","tr":"iyi yakaladın"},{"term":"hardcoded","tr":"koda sabit yazılmış"},{"term":"merge conflict","tr":"birleştirme çakışması"},{"term":"ready for another look","tr":"tekrar incelemeye hazır"}]'::jsonb,'[{"q_tr":"İnceleyen API adresiyle ilgili ne öneriyor?","options":["Adresi silmeyi","Adresi yapılandırmadan okumayı","Adresi başka bir dala taşımayı"],"answer":1,"why_tr":"“Could we read it from the config instead?”"},{"q_tr":"Konuşmanın sonunda durum ne?","options":["Yazar düzeltmeleri yaptı ve yeniden inceleme bekliyor","İnceleyen PR''ı reddetti","Çakışma hâlâ duruyor"],"answer":0,"why_tr":"“Fixed. Ready for another look.”"}]'::jsonb,2,'draft');
insert into public.readings (id,pack_id,title,kind,sentences,glossary,questions,difficulty,status) values ('70a8da23-056c-5361-b5aa-89fce2f65d48','8c6847cf-f469-5cd6-b2d7-4c15dbfd531a','Login fails after password reset','Hata kaydı','[{"en":"Title: Login fails after password reset.","tr":"Başlık: Parola sıfırlamadan sonra giriş başarısız oluyor."},{"en":"Steps to reproduce: reset the password from the email link, then log in with the new password.","tr":"Yeniden oluşturma adımları: parolayı e-postadaki bağlantıdan sıfırla, sonra yeni parolayla giriş yap."},{"en":"Expected result: the user sees the dashboard.","tr":"Beklenen sonuç: kullanıcı ana paneli görür."},{"en":"Actual result: an ''Invalid session'' error appears.","tr":"Gerçekleşen sonuç: “Geçersiz oturum” hatası çıkıyor."},{"en":"The issue is intermittent; it does not happen on every attempt.","tr":"Sorun aralıklı; her denemede olmuyor."}]'::jsonb,'[{"term":"steps to reproduce","tr":"yeniden oluşturma adımları"},{"term":"expected result","tr":"beklenen sonuç"},{"term":"actual result","tr":"gerçekleşen sonuç"},{"term":"intermittent","tr":"aralıklı"}]'::jsonb,'[{"q_tr":"Hata ne zaman ortaya çıkıyor?","options":["Parola sıfırlandıktan sonra yeni parolayla giriş yaparken","Kullanıcı kayıt olurken","Ana panel açıldığında"],"answer":0,"why_tr":"Adımlar: parolayı sıfırla, sonra yeni parolayla giriş yap."},{"q_tr":"“intermittent” bu kayıtta ne anlatıyor?","options":["Hata her denemede oluyor","Hata bazen oluyor, bazen olmuyor","Hata düzeltildi"],"answer":1,"why_tr":"“it does not happen on every attempt” = her denemede olmuyor."}]'::jsonb,2,'draft');
insert into public.readings (id,pack_id,title,kind,sentences,glossary,questions,difficulty,status) values ('a8f1b2bb-362c-5af5-9bfa-4afda7fd3bf4','8c6847cf-f469-5cd6-b2d7-4c15dbfd531a','README: Troubleshooting','README parçası','[{"en":"If the app does not start, check that Node 22 is installed.","tr":"Uygulama başlamazsa Node 22''nin kurulu olduğunu kontrol et."},{"en":"If you see a timeout error, increase REQUEST_TIMEOUT in the config file.","tr":"Zaman aşımı hatası görürsen yapılandırma dosyasındaki REQUEST_TIMEOUT değerini artır."},{"en":"The old login method is deprecated and will be removed in version 3.","tr":"Eski giriş yöntemi kullanımdan kaldırıldı ve 3. sürümde tamamen silinecek."},{"en":"Please include the full stack trace when you open an issue.","tr":"Bir sorun kaydı açarken lütfen tam yığın izini ekle."}]'::jsonb,'[{"term":"troubleshooting","tr":"sorun giderme"},{"term":"deprecated","tr":"kullanımdan kaldırılmış"},{"term":"stack trace","tr":"yığın izi"},{"term":"open an issue","tr":"sorun kaydı açmak"}]'::jsonb,'[{"q_tr":"Zaman aşımı hatası görürsen ne yapmalısın?","options":["Node''u kaldırmalısın","REQUEST_TIMEOUT değerini artırmalısın","Eski giriş yöntemini kullanmalısın"],"answer":1,"why_tr":"“increase REQUEST_TIMEOUT in the config file”"},{"q_tr":"Eski giriş yöntemi için ne söyleniyor?","options":["3. sürümde kaldırılacak","Yeni eklendi","Önerilen yöntem bu"],"answer":0,"why_tr":"“deprecated and will be removed in version 3”"}]'::jsonb,3,'draft');
insert into public.readings (id,pack_id,title,kind,sentences,glossary,questions,difficulty,status) values ('15bc6b33-a1d6-5fac-bff5-8f029a51b6dc','b2d05b0d-3f42-5152-8985-f7b28dde1bdb','Team chat: release update','Ekip mesajı','[{"en":"Hi team, here is a quick update on the 2.4 release.","tr":"Herkese merhaba, 2.4 sürümüyle ilgili kısa bir durum bilgisi."},{"en":"The search filters are done and merged.","tr":"Arama filtreleri bitti ve ana koda eklendi."},{"en":"The payment bug is still open, so we are not on track for Thursday.","tr":"Ödeme hatası hâlâ açık, bu yüzden perşembe için plana uygun değiliz."},{"en":"Our new estimate for the release is Monday.","tr":"Sürüm için yeni tahminimiz pazartesi."},{"en":"Ece is out of office tomorrow, so please send payment questions to Ali.","tr":"Ece yarın izinli, bu yüzden ödeme sorularını lütfen Ali''ye gönderin."}]'::jsonb,'[{"term":"merged","tr":"ana koda eklendi"},{"term":"on track","tr":"plana uygun"},{"term":"estimate","tr":"tahmin"},{"term":"out of office","tr":"izinli, ofis dışında"}]'::jsonb,'[{"q_tr":"Sürüm neden perşembeye yetişmiyor?","options":["Ödeme hatası hâlâ açık","Arama filtreleri bitmedi","Ece izinli"],"answer":0,"why_tr":"“The payment bug is still open, so we are not on track” cümlesi nedeni veriyor."},{"q_tr":"Yarın ödeme sorularını kime göndermelisin?","options":["Ece''ye","Ali''ye","Takım liderine"],"answer":1,"why_tr":"Ece izinli; sorular Ali''ye gönderilecek."},{"q_tr":"Sürüm için yeni tahmin hangi gün?","options":["Perşembe","Cuma","Pazartesi"],"answer":2,"why_tr":"“Our new estimate for the release is Monday.”"}]'::jsonb,2,'draft');
insert into public.readings (id,pack_id,title,kind,sentences,glossary,questions,difficulty,status) values ('7c7b5109-f52f-5671-9133-541403ef8aab','b2d05b0d-3f42-5152-8985-f7b28dde1bdb','Daily standup notes','Toplantı notu','[{"en":"Mert: Yesterday I fixed the login timeout.","tr":"Mert: Dün giriş zaman aşımını düzelttim."},{"en":"Today I''m working on the profile page.","tr":"Bugün profil sayfası üzerinde çalışıyorum."},{"en":"Selin: I''m stuck on a failing integration test.","tr":"Selin: Başarısız olan bir entegrasyon testinde takıldım."},{"en":"Mert will pair with her after the standup.","tr":"Mert toplantıdan sonra onunla eşli çalışacak."},{"en":"Action item: Selin will share the test logs in the team channel.","tr":"Yapılacak iş: Selin test kayıtlarını ekip kanalında paylaşacak."}]'::jsonb,'[{"term":"timeout","tr":"zaman aşımı"},{"term":"integration test","tr":"entegrasyon testi"},{"term":"action item","tr":"yapılacak iş"},{"term":"logs","tr":"kayıtlar"}]'::jsonb,'[{"q_tr":"Selin''in engeli ne?","options":["Profil sayfası","Başarısız bir entegrasyon testi","Giriş zaman aşımı"],"answer":1,"why_tr":"“I''m stuck on a failing integration test.”"},{"q_tr":"Toplantıdan sonra ne olacak?","options":["Mert ile Selin eşli çalışacak","Mert izne çıkacak","Selin profil sayfasını bitirecek"],"answer":0,"why_tr":"“Mert will pair with her after the standup.”"}]'::jsonb,1,'draft');
insert into public.readings (id,pack_id,title,kind,sentences,glossary,questions,difficulty,status) values ('ccb814ec-731a-5d20-80a3-26e92d0ebb45','2e27320a-9d7f-514d-b3d5-0606c1f40344','Working from home','Akademik paragraf','[{"en":"Working from home has become common in many countries.","tr":"Evden çalışma pek çok ülkede yaygınlaştı."},{"en":"Its main benefit is that employees save time because they do not commute.","tr":"Temel faydası, çalışanların işe gidip gelmedikleri için zaman kazanmasıdır."},{"en":"However, some workers feel isolated, and this can reduce their motivation.","tr":"Ancak bazı çalışanlar kendini yalnız hissediyor ve bu durum motivasyonlarını düşürebiliyor."},{"en":"Whereas large companies can offer online support, small firms often lack the resources to do so.","tr":"Büyük şirketler çevrim içi destek sunabilirken küçük firmalar çoğu zaman bunun için gereken kaynaklardan yoksun."},{"en":"Therefore, the impact of remote work depends partly on the size of the company.","tr":"Bu nedenle uzaktan çalışmanın etkisi kısmen şirketin büyüklüğüne bağlı."}]'::jsonb,'[{"term":"benefit","tr":"fayda"},{"term":"isolated","tr":"yalnız, yalıtılmış"},{"term":"lack","tr":"-den yoksun olmak"},{"term":"impact","tr":"etki"}]'::jsonb,'[{"q_tr":"Paragrafa göre evden çalışmanın bir sakıncası nedir?","options":["Çalışanların zaman kaybetmesi","Bazı çalışanların yalnız hissetmesi","Şirketlerin daha çok para harcaması"],"answer":1,"why_tr":"“some workers feel isolated, and this can reduce their motivation”"},{"q_tr":"“Whereas” ile başlayan cümle neyi karşılaştırıyor?","options":["Büyük ve küçük şirketlerin destek olanaklarını","Evden ve ofisten çalışmayı","Çalışanların yaşlarını"],"answer":0,"why_tr":"Büyük şirketlerin destek sunabildiği, küçük firmaların ise kaynaktan yoksun olduğu karşılaştırılıyor."},{"q_tr":"Paragraf hangi sonuca varıyor?","options":["Uzaktan çalışma herkes için kötüdür","Uzaktan çalışmanın etkisi şirket büyüklüğüne kısmen bağlıdır","Küçük firmalar uzaktan çalışmayı yasaklamalıdır"],"answer":1,"why_tr":"Son cümle “Therefore” ile bu sonucu veriyor."}]'::jsonb,3,'draft');
insert into public.readings (id,pack_id,title,kind,sentences,glossary,questions,difficulty,status) values ('bc1bc712-7e06-5814-b110-b5d99ad9e867','2e27320a-9d7f-514d-b3d5-0606c1f40344','Urban trees','Akademik paragraf','[{"en":"Trees play a crucial role in cities.","tr":"Ağaçlar şehirlerde çok önemli bir rol oynar."},{"en":"They reduce temperatures in summer and contribute to cleaner air.","tr":"Yazın sıcaklıkları düşürür ve havanın temizlenmesine katkıda bulunurlar."},{"en":"Despite these benefits, many cities cut down trees to build roads.","tr":"Bu faydalara rağmen pek çok şehir yol yapmak için ağaç kesiyor."},{"en":"This often leads to hotter streets and higher energy use for air conditioning.","tr":"Bu da çoğu zaman daha sıcak sokaklara ve klima için daha fazla enerji kullanımına yol açıyor."}]'::jsonb,'[{"term":"crucial","tr":"çok önemli"},{"term":"contribute to","tr":"katkıda bulunmak"},{"term":"despite","tr":"-e rağmen"},{"term":"lead to","tr":"yol açmak"}]'::jsonb,'[{"q_tr":"Paragrafa göre ağaç kesmenin bir sonucu nedir?","options":["Sokakların serinlemesi","Klima için daha fazla enerji kullanılması","Havanın temizlenmesi"],"answer":1,"why_tr":"“leads to hotter streets and higher energy use for air conditioning”"},{"q_tr":"“Despite these benefits” ifadesi neyi vurgular?","options":["Faydalara rağmen ağaçların kesildiğini","Faydaların az olduğunu","Ağaçların yol yapımına yardım ettiğini"],"answer":0,"why_tr":"“despite” karşıtlık bildirir: faydalar var ama ağaçlar yine de kesiliyor."}]'::jsonb,2,'draft');
insert into public.readings (id,pack_id,title,kind,sentences,glossary,questions,difficulty,status) values ('9990c561-55e2-510e-894e-674cdf92405d','e6ad2555-ff51-5462-82ce-6e582d7ec447','Daily internet use, 2010–2024','Grafik yorumu','[{"en":"The chart shows the proportion of adults who used the internet daily between 2010 and 2024.","tr":"Grafik, 2010 ile 2024 arasında interneti her gün kullanan yetişkinlerin oranını gösteriyor."},{"en":"In 2010, the figure was about 40%.","tr":"2010''da bu oran yaklaşık %40''tı."},{"en":"It rose steadily over the next decade and reached 80% in 2020.","tr":"Sonraki on yılda düzenli olarak arttı ve 2020''de %80''e ulaştı."},{"en":"Since then, it has risen slightly and leveled off at around 85%.","tr":"O zamandan beri biraz arttı ve yaklaşık %85''te sabitlendi."},{"en":"Overall, daily internet use more than doubled over the period.","tr":"Genel olarak günlük internet kullanımı bu dönemde iki katından fazla arttı."}]'::jsonb,'[{"term":"proportion","tr":"oran"},{"term":"steadily","tr":"düzenli olarak"},{"term":"leveled off","tr":"sabitlendi"},{"term":"overall","tr":"genel olarak"}]'::jsonb,'[{"q_tr":"2020''de oran neydi?","options":["%40","%80","%85"],"answer":1,"why_tr":"“reached 80% in 2020”"},{"q_tr":"Paragrafa göre hangisi doğrudur?","options":["Oran 2020''den sonra keskin biçimde düştü","Oran dönem boyunca iki katından fazla arttı","Oran hep %40 civarında kaldı"],"answer":1,"why_tr":"%40''tan yaklaşık %85''e çıkmış: “more than doubled”."}]'::jsonb,3,'draft');
insert into public.readings (id,pack_id,title,kind,sentences,glossary,questions,difficulty,status) values ('7a23badc-fa8c-5652-b810-3831f3233e93','e6ad2555-ff51-5462-82ce-6e582d7ec447','Birth rates in developed countries','Akademik paragraf','[{"en":"In many developed countries, birth rates have declined over the last fifty years.","tr":"Pek çok gelişmiş ülkede doğum oranları son elli yılda düştü."},{"en":"This trend is mainly attributed to higher education levels and the rising cost of raising children.","tr":"Bu eğilim esas olarak daha yüksek eğitim düzeylerine ve çocuk yetiştirmenin artan maliyetine bağlanıyor."},{"en":"As a result, the proportion of older people in the population has increased.","tr":"Sonuç olarak nüfus içindeki yaşlıların oranı arttı."},{"en":"Some governments now offer financial support to families; however, its effect has been limited so far.","tr":"Bazı hükümetler artık ailelere maddi destek sunuyor; ancak bunun etkisi şimdiye kadar sınırlı kaldı."}]'::jsonb,'[{"term":"birth rate","tr":"doğum oranı"},{"term":"attributed to","tr":"-e bağlanan"},{"term":"proportion","tr":"oran"},{"term":"so far","tr":"şimdiye kadar"}]'::jsonb,'[{"q_tr":"Paragrafa göre doğum oranlarındaki düşüşün bir nedeni nedir?","options":["Daha yüksek eğitim düzeyleri","Yaşlı nüfusun azalması","Devlet desteğinin artması"],"answer":0,"why_tr":"“mainly attributed to higher education levels and the rising cost of raising children”"},{"q_tr":"Devletlerin maddi desteği hakkında ne söyleniyor?","options":["Doğum oranlarını iki katına çıkardı","Etkisi şimdiye kadar sınırlı kaldı","Hiç uygulanmadı"],"answer":1,"why_tr":"“its effect has been limited so far”"},{"q_tr":"“As a result” ile başlayan cümle neyi anlatıyor?","options":["Düşen doğum oranlarının bir sonucunu","Bir karşıtlığı","Bir örneği"],"answer":0,"why_tr":"“As a result” sonuç bildirir: yaşlı nüfusun oranı arttı."}]'::jsonb,3,'draft');
insert into public.readings (id,pack_id,title,kind,sentences,glossary,questions,difficulty,status) values ('ae99d991-6b78-5184-ad8b-95397fedf2a7','de1b4712-7243-59d2-b591-86fd886a91fd','Sleep and memory','Akademik paragraf','[{"en":"Many studies have examined the link between sleep and memory.","tr":"Pek çok çalışma uyku ile hafıza arasındaki bağlantıyı incelemiştir."},{"en":"In a recent study, researchers asked 120 participants to learn a list of words before going to bed.","tr":"Yakın tarihli bir çalışmada araştırmacılar 120 katılımcıdan yatmadan önce bir kelime listesi öğrenmelerini istedi."},{"en":"Participants who slept at least seven hours remembered more words the next day.","tr":"En az yedi saat uyuyan katılımcılar ertesi gün daha fazla kelime hatırladı."},{"en":"However, the authors note that the sample consisted only of university students.","tr":"Ancak yazarlar, örneklemin yalnızca üniversite öğrencilerinden oluştuğunu belirtiyor."},{"en":"Thus, further research is needed before the results can be generalized.","tr":"Bu nedenle sonuçlar genellenmeden önce daha fazla araştırma gerekiyor."}]'::jsonb,'[{"term":"examine","tr":"incelemek"},{"term":"participant","tr":"katılımcı"},{"term":"sample","tr":"örneklem"},{"term":"generalize","tr":"genellemek"}]'::jsonb,'[{"q_tr":"Paragrafa göre aşağıdakilerden hangisi doğrudur?","options":["Daha uzun uyuyan katılımcılar daha fazla kelime hatırladı","Katılımcılar farklı yaş gruplarından seçildi","Sonuçlar herkese genellenebilir"],"answer":0,"why_tr":"“Participants who slept at least seven hours remembered more words.” Diğer iki seçenek paragrafla çelişiyor."},{"q_tr":"Yazarlar neden temkinli?","options":["Çalışma çok uzun sürdü","Örneklem yalnızca üniversite öğrencilerinden oluşuyordu","Kelime listesi çok kısaydı"],"answer":1,"why_tr":"“the sample consisted only of university students”"},{"q_tr":"Son cümledeki “Thus” hangi ilişkiyi kuruyor?","options":["Karşıtlık","Sonuç","Örnekleme"],"answer":1,"why_tr":"“Thus” = bu nedenle; önceki cümledeki kısıtlılığın sonucunu bildiriyor."}]'::jsonb,3,'draft');
insert into public.readings (id,pack_id,title,kind,sentences,glossary,questions,difficulty,status) values ('bd56a350-4163-56da-9d14-9665fe501261','de1b4712-7243-59d2-b591-86fd886a91fd','Online learning survey','Akademik paragraf','[{"en":"A survey of 1,500 university students was conducted in 2023.","tr":"2023''te 1.500 üniversite öğrencisiyle bir anket yapıldı."},{"en":"About 70% of respondents said they preferred online lectures, which they could watch at any time.","tr":"Yanıt verenlerin yaklaşık %70''i, istedikleri zaman izleyebildikleri çevrim içi dersleri tercih ettiğini söyledi."},{"en":"Yet many of them also reported feeling less connected to their classmates.","tr":"Yine de birçoğu sınıf arkadaşlarına daha az bağlı hissettiğini de bildirdi."},{"en":"The authors claim that universities should combine online and face-to-face teaching.","tr":"Yazarlar, üniversitelerin çevrim içi ve yüz yüze öğretimi birleştirmesi gerektiğini ileri sürüyor."}]'::jsonb,'[{"term":"survey","tr":"anket"},{"term":"respondent","tr":"yanıt veren kişi"},{"term":"yet","tr":"yine de, ancak"},{"term":"claim","tr":"ileri sürmek"}]'::jsonb,'[{"q_tr":"Paragrafa göre öğrencilerin çoğu çevrim içi dersleri neden tercih ediyor?","options":["Dersler daha kısa olduğu için","Dersleri istedikleri zaman izleyebildikleri için","Hocalar daha iyi olduğu için"],"answer":1,"why_tr":"“online lectures, which they could watch at any time”"},{"q_tr":"Yazarlar ne öneriyor?","options":["Yalnızca çevrim içi öğretim","Çevrim içi ve yüz yüze öğretimin birleştirilmesi","Yüz yüze öğretimin kaldırılması"],"answer":1,"why_tr":"“combine online and face-to-face teaching”"}]'::jsonb,3,'draft');
insert into public.writing_tasks (id,pack_id,prompt_tr,rubric,sample_answers,difficulty,status) values ('4870d590-aef7-5e55-970b-b51ec745a32c','6fbbf6ec-47c4-5a61-ae2a-085acb973117','Bir teknik sorunu ve iki olası çözümü 3–4 cümleyle anlat; birini öner ve nedenini söyle.','["Sorunu “The problem is that …” ile tanımlıyor","İki seçeneği “One option is to … / Another option is to …” ile sunuyor","Önerisini gerekçesiyle ve doğru yapıyla (suggest that / recommend -ing) yapıyor"]'::jsonb,array['The problem is that the motor overheats after an hour. One option is to add a second fan, and another option is to use a bigger motor. I suggest that we add a fan, because it is cheaper and faster. If we do this, the temperature will drop by about 10 degrees.']::text[],3,'draft');
insert into public.writing_tasks (id,pack_id,prompt_tr,rubric,sample_answers,difficulty,status) values ('8494e6e8-77c2-57a2-bac8-ff04a6bdda38','c016cb37-6858-58cd-ae01-49689b107921','Bir ürünün 3–4 temel teknik özelliğini İngilizce yaz (boyut, ağırlık, malzeme, çalışma değeri) ve onu eski modelle karşılaştır.','["Ölçüleri doğru biçimde veriyor (by, per, up to)","Malzemeyi “made of” ile söylüyor","Karşılaştırma için -er/more … than ya da compared to kullanıyor"]'::jsonb,array['The new sensor measures 40 by 20 mm and weighs 35 grams. It is made of aluminum and operates at 5 volts. Compared to the old model, it is lighter and more accurate.']::text[],2,'draft');
insert into public.writing_tasks (id,pack_id,prompt_tr,rubric,sample_answers,difficulty,status) values ('b20981e0-eb47-5623-ae5b-476cf1cd98f6','233b0925-1efe-5baa-9090-54d6f8aef7d6','Bir testin sonucunu 3–4 cümleyle özetle: ne test edildi, hangi koşulda, sonuç ne ve önerin ne?','["Test koşulunu (sıcaklık, yük, süre) veriyor","Sonucu sayılarla ve geçmiş zamanla anlatıyor","Öneriyi “We recommend …-ing” ile yapıyor"]'::jsonb,array['We tested five prototypes at full load for 48 hours. Four prototypes passed the test, but one failed after 30 hours because of overheating. We recommend using a larger fan in the next design.']::text[],3,'draft');
insert into public.writing_tasks (id,pack_id,prompt_tr,rubric,sample_answers,difficulty,status) values ('e68fd1ea-71a0-547d-94cf-5b38c4d6bcb7','1ec86e14-8694-5f09-89f1-2ad9ef7f19f5','Bir arkadaşına 3–4 cümlelik bir mesaj yaz: hafta sonu planını anlat ve onu bir etkinliğe davet et.','["Planını “I''m going to …” ile anlatıyor","Daveti “How about …?” veya “Are you free …?” ile yapıyor","Somut bir gün, saat veya yer veriyor"]'::jsonb,array['Hi Ece! I''m going to clean the house on Saturday morning, but I''m free in the afternoon. How about going to the new café in Moda at three? Let me know if you''re free!']::text[],2,'draft');
insert into public.writing_tasks (id,pack_id,prompt_tr,rubric,sample_answers,difficulty,status) values ('df4acf57-9455-5f4c-b038-ce63a2d91236','2fe5da34-f4cb-5c47-8c4e-d94faab76c7f','Kendini 3–4 cümleyle tanıt: nerelisin, ne iş yapıyorsun, boş zamanında neler yaparsın?','["Adını ve nereli olduğunu söylüyor","Mesleğini veya okulunu “I''m a …” ya da “I work at …” ile anlatıyor","Bir ilgi alanını “I like …-ing” ile anlatıyor"]'::jsonb,array['Hi, I''m Deniz. I''m originally from Bursa, but I''ve lived in İstanbul for three years. I work at a small software company. In my spare time, I like cooking and playing tennis.']::text[],1,'draft');
insert into public.writing_tasks (id,pack_id,prompt_tr,rubric,sample_answers,difficulty,status) values ('1e0666e5-1431-5000-810e-05877917e678','9fec7c37-b21c-53df-8fc9-49684d6cfa85','Bir mağazaya ya da otele 3–4 cümlelik kibar bir şikâyet mesajı yaz: sorun ne, ne zaman oldu ve ne istiyorsun?','["Sorunu ve ne zaman olduğunu açıkça anlatıyor","İsteğini “I''d like …” ile kibarca söylüyor","Kaba veya suçlayıcı ifade kullanmıyor"]'::jsonb,array['Hello, I bought a lamp from your store last week, but it doesn''t work. I tried different sockets, but it still doesn''t turn on. I''d like to exchange it for a new one. I still have the receipt.']::text[],2,'draft');
insert into public.writing_tasks (id,pack_id,prompt_tr,rubric,sample_answers,difficulty,status) values ('a0d7cfe7-527b-57d1-ad1c-545db1c9bff4','26515c63-3bd4-5d24-9fbd-336e392868a3','Bir PR''a 2–3 cümlelik nazik bir inceleme yorumu yaz: bir şeyi beğen, bir değişiklik öner ve nedenini söyle.','["Olumlu bir geri bildirimle başlıyor","Öneriyi “could / maybe / what about” gibi nazik bir kalıpla yapıyor","Önerinin nedenini açıklıyor"]'::jsonb,array['Nice work on the search filters! One suggestion: the API URL is hardcoded, so maybe we could read it from the config file. This would make it easier to change per environment.']::text[],3,'draft');
insert into public.writing_tasks (id,pack_id,prompt_tr,rubric,sample_answers,difficulty,status) values ('29475f0b-7aa1-5143-8f3f-bee9b08d44ea','8c6847cf-f469-5cd6-b2d7-4c15dbfd531a','Bir hata kaydı için 3–4 cümle yaz: ne oluyor, nasıl yeniden oluşturulur, beklenen ve gerçekleşen sonuç ne?','["Hatayı tek cümlede net anlatıyor","Yeniden oluşturma adımlarını sırayla veriyor","Beklenen ve gerçekleşen sonucu ayırıyor"]'::jsonb,array['The app crashes when I upload a PDF larger than 10 MB. Steps to reproduce: open the Files page and upload a large PDF. Expected result: the file is uploaded. Actual result: the app closes without an error message.']::text[],3,'draft');
insert into public.writing_tasks (id,pack_id,prompt_tr,rubric,sample_answers,difficulty,status) values ('2fa1d240-3f90-5d15-a724-2cce18b46d92','b2d05b0d-3f42-5152-8985-f7b28dde1bdb','Günlük toplantı için 3–4 cümlelik bir durum mesajı yaz: dün ne yaptın, bugün ne yapacaksın, bir engelin var mı?','["Dün için geçmiş zaman kullanılmış","Bugün için “I''m going to” veya “I''m working on” kullanılmış","Engel varsa açıkça ve bir yardım isteğiyle söylenmiş"]'::jsonb,array['Yesterday I finished the search filters. Today I''m working on the unit tests. My only blocker is the missing API key. Could someone from the backend team help me?']::text[],2,'draft');
insert into public.writing_tasks (id,pack_id,prompt_tr,rubric,sample_answers,difficulty,status) values ('9bafc039-b2cc-5323-bc2b-d0fa86a98db8','2e27320a-9d7f-514d-b3d5-0606c1f40344','Bir konu hakkında 3 cümle yaz: bir faydasını, bir sakıncasını ve bir sonucunu bağlaçlarla bağla (however, therefore, although …).','["Bir fayda ve bir sakınca belirtiyor","En az bir karşıtlık bağlacını doğru kullanıyor","En az bir sonuç bağlacını doğru kullanıyor"]'::jsonb,array['Online courses are flexible, so students can study at any time. However, some students find it hard to stay motivated. Therefore, many universities combine online and face-to-face classes.']::text[],3,'draft');
insert into public.writing_tasks (id,pack_id,prompt_tr,rubric,sample_answers,difficulty,status) values ('daf183e6-28f0-5e58-a6c6-c40097d66d43','e6ad2555-ff51-5462-82ce-6e582d7ec447','Bir grafiği veya eğilimi 3 cümleyle anlat: başlangıç değeri, değişim ve son durum.','["Başlangıç ve son değeri “from … to” veya “reach” ile veriyor","Değişimi zarf veya sıfatla niteliyor (steadily, sharp, slight)","Etkisi süren değişim için present perfect kullanıyor"]'::jsonb,array['In 2015, about 30% of people shopped online. The figure rose steadily and reached a peak of 70% in 2021. Since then, it has leveled off at around 68%.']::text[],3,'draft');
insert into public.writing_tasks (id,pack_id,prompt_tr,rubric,sample_answers,difficulty,status) values ('6494c65d-f55d-589d-b142-7752f016501d','de1b4712-7243-59d2-b591-86fd886a91fd','Okuduğun bir araştırmayı 2–3 akademik cümleyle özetle: amacı, temel bulgusu ve bir kısıtlılığı.','["Amacı “The aim of this study was to …” gibi bir kalıpla veriyor","Bulguyu temkinli bir raporlama fiiliyle (suggest, indicate) aktarıyor","Bir kısıtlılığı ve sonucunu belirtiyor"]'::jsonb,array['The aim of this study was to examine the link between sleep and memory. The results suggest that participants who sleep longer remember more words. However, the sample consisted only of students, so further research is needed.']::text[],3,'draft');
